(window.YC_CS_BANK=window.YC_CS_BANK||[]).push({id:"cs-3419",module:"changshi",prompt:"用人单位对小额、标准明确的仲裁裁决不服的，可以在多久内向人民法院申请撤销裁决？",options:["30日内", "15日内", "60日内", "6个月内"],answer:0,explanation:"用人单位有证据证明终局裁决存在法定情形的，可以自收到仲裁裁决书之日起30日内向劳动争议仲裁委员会所在地的中级人民法院申请撤销裁决。"},{id:"cs-3420",module:"changshi",prompt:"终局裁决的适用范围不包括？",options:["确认劳动关系争议", "追索劳动报酬、工伤医疗费、经济补偿或者赔偿金，不超过当地月最低工资标准12个月金额的争议", "因执行国家的劳动标准在工作时间、休息休假、社会保险等方面发生的争议", "小额金钱给付争议"],answer:0,explanation:"终局裁决适用于小额金钱给付争议和因执行国家劳动标准在工作时间、休息休假、社会保险等方面发生的争议；确认劳动关系的争议不属于终局裁决范围。"},{id:"cs-3421",module:"changshi",prompt:"劳动争议仲裁不收费，费用由？",options:["财政保障", "败诉方承担", "双方分担", "工会承担"],answer:0,explanation:"劳动争议仲裁不收费，劳动争议仲裁委员会的经费由财政予以保障。"},{id:"cs-3422",module:"changshi",prompt:"劳动争议仲裁时效的中断事由不包括？",options:["仲裁时效期间届满", "向对方当事人主张权利", "向有关部门请求权利救济", "对方当事人同意履行义务"],answer:0,explanation:"劳动争议仲裁时效因当事人一方向对方当事人主张权利，或者向有关部门请求权利救济，或者对方当事人同意履行义务而中断；时效期间届满是时效完成的情形，不是中断事由。"},{id:"cs-3423",module:"changshi",prompt:"因不可抗力等正当理由耽误仲裁时效的，仲裁时效？",options:["中止", "中断", "延长", "终止"],answer:0,explanation:"因不可抗力或者有其他正当理由，当事人不能在仲裁时效期间申请仲裁的，仲裁时效中止，从中止时效的原因消除之日起，仲裁时效期间继续计算。"},{id:"cs-3424",module:"changshi",prompt:"劳动关系存续期间因拖欠劳动报酬发生争议的，劳动者申请仲裁？",options:["不受仲裁时效期间1年的限制", "受1年限制", "受6个月限制", "受2年限制"],answer:0,explanation:"劳动关系存续期间因拖欠劳动报酬发生争议的，劳动者申请仲裁不受仲裁时效期间1年的限制；但劳动关系终止的，应当自劳动关系终止之日起1年内提出。"},{id:"cs-3425",module:"changshi",prompt:"劳动争议调解委员会的调解协议？",options:["具有合同性质，对双方有约束力，但不具有强制执行力", "具有强制执行力", "没有约束力", "由法院强制执行"],answer:0,explanation:"劳动争议调解委员会达成的调解协议具有合同性质，对双方当事人具有约束力，但不具有强制执行力，一方不履行的，另一方可以申请仲裁。"},{id:"cs-3426",module:"changshi",prompt:"劳动保障监察的对象是？",options:["用人单位", "劳动者", "工会", "政府机关"],answer:0,explanation:"劳动保障监察是劳动行政部门对用人单位遵守劳动保障法律法规的情况进行监督检查的制度。"},{id:"cs-3427",module:"changshi",prompt:"用人单位违反劳动保障法律法规，劳动行政部门可以采取的措施不包括？",options:["直接追究刑事责任", "责令改正", "行政处罚", "责令支付赔偿金"],answer:0,explanation:"劳动行政部门对用人单位违反劳动保障法律法规的行为，可以责令改正、给予行政处罚等；追究刑事责任由司法机关进行。"},{id:"cs-3428",module:"changshi",prompt:"拖欠农民工工资的清偿责任由？",options:["用人单位承担，违法发包、转包的由具备用工主体资格的单位承担清偿责任", "仅包工头承担", "政府承担", "劳动者自担"],answer:0,explanation:"《保障农民工工资支付条例》规定，用人单位拖欠农民工工资的，应当依法予以清偿；工程建设领域违法发包、转包的，由具备用工主体资格的发包、转包单位承担清偿责任。"},{id:"cs-3429",module:"changshi",prompt:"反垄断法规定，垄断协议的豁免情形不包括？",options:["损害消费者利益的行为", "为改进技术、研究开发新产品", "为提高产品质量、降低成本", "为保障对外贸易中的正当利益"],answer:0,explanation:"反垄断法规定的豁免情形包括为改进技术、研究开发新产品，为提高产品质量、降低成本、增进效率，为保障对外贸易中的正当利益等；损害消费者利益的行为不能豁免。"},{id:"cs-3430",module:"changshi",prompt:"认定经营者具有市场支配地位的因素不包括？",options:["经营者的个人品德", "该经营者在相关市场的市场份额及竞争状况", "该经营者控制销售市场或者原材料采购市场的能力", "其他经营者对该经营者在交易上的依赖程度"],answer:0,explanation:"认定经营者具有市场支配地位的因素包括市场份额、控制市场的能力、财力和技术条件、其他经营者的依赖程度、进入难易程度等；个人品德不是认定因素。"},{id:"cs-3431",module:"changshi",prompt:"可以推定经营者具有市场支配地位的市场份额标准不包括？",options:["两个经营者合计市场份额低于1/10", "一个经营者市场份额达到1/2", "两个经营者合计达到2/3", "三个经营者合计达到3/4"],answer:0,explanation:"一个经营者市场份额达到1/2、两个达到2/3、三个达到3/4的，可以推定具有市场支配地位；但份额不足1/10的经营者不推定具有支配地位。"},{id:"cs-3432",module:"changshi",prompt:"消费者权益保护法规定，经营者提供的商品或者服务不符合质量要求的，消费者可以？",options:["依照国家规定、当事人约定退货，或者要求经营者履行更换、修理等义务", "只能修理", "只能更换", "只能索赔"],answer:0,explanation:"经营者提供的商品或者服务不符合质量要求的，消费者可以依照国家规定、当事人约定退货，或者要求经营者履行更换、修理等义务；没有国家规定和当事人约定的，消费者可以自收到商品之日起7日内退货。"},{id:"cs-3433",module:"changshi",prompt:"消费者权益保护法规定，经营者采用网络、电视等方式销售商品，消费者无理由退货的商品应当？",options:["完好", "已使用", "已损坏", "已拆封"],answer:0,explanation:"消费者退货的商品应当完好，退回商品的运费由消费者承担，经营者和消费者另有约定的除外。"},{id:"cs-3434",module:"changshi",prompt:"产品质量法规定，生产者不得生产？",options:["国家明令淘汰的产品", "合格产品", "优质产品", "出口产品"],answer:0,explanation:"生产者不得生产国家明令淘汰的产品，不得伪造产地，不得伪造或者冒用他人的厂名、厂址，不得伪造或者冒用认证标志等质量标志。"},{id:"cs-3435",module:"changshi",prompt:"广告法规定，广告应当具有可识别性，能够使消费者辨明其为广告，大众传播媒介不得以什么形式变相发布广告？",options:["新闻报道", "广告栏目", "专题节目", "公益广告"],answer:0,explanation:"广告应当具有可识别性，大众传播媒介不得以新闻报道形式变相发布广告，通过大众传播媒介发布的广告应当显著标明广告。"},{id:"cs-3436",module:"changshi",prompt:"广告法规定，药品广告不得含有的内容不包括？",options:["药品通用名称", "表示功效的断言或者保证", "利用广告代言人作推荐、证明", "说明治愈率或者有效率"],answer:0,explanation:"药品广告不得含有表示功效、安全性的断言或者保证，不得说明治愈率或者有效率，不得利用广告代言人作推荐、证明；标明药品通用名称是允许的。"},{id:"cs-3437",module:"changshi",prompt:"电子商务法规定，电子商务经营者应当向消费者出具？",options:["购货凭证或者服务单据、电子发票等", "仅口头承诺", "仅收据", "无需凭证"],answer:0,explanation:"电子商务经营者销售商品或者提供服务，应当依法出具纸质发票或者电子发票等购货凭证或者服务单据。"},{id:"cs-3438",module:"changshi",prompt:"电子商务法规定，平台内经营者提交的身份、地址、联系方式、行政许可等信息，平台应当？",options:["进行核验、登记，并定期核验更新", "仅登记不核验", "无需登记", "由消费者核验"],answer:0,explanation:"电子商务平台经营者应当要求申请进入平台销售商品或者提供服务的经营者提交其身份、地址、联系方式、行政许可等真实信息，进行核验、登记，建立登记档案，并定期核验更新。"},{id:"cs-3439",module:"changshi",prompt:"税收征收管理法规定，纳税人可以依照法律、行政法规的规定？",options:["书面申请减税、免税", "口头申请免税", "自行减免", "拒绝纳税"],answer:0,explanation:"纳税人可以依照法律、行政法规的规定书面申请减税、免税；减税、免税的申请须经法律、行政法规规定的审查批准机关审批。"},{id:"cs-3440",module:"changshi",prompt:"税收征收管理法规定，税务机关征收税款时，必须给纳税人开具？",options:["完税凭证", "收据", "发票", "证明"],answer:0,explanation:"税务机关征收税款时，必须给纳税人开具完税凭证。"},{id:"cs-3441",module:"changshi",prompt:"银行业监督管理机构的监管职责不包括？",options:["直接经营银行业务", "制定审慎经营规则", "审批银行业金融机构的设立", "对银行业金融机构进行现场检查"],answer:0,explanation:"银行业监督管理机构负责制定审慎经营规则、审批机构设立、进行现场检查等；不得直接经营银行业务。"},{id:"cs-3442",module:"changshi",prompt:"民事诉讼中，书证提交的原始文书优先于？",options:["复印件", "照片", "扫描件", "电子版"],answer:0,explanation:"书证应当提交原件，提交原件确有困难的，可以提交复制品、照片、副本、节录本。"},{id:"cs-3443",module:"changshi",prompt:"民事诉讼中，证据的质证是指？",options:["当事人对证据的真实性、关联性、合法性进行质疑和说明", "法官审查证据", "律师宣读证据", "书记员记录证据"],answer:0,explanation:"质证是当事人在法庭上对证据的真实性、关联性、合法性进行质疑、说明和辩驳的活动。"},{id:"cs-3444",module:"changshi",prompt:"民事诉讼中，未经质证的证据？",options:["不得作为认定案件事实的依据（当事人明确放弃质证权利的除外）", "可以作为依据", "由法院决定", "一律无效"],answer:0,explanation:"证据应当在法庭上出示，并由当事人互相质证；未经质证的证据，不得作为认定案件事实的依据。"},{id:"cs-3445",module:"changshi",prompt:"民事诉讼中，下列证据中证明力最强的一般是？",options:["公文书证", "当事人陈述", "证人证言", "利害关系人的证言"],answer:0,explanation:"国家机关或者其他依法具有社会管理职能的组织制作的公文书证的证明力一般大于其他书证；证人证言的证明力相对较弱。"},{id:"cs-3446",module:"changshi",prompt:"民事诉讼中，下列事实无需举证证明的是？",options:["自然规律以及定理、定律", "合同约定", "当事人主张", "证人陈述"],answer:0,explanation:"自然规律以及定理、定律，众所周知的事实，依法推定的事实，根据日常生活经验法则推定的事实等，无需举证证明。"},{id:"cs-3447",module:"changshi",prompt:"民事诉讼中，自认是指？",options:["一方当事人在法庭审理中或起诉状、答辩状中承认对方主张的不利于己的事实", "承认违法", "承认债务", "承认责任"],answer:0,explanation:"自认是一方当事人在诉讼过程中承认对方当事人主张的不利于自己的事实；自认的事实，对方当事人无需举证证明。"},{id:"cs-3448",module:"changshi",prompt:"民事诉讼中，涉及身份关系的事实？",options:["不适用自认", "适用自认", "由法院认定", "由鉴定认定"],answer:0,explanation:"涉及身份关系、国家利益、社会公共利益等应当由人民法院依职权调查的事实，不适用自认。"},{id:"cs-3449",module:"changshi",prompt:"民事诉讼中，鉴定人应当出庭作证的情形是？",options:["当事人对鉴定意见有异议或者人民法院认为鉴定人应当出庭的", "所有鉴定", "从不", "由鉴定人决定"],answer:0,explanation:"当事人对鉴定意见有异议或者人民法院认为鉴定人应当出庭的，鉴定人应当出庭作证；经通知拒不出庭的，鉴定意见不得作为认定事实的依据。"},{id:"cs-3450",module:"changshi",prompt:"民事诉讼中，证人因出庭作证支出的费用由？",options:["败诉方承担（当事人申请的由申请人预交）", "证人自担", "法院承担", "国家财政"],answer:0,explanation:"证人因履行出庭作证义务而支出的交通、住宿、就餐等必要费用以及误工损失，由败诉一方当事人承担。"},{id:"cs-3451",module:"changshi",prompt:"民事诉讼中，电子数据的载体不包括？",options:["纸质信件", "手机短信", "电子邮件", "微信聊天记录"],answer:0,explanation:"电子数据是指通过电子邮件、电子数据交换、网上聊天记录、博客、微博客、手机短信、电子签名、域名等形成或者存储在电子介质中的信息。"},{id:"cs-3452",module:"changshi",prompt:"民事诉讼中，证明责任的分配原则是？",options:["谁主张，谁举证", "谁被告，谁举证", "谁原告，谁举证", "谁弱者，谁举证"],answer:0,explanation:"民事诉讼中证明责任分配的一般原则是谁主张、谁举证；法律规定的特殊侵权等情形除外。"},{id:"cs-3453",module:"changshi",prompt:"民事诉讼中，举证期限由？",options:["人民法院指定或者当事人协商并经法院准许", "当事人自行决定", "律师决定", "无期限"],answer:0,explanation:"人民法院应当在送达案件受理通知书和应诉通知书的同时，向当事人送达举证通知书，指定举证期限；当事人协商一致的，经人民法院准许。"},{id:"cs-3454",module:"changshi",prompt:"民事诉讼中，逾期提供证据的，人民法院应当责令其说明理由；理由不成立的，人民法院可以？",options:["不予采纳该证据，或者采纳该证据但予以训诫、罚款", "一律采纳", "一律不予采纳", "中止审理"],answer:0,explanation:"当事人逾期提供证据的，人民法院应当责令其说明理由；拒不说明理由或者理由不成立的，人民法院根据不同情形可以不予采纳该证据，或者采纳该证据但予以训诫、罚款。"},{id:"cs-3455",module:"changshi",prompt:"民事诉讼中，证据保全的申请时间可以是？",options:["诉讼前或诉讼中", "仅诉讼前", "仅诉讼中", "仅判决后"],answer:0,explanation:"在证据可能灭失或者以后难以取得的情况下，当事人可以在诉讼过程中申请证据保全，利害关系人也可以在提起诉讼或者申请仲裁前申请证据保全。"},{id:"cs-3456",module:"changshi",prompt:"民事诉讼中，人民法院对证据的审查判断标准是？",options:["真实性、关联性、合法性", "完整性、及时性、有效性", "充分性、必要性、合理性", "客观性、主观性、中性"],answer:0,explanation:"人民法院对证据的审查判断标准是证据的真实性、关联性和合法性。"},{id:"cs-3457",module:"changshi",prompt:"全面依法治国的基本格局是？",options:["科学立法、严格执法、公正司法、全民守法", "有法可依、有法必依、执法必严、违法必究", "立法、执法、司法、守法", "依法行政、公正司法"],answer:0,explanation:"全面依法治国的基本格局是科学立法、严格执法、公正司法、全民守法。"},{id:"cs-3458",module:"changshi",prompt:"全面依法治国的基本要求是？",options:["有法可依、有法必依、执法必严、违法必究", "科学立法、严格执法", "公正司法、全民守法", "依法治国、依法执政"],answer:0,explanation:"全面依法治国的基本要求是有法可依、有法必依、执法必严、违法必究。"},{id:"cs-3459",module:"changshi",prompt:"全面依法治国的主体是？",options:["人民", "政府", "政党", "法院"],answer:0,explanation:"依法治国的主体是人民，人民在党的领导下依法管理国家事务。"},{id:"cs-3460",module:"changshi",prompt:"我国宪法规定的司法独立是指？",options:["人民法院依照法律规定独立行使审判权，不受行政机关、社会团体和个人的干涉", "法院不受党的领导", "法官个人独立", "司法不受监督"],answer:0,explanation:"司法独立是指人民法院、人民检察院依照法律规定独立行使审判权、检察权，不受行政机关、社会团体和个人的干涉。"},{id:"cs-3461",module:"changshi",prompt:"法治理论认为，法律的生命力在于？",options:["实施", "制定", "修改", "废止"],answer:0,explanation:"法律的生命力在于实施，法律的权威也在于实施。"},{id:"cs-3462",module:"changshi",prompt:"法治理论认为，法律的权威源自？",options:["人民的内心拥护和真诚信仰", "国家的强制力", "政府的宣传", "媒体的报道"],answer:0,explanation:"法律的权威源自人民的内心拥护和真诚信仰。"},{id:"cs-3463",module:"changshi",prompt:"法治思维的基本内容包括？",options:["规则思维、权利思维、程序思维、责任思维", "权力思维", "人治思维", "经验思维"],answer:0,explanation:"法治思维的基本内容包括规则思维、权利思维、程序思维、责任思维等。"},{id:"cs-3464",module:"changshi",prompt:"法律权利的实现依赖于？",options:["义务的履行", "国家的强制", "个人的自觉", "道德的约束"],answer:0,explanation:"法律权利的实现依赖于义务的履行，义务是权利实现的保障。"},{id:"cs-3465",module:"changshi",prompt:"我国法律体系的基本框架包括？",options:["宪法及宪法相关法、民法商法、行政法、经济法、社会法、刑法、诉讼与非诉讼程序法", "仅宪法和民法", "仅刑法和诉讼法", "仅经济法和行政法"],answer:0,explanation:"我国法律体系的基本框架包括宪法及宪法相关法、民法商法、行政法、经济法、社会法、刑法、诉讼与非诉讼程序法七个法律部门。"},{id:"cs-3466",module:"changshi",prompt:"在我国法律体系中，民商法调整的是？",options:["平等主体之间的人身关系和财产关系", "行政关系", "刑事关系", "劳动关系"],answer:0,explanation:"民商法调整平等主体之间的人身关系和财产关系。"},{id:"cs-3467",module:"changshi",prompt:"在我国法律体系中，社会法调整的是？",options:["劳动关系、社会保障和社会福利关系", "平等主体之间的财产关系", "行政关系", "刑事关系"],answer:0,explanation:"社会法是调整劳动关系、社会保障和社会福利关系的法律规范的总和。"},{id:"cs-3468",module:"changshi",prompt:"诉讼与非诉讼程序法调整的是？",options:["解决社会纠纷的诉讼活动或非诉讼活动", "实体权利义务", "行政关系", "劳动关系"],answer:0,explanation:"诉讼与非诉讼程序法是调整解决社会纠纷的诉讼活动或非诉讼活动的法律规范的总和。"});
(window.YC_CS_BANK=window.YC_CS_BANK||[]).push({id:"cs-3469",module:"changshi",prompt:"根据民法典，结婚的法定条件不包括？",options:["必须门当户对", "达到法定婚龄", "男女双方完全自愿", "符合一夫一妻制"],answer:0,explanation:"结婚的法定条件包括男女双方完全自愿、达到法定婚龄（男22周岁、女20周岁）、符合一夫一妻制、不属于禁止结婚的情形。"},{id:"cs-3470",module:"changshi",prompt:"根据民法典婚姻家庭编，我国法定婚龄为？",options:["男22周岁、女20周岁", "男20周岁、女18周岁", "男25周岁、女23周岁", "男18周岁、女18周岁"],answer:0,explanation:"我国法定婚龄为男不得早于22周岁，女不得早于20周岁。"},{id:"cs-3471",module:"changshi",prompt:"根据民法典，禁止结婚的情形不包括？",options:["没有血缘关系", "直系血亲", "三代以内旁系血亲", "有配偶者"],answer:0,explanation:"禁止结婚的情形包括直系血亲和三代以内的旁系血亲；没有血缘关系不属于禁止结婚的情形。"},{id:"cs-3472",module:"changshi",prompt:"根据民法典，婚姻无效的情形不包括？",options:["夫妻感情破裂", "重婚", "有禁止结婚的亲属关系", "未达到法定婚龄"],answer:0,explanation:"婚姻无效的情形包括重婚、有禁止结婚的亲属关系、未达到法定婚龄；夫妻感情破裂是离婚的事由，不是婚姻无效的情形。"},{id:"cs-3473",module:"changshi",prompt:"因胁迫结婚的，受胁迫方可以请求撤销婚姻的期限为？",options:["自胁迫行为终止之日起1年内", "6个月内", "2年内", "3年内"],answer:0,explanation:"因胁迫结婚的，受胁迫的一方可以向人民法院请求撤销婚姻，请求撤销的应当自胁迫行为终止之日起1年内提出。"},{id:"cs-3474",module:"changshi",prompt:"一方患有重大疾病的，应当在结婚登记前如实告知另一方；不如实告知的，另一方可以向人民法院请求？",options:["撤销婚姻", "确认婚姻无效", "赔偿损失", "强制离婚"],answer:0,explanation:"一方患有重大疾病的，应当在结婚登记前如实告知另一方；不如实告知的，另一方可以向人民法院请求撤销婚姻。"},{id:"cs-3475",module:"changshi",prompt:"离婚后，已满两周岁的子女直接抚养权由谁确定？",options:["父母双方协议不成的，由人民法院根据最有利于未成年子女的原则判决", "父亲优先", "母亲优先", "祖父母优先"],answer:0,explanation:"已满两周岁的子女，父母双方对抚养问题协议不成的，由人民法院根据双方的具体情况，按照最有利于未成年子女的原则判决。"},{id:"cs-3476",module:"changshi",prompt:"子女已满八周岁的，直接抚养权争议中应当尊重其？",options:["真实意愿", "经济条件", "学习成绩", "户籍情况"],answer:0,explanation:"子女已满八周岁的，应当尊重其真实意愿。"},{id:"cs-3477",module:"changshi",prompt:"离婚后，不直接抚养子女的一方应当负担？",options:["部分或者全部抚养费", "全部抚养费", "无抚养义务", "仅医疗费"],answer:0,explanation:"离婚后，子女由一方直接抚养的，另一方应当负担部分或者全部抚养费；负担费用的多少和期限的长短，由双方协议，协议不成的，由人民法院判决。"},{id:"cs-3478",module:"changshi",prompt:"收养人应当同时具备的条件不包括？",options:["必须已婚", "无不利于被收养人健康成长的违法犯罪记录", "有抚养、教育和保护被收养人的能力", "未患有医学上认为不应当收养子女的疾病"],answer:0,explanation:"收养人应当同时具备无不利于被收养人健康成长的违法犯罪记录、有抚养教育保护能力、未患有医学上认为不应当收养子女的疾病等条件；收养人可以已婚也可以未婚。"},{id:"cs-3479",module:"changshi",prompt:"收养应当向哪个部门登记？",options:["县级以上人民政府民政部门", "公安机关", "人民法院", "街道办事处"],answer:0,explanation:"收养应当向县级以上人民政府民政部门登记，收养关系自登记之日起成立。"},{id:"cs-3480",module:"changshi",prompt:"收养关系解除后，成年被收养人与生父母及其他近亲属的权利义务关系？",options:["可以协商确定是否恢复", "自动恢复", "不能恢复", "由法院判决"],answer:0,explanation:"收养关系解除后，养子女与养父母及其他近亲属间的权利义务关系即行消除；与生父母及其他近亲属间的权利义务关系自行恢复，但成年被收养人与生父母及其他近亲属间的权利义务关系是否恢复，可以协商确定。"},{id:"cs-3481",module:"changshi",prompt:"根据民法典继承编，遗嘱的法定形式不包括？",options:["录音遗嘱（未注明日期）", "自书遗嘱", "代书遗嘱", "公证遗嘱"],answer:0,explanation:"民法典规定的遗嘱形式包括自书遗嘱、代书遗嘱、打印遗嘱、录音录像遗嘱、口头遗嘱和公证遗嘱；录音录像遗嘱应当有两个以上见证人在场见证并注明年月日。"},{id:"cs-3482",module:"changshi",prompt:"代书遗嘱的生效要件是？",options:["有两个以上见证人在场见证，由其中一人代书，注明年月日，并由代书人、其他见证人和遗嘱人签名", "仅遗嘱人签名", "仅代书人签名", "无需见证人"],answer:0,explanation:"代书遗嘱应当有两个以上见证人在场见证，由其中一人代书，注明年、月、日，并由代书人、其他见证人和遗嘱人签名。"},{id:"cs-3483",module:"changshi",prompt:"遗嘱人立有数份遗嘱且内容相抵触的，以哪份为准？",options:["最后的遗嘱", "公证遗嘱", "自书遗嘱", "口头遗嘱"],answer:0,explanation:"立有数份遗嘱，内容相抵触的，以最后的遗嘱为准；民法典取消了公证遗嘱效力优先的规定。"},{id:"cs-3484",module:"changshi",prompt:"继承开始后，继承人放弃继承的，应当在遗产处理前以什么形式表示？",options:["书面形式", "口头形式", "默示形式", "推定形式"],answer:0,explanation:"继承开始后，继承人放弃继承的，应当在遗产处理前，以书面形式作出放弃继承的表示；没有表示的，视为接受继承。"},{id:"cs-3485",module:"changshi",prompt:"受遗赠人应当在知道受遗赠后多少日内作出接受或者放弃受遗赠的表示？",options:["60日内", "30日内", "90日内", "6个月内"],answer:0,explanation:"受遗赠人应当在知道受遗赠后60日内，作出接受或者放弃受遗赠的表示；到期没有表示的，视为放弃受遗赠。"},{id:"cs-3486",module:"changshi",prompt:"民事主体的人格权受法律保护，任何组织或者个人不得侵害，这体现了？",options:["人格权独立成编的保护原则", "人格权可转让", "人格权可放弃", "人格权可继承"],answer:0,explanation:"人格权是民事主体享有的生命权、身体权、健康权、姓名权、名称权、肖像权、名誉权、荣誉权、隐私权等权利，受法律保护，不得转让、放弃、继承。"},{id:"cs-3487",module:"changshi",prompt:"以非法拘禁等方式剥夺、限制他人的行动自由的，属于侵害？",options:["行动自由", "名誉权", "荣誉权", "姓名权"],answer:0,explanation:"任何组织或者个人不得以非法拘禁等方式剥夺、限制他人的行动自由，不得非法搜查他人的身体。"},{id:"cs-3488",module:"changshi",prompt:"未经肖像权人同意，制作、使用、公开肖像权人的肖像的，构成？",options:["侵害肖像权", "侵害名誉权", "侵害隐私权", "侵害姓名权"],answer:0,explanation:"未经肖像权人同意，不得制作、使用、公开肖像权人的肖像，但是法律另有规定的除外。"},{id:"cs-3489",module:"changshi",prompt:"合理使用他人肖像的情形不包括？",options:["商业广告代言", "个人学习、艺术欣赏", "新闻报道", "国家机关执行公务"],answer:0,explanation:"为个人学习、艺术欣赏、课堂教学、新闻报道、国家机关执行公务等合理使用他人肖像，可以不经肖像权人同意；商业广告代言不属于合理使用。"},{id:"cs-3490",module:"changshi",prompt:"民事主体的名誉受到侵害的，有权请求行为人？",options:["停止侵害、消除影响、恢复名誉、赔礼道歉，并可以要求赔偿损失", "仅赔礼道歉", "仅赔偿损失", "仅停止侵害"],answer:0,explanation:"民事主体的名誉权受到侵害的，有权请求行为人停止侵害、消除影响、恢复名誉、赔礼道歉，并可以要求赔偿损失。"},{id:"cs-3491",module:"changshi",prompt:"根据民法典人格权编，隐私权的客体包括？",options:["私人生活安宁和私密空间、私密活动、私密信息", "公开信息", "公共事务", "商业秘密"],answer:0,explanation:"隐私是自然人的私人生活安宁和不愿为他人知晓的私密空间、私密活动、私密信息。"},{id:"cs-3492",module:"changshi",prompt:"下列行为中不属于侵害隐私权的是？",options:["经权利人明确同意处理其私密信息", "偷拍他人住宅", "窃听他人私人谈话", "泄露他人病历"],answer:0,explanation:"经权利人明确同意处理其私密信息的行为不构成侵害隐私权。"},{id:"cs-3493",module:"changshi",prompt:"个人信息中的私密信息适用？",options:["隐私权的规定", "姓名权的规定", "肖像权的规定", "名誉权的规定"],answer:0,explanation:"个人信息中的私密信息，适用有关隐私权的规定；没有规定的，适用有关个人信息保护的规定。"},{id:"cs-3494",module:"changshi",prompt:"死者的姓名、肖像、名誉、荣誉、隐私、遗体等受到侵害的，有权请求行为人承担民事责任的近亲属范围是？",options:["配偶、子女、父母", "所有亲属", "仅兄弟姐妹", "仅祖父母"],answer:0,explanation:"死者的姓名、肖像、名誉、荣誉、隐私、遗体等受到侵害的，其配偶、子女、父母有权依法请求行为人承担民事责任。"},{id:"cs-3495",module:"changshi",prompt:"自然人享有生命权，有权维护自己的？",options:["生命安全和生命尊严", "财产利益", "商业利益", "政治权利"],answer:0,explanation:"自然人享有生命权，自然人的生命安全和生命尊严受法律保护，任何组织或者个人不得侵害。"},{id:"cs-3496",module:"changshi",prompt:"完全民事行为能力人自愿承担风险（自甘风险）参加文体活动，因其他参加者的行为受到损害的，其他参加者？",options:["不承担侵权责任（有故意或重大过失的除外）", "承担全部责任", "承担一半责任", "承担补偿责任"],answer:0,explanation:"自愿参加具有一定风险的文体活动，因其他参加者的行为受到损害的，受害人不得请求其他参加者承担侵权责任，但其他参加者对损害的发生有故意或者重大过失的除外。"},{id:"cs-3497",module:"changshi",prompt:"因保护他人民事权益使自己受到损害的，由谁承担民事责任？",options:["侵权人承担民事责任，受益人可以给予适当补偿", "自己承担", "国家承担", "受益人承担全部"],answer:0,explanation:"因保护他人民事权益使自己受到损害的，由侵权人承担民事责任，受益人可以给予适当补偿；没有侵权人、侵权人逃逸或者无力承担民事责任的，受害人请求补偿的，受益人应当给予适当补偿。"},{id:"cs-3498",module:"changshi",prompt:"民事主体因同一行为应当承担民事责任、行政责任和刑事责任的，其财产不足以支付的，优先用于承担？",options:["民事责任", "行政责任", "刑事责任", "罚款"],answer:0,explanation:"民事主体因同一行为应当承担民事责任、行政责任和刑事责任，其财产不足以支付的，优先用于承担民事责任。"},{id:"cs-3499",module:"changshi",prompt:"侵权行为危及他人人身、财产安全的，被侵权人有权请求侵权人承担？",options:["停止侵害、排除妨碍、消除危险等侵权责任", "仅赔偿损失", "仅赔礼道歉", "仅恢复原状"],answer:0,explanation:"侵权行为危及他人人身、财产安全的，被侵权人有权请求侵权人承担停止侵害、排除妨碍、消除危险等侵权责任。"},{id:"cs-3500",module:"changshi",prompt:"刑法的任务是用刑罚同什么作斗争？",options:["一切犯罪行为", "一切违法行为", "一切不道德行为", "一切民事纠纷"],answer:0,explanation:"刑法的任务是用刑罚同一切犯罪行为作斗争，以保卫国家安全、人民民主专政政权和社会主义制度等。"},{id:"cs-3501",module:"changshi",prompt:"我国刑法的属地管辖权适用于？",options:["在中华人民共和国领域内犯罪的一切人（享有外交豁免权的除外）", "仅中国人", "仅外国人", "仅境内居民"],answer:0,explanation:"凡在中华人民共和国领域内犯罪的，除法律有特别规定的以外，都适用我国刑法。"},{id:"cs-3502",module:"changshi",prompt:"我国刑法规定的最低刑事责任年龄为？",options:["12周岁（特定情形）", "10周岁", "14周岁（一般情形）", "16周岁（完全负刑事责任）"],answer:0,explanation:"已满16周岁的人犯罪应当负刑事责任；已满14周岁不满16周岁犯特定严重罪行的负刑事责任；已满12周岁不满14周岁犯故意杀人、故意伤害罪致人死亡等特定情形，经最高检核准追诉的负刑事责任。"},{id:"cs-3503",module:"changshi",prompt:"已满14周岁不满16周岁的人应当负刑事责任的犯罪不包括？",options:["盗窃罪", "故意杀人罪", "故意伤害致人重伤或者死亡", "抢劫罪"],answer:0,explanation:"已满14周岁不满16周岁的人犯故意杀人、故意伤害致人重伤或者死亡、强奸、抢劫、贩卖毒品、放火、爆炸、投放危险物质罪的，应当负刑事责任；盗窃罪不在其列。"},{id:"cs-3504",module:"changshi",prompt:"又聋又哑的人或者盲人犯罪，可以？",options:["从轻、减轻或者免除处罚", "从重处罚", "加重处罚", "一律免除"],answer:0,explanation:"又聋又哑的人或者盲人犯罪，可以从轻、减轻或者免除处罚。"},{id:"cs-3505",module:"changshi",prompt:"醉酒的人犯罪，应当？",options:["负刑事责任", "不负刑事责任", "减轻处罚", "免除处罚"],answer:0,explanation:"醉酒的人犯罪，应当负刑事责任。"},{id:"cs-3506",module:"changshi",prompt:"防卫不适时的情形包括？",options:["事前防卫和事后防卫", "正当防卫和防卫过当", "紧急避险", "自助行为"],answer:0,explanation:"防卫不适时包括事前防卫（不法侵害尚未开始）和事后防卫（不法侵害已经结束）。"},{id:"cs-3507",module:"changshi",prompt:"单位犯罪的特征不包括？",options:["必须以个人名义实施", "以单位名义实施", "为单位谋取利益", "体现单位意志"],answer:0,explanation:"单位犯罪是指公司、企业、事业单位、机关、团体为单位谋取利益，以单位名义实施，法律规定应负刑事责任的危害社会的行为。"},{id:"cs-3508",module:"changshi",prompt:"单位犯罪的处罚原则是？",options:["对单位判处罚金，并对直接负责的主管人员和其他直接责任人员判处刑罚（法律另有规定的除外）", "仅处罚单位", "仅处罚个人", "都不处罚"],answer:0,explanation:"单位犯罪的，对单位判处罚金，并对其直接负责的主管人员和其他直接责任人员判处刑罚；法律另有规定的除外。"},{id:"cs-3509",module:"changshi",prompt:"根据刑法规定，刑罚的种类不包括？",options:["训诫", "管制", "拘役", "有期徒刑"],answer:0,explanation:"我国刑罚的种类包括管制、拘役、有期徒刑、无期徒刑、死刑（主刑）和罚金、剥夺政治权利、没收财产、驱逐出境（附加刑）；训诫不是刑罚。"},{id:"cs-3510",module:"changshi",prompt:"根据刑法规定，管制的期限为？",options:["3个月以上2年以下", "1个月以上6个月以下", "6个月以上15年以下", "1年以上5年以下"],answer:0,explanation:"管制的期限为3个月以上2年以下，数罪并罚时最高不能超过3年。"},{id:"cs-3511",module:"changshi",prompt:"根据刑法规定，拘役的期限为？",options:["1个月以上6个月以下", "3个月以上2年以下", "6个月以上15年以下", "1年以上"],answer:0,explanation:"拘役的期限为1个月以上6个月以下，数罪并罚时最高不能超过1年。"},{id:"cs-3512",module:"changshi",prompt:"刑事诉讼强制措施的种类不包括？",options:["行政拘留", "拘传", "取保候审", "监视居住"],answer:0,explanation:"刑事诉讼强制措施包括拘传、取保候审、监视居住、拘留和逮捕；行政拘留是行政处罚。"},{id:"cs-3513",module:"changshi",prompt:"刑事诉讼中，拘传的适用对象是？",options:["未被羁押的犯罪嫌疑人、被告人", "已被羁押的人", "证人", "被害人"],answer:0,explanation:"拘传是对于未被羁押的犯罪嫌疑人、被告人，强制其到指定地点接受讯问的措施。"},{id:"cs-3514",module:"changshi",prompt:"取保候审的保证方式包括？",options:["保证人或保证金", "仅保证人", "仅保证金", "仅财产担保"],answer:0,explanation:"取保候审的保证方式包括提出保证人或者交纳保证金，但不能同时适用。"},{id:"cs-3515",module:"changshi",prompt:"保证人的条件不包括？",options:["与本案有利害关系", "与本案无牵连", "有能力履行保证义务", "享有政治权利，人身自由未受到限制"],answer:0,explanation:"保证人应当与本案无牵连，有能力履行保证义务，享有政治权利且人身自由未受限制，有固定的住处和收入。"},{id:"cs-3516",module:"changshi",prompt:"被取保候审的犯罪嫌疑人、被告人应当遵守的规定不包括？",options:["可以随意离开所居住的市、县", "未经批准不得离开所居住的市、县", "住址、工作单位和联系方式变动时在24小时以内报告", "传讯的时候及时到案"],answer:0,explanation:"被取保候审人未经批准不得离开所居住的市、县，住址等变动应报告，传讯时及时到案，不得干扰证人作证等。"},{id:"cs-3517",module:"changshi",prompt:"监视居住的适用条件不包括？",options:["符合逮捕条件但案件事实清楚", "患有严重疾病、生活不能自理", "怀孕或者正在哺乳自己婴儿的妇女", "系生活不能自理的人的唯一扶养人"],answer:0,explanation:"监视居住适用于符合逮捕条件但有法定特殊情形（严重疾病、怀孕哺乳、唯一扶养人等）以及因为案件的特殊情况或者办理案件的需要采取监视居住措施更为适宜的等情形。"},{id:"cs-3518",module:"changshi",prompt:"指定居所监视居住适用于？",options:["无固定住处或涉嫌危害国家安全犯罪、恐怖活动犯罪在住处执行有碍侦查的", "所有嫌疑人", "仅本地人", "仅轻微案件"],answer:0,explanation:"监视居住应当在犯罪嫌疑人、被告人的住处执行；无固定住处的，可以在指定的居所执行；涉嫌危害国家安全犯罪、恐怖活动犯罪，在住处执行可能有碍侦查的，经上一级公安机关批准，也可以在指定的居所执行。"},{id:"cs-3519",module:"changshi",prompt:"刑事拘留的适用情形不包括？",options:["轻微违法行为", "正在预备犯罪、实行犯罪或者在犯罪后即时被发觉的", "被害人或者在场亲眼看见的人指认其犯罪的", "在身边或者住处发现有犯罪证据的"],answer:0,explanation:"刑事拘留适用于正在预备犯罪、实行犯罪或犯罪后即时被发觉，被害人或在场亲眼看见的人指认其犯罪，在身边或住处发现有犯罪证据等法定情形。"},{id:"cs-3520",module:"changshi",prompt:"刑事诉讼中，逮捕的条件不包括？",options:["可能判处管制", "有证据证明有犯罪事实", "可能判处徒刑以上刑罚", "采取取保候审不足以防止发生社会危险性"],answer:0,explanation:"逮捕的条件是有证据证明有犯罪事实、可能判处徒刑以上刑罚、采取取保候审尚不足以防止发生社会危险性。"},{id:"cs-3521",module:"changshi",prompt:"逮捕后应当立即送看守所羁押，并在逮捕后多少小时内通知家属？",options:["24小时内", "12小时内", "48小时内", "72小时内"],answer:0,explanation:"逮捕后应当立即将被逮捕人送看守所羁押，除无法通知的以外，应当在逮捕后24小时以内通知被逮捕人的家属。"},{id:"cs-3522",module:"changshi",prompt:"人民检察院审查批准逮捕的期限为？",options:["7日内（已拘留的不超过7日）", "3日内", "15日内", "30日内"],answer:0,explanation:"人民检察院对于公安机关提请批准逮捕的案件进行审查后，应当在7日内作出批准逮捕或者不批准逮捕的决定。"},{id:"cs-3523",module:"changshi",prompt:"对犯罪嫌疑人逮捕后的侦查羁押期限，案情复杂、期限届满不能终结的，可以经上一级人民检察院批准延长？",options:["1个月", "2个月", "3个月", "6个月"],answer:0,explanation:"对犯罪嫌疑人逮捕后的侦查羁押期限不得超过2个月；案情复杂、期限届满不能终结的案件，可以经上一级人民检察院批准延长1个月。"},{id:"cs-3524",module:"changshi",prompt:"因特殊原因，在较长时间内不宜交付审判的特别重大复杂的案件，由最高人民检察院报请？",options:["全国人民代表大会常务委员会批准延期审理", "最高人民法院批准", "国务院批准", "中央政法委批准"],answer:0,explanation:"因为特殊原因，在较长时间内不宜交付审判的特别重大复杂的案件，由最高人民检察院报请全国人民代表大会常务委员会批准延期审理。"},{id:"cs-3525",module:"changshi",prompt:"犯罪嫌疑人、被告人被羁押的案件，不能在法定期限内办结的，应当？",options:["变更强制措施或释放", "继续羁押", "无限期延长", "自动释放"],answer:0,explanation:"犯罪嫌疑人、被告人被羁押的案件，不能在法定侦查羁押、审查起诉、审判期限内办结的，应当变更强制措施或者释放。"},{id:"cs-3526",module:"changshi",prompt:"强制措施的变更情形不包括？",options:["案件事实清楚", "犯罪嫌疑人、被告人患有严重疾病", "案件不能在法定期限内办结", "社会危险性消除"],answer:0,explanation:"犯罪嫌疑人、被告人患有严重疾病、案件不能在法定期限内办结、社会危险性消除等情形，可以变更强制措施。"},{id:"cs-3527",module:"changshi",prompt:"国际法的基本原则不包括？",options:["干涉他国内政", "国家主权平等", "不干涉内政", "和平解决国际争端"],answer:0,explanation:"国际法的基本原则包括国家主权平等、不干涉内政、和平解决国际争端、善意履行国际义务等。"},{id:"cs-3528",module:"changshi",prompt:"国家领土的组成部分不包括？",options:["公海", "领陆", "领水", "领空"],answer:0,explanation:"国家领土包括领陆、领水（内水和领海）、领空和底土；公海不属于任何国家领土。"},{id:"cs-3529",module:"changshi",prompt:"根据海洋法公约，领海的法律地位是？",options:["沿海国主权管辖下的水域", "公海", "专属经济区", "内水"],answer:0,explanation:"领海是沿海国主权管辖下邻接其陆地领土和内水以外一定宽度的海域。"},{id:"cs-3530",module:"changshi",prompt:"根据海洋法公约，无害通过权适用于？",options:["领海", "内水", "专属经济区", "公海"],answer:0,explanation:"无害通过权是指外国船舶在不损害沿海国和平、良好秩序和安全的条件下，可以自由通过领海而不需要事先通知或获得许可。"},{id:"cs-3531",module:"changshi",prompt:"大陆架的权利基础是？",options:["沿海国陆地领土的自然延伸", "200海里专属经济区", "领海基线", "国际条约"],answer:0,explanation:"大陆架是沿海国陆地领土在海面以下的自然延伸，沿海国对大陆架享有勘探开发自然资源的主权权利。"},{id:"cs-3532",module:"changshi",prompt:"根据海洋法公约，公海的自由不包括？",options:["在公海进行军事演习（须遵守国际法）", "航行自由", "飞越自由", "捕鱼自由"],answer:0,explanation:"公海自由包括航行自由、飞越自由、铺设海底电缆和管道自由、建造人工岛屿和其他设施自由、捕鱼自由、科学研究自由等；军事活动须遵守国际法。"},{id:"cs-3533",module:"changshi",prompt:"外交代表的刑事管辖豁免是指？",options:["外交代表不受驻在国刑事管辖", "外交代表可以犯罪", "外交代表享有民事豁免", "外交代表享有行政豁免"],answer:0,explanation:"外交代表享有刑事管辖豁免，不受驻在国的刑事管辖；民事和行政管辖豁免有例外。"},{id:"cs-3534",module:"changshi",prompt:"国际条约的缔结程序不包括？",options:["国内法院批准", "谈判", "签署", "批准"],answer:0,explanation:"国际条约的缔结程序一般包括谈判、签署、批准、交换批准书等；国内法院不参与条约缔结。"},{id:"cs-3535",module:"changshi",prompt:"国际争端的和平解决方法不包括？",options:["武力威胁或使用武力", "谈判", "仲裁", "司法解决"],answer:0,explanation:"国际争端的和平解决方法包括谈判、协商、斡旋、调停、调查、和解、仲裁、司法解决等；不得使用武力威胁或武力。"},{id:"cs-3536",module:"changshi",prompt:"联合国安全理事会的常任理事国不包括？",options:["德国", "中国", "法国", "俄罗斯"],answer:0,explanation:"联合国安全理事会的常任理事国为中国、法国、俄罗斯、英国、美国。"},{id:"cs-3537",module:"changshi",prompt:"联合国大会的表决原则是？",options:["一国一票，重要问题以三分之二多数通过", "一国一票，简单多数", "加权表决", "协商一致"],answer:0,explanation:"联合国大会实行一国一票，重要问题以出席并投票的三分之二多数通过，其他问题以过半数通过。"},{id:"cs-3538",module:"changshi",prompt:"安理会的表决程序中，常任理事国享有？",options:["否决权", "优先权", "双重投票权", "豁免权"],answer:0,explanation:"安理会非程序性事项的决议须包括全体常任理事国在内的9个同意票，常任理事国享有否决权。"},{id:"cs-3539",module:"changshi",prompt:"国际法院的法官人数为？",options:["15人", "9人", "12人", "21人"],answer:0,explanation:"国际法院由15名法官组成，任期9年，可以连选连任。"},{id:"cs-3540",module:"changshi",prompt:"国际刑事法院的所在地是？",options:["荷兰海牙", "纽约", "日内瓦", "罗马"],answer:0,explanation:"国际刑事法院设在荷兰海牙，根据《罗马规约》于2002年成立。"},{id:"cs-3541",module:"changshi",prompt:"引渡的一般原则不包括？",options:["本国国民不引渡（多数国家）", "政治犯不引渡", "双重犯罪原则", "可以随意引渡"],answer:0,explanation:"引渡的一般原则包括本国国民不引渡（多数国家）、政治犯不引渡、双重犯罪原则、特定原则等。"},{id:"cs-3542",module:"changshi",prompt:"消费者权益保护法规定的经营者义务不包括？",options:["无限期无理由退货", "提供真实、全面的商品信息", "出具购货凭证或服务单据", "保证商品或服务质量"],answer:0,explanation:"经营者的义务包括提供真实全面的信息、出具凭证、保证质量、7日无理由退货（网络购物）等；无限期无理由退货不是法定义务。"},{id:"cs-3543",module:"changshi",prompt:"消费者权益保护法规定，经营者不得对消费者进行？",options:["侮辱、诽谤，不得搜查消费者的身体及其携带的物品，不得侵犯消费者的人身自由", "正常询问", "合理查验", "依法查验"],answer:0,explanation:"经营者不得对消费者进行侮辱、诽谤，不得搜查消费者的身体及其携带的物品，不得侵犯消费者的人身自由。"},{id:"cs-3544",module:"changshi",prompt:"消费者在购买、使用商品时，其合法权益受到损害的，可以向谁要求赔偿？",options:["销售者", "生产者", "运输者", "仓储者"],answer:0,explanation:"消费者在购买、使用商品时，其合法权益受到损害的，可以向销售者要求赔偿；销售者赔偿后，属于生产者责任的，有权向生产者追偿。"},{id:"cs-3545",module:"changshi",prompt:"消费者通过网络交易平台购买商品，平台不能提供销售者真实名称、地址和有效联系方式的，消费者可以？",options:["要求平台先行赔付", "自行承担", "仅向平台索赔", "放弃权利"],answer:0,explanation:"消费者通过网络交易平台购买商品或者接受服务，其合法权益受到损害的，可以向销售者或者服务者要求赔偿；网络交易平台提供者不能提供销售者或者服务者的真实名称、地址和有效联系方式的，消费者也可以向网络交易平台提供者要求赔偿。"},{id:"cs-3546",module:"changshi",prompt:"经营者对消费者提出的修理、重作、更换、退货、补足商品数量、退还货款和服务费用等要求，故意拖延或者无理拒绝的，应当？",options:["承担民事责任，并可能受到行政处罚", "仅民事责任", "仅行政处罚", "不承担责任"],answer:0,explanation:"经营者对消费者提出的合理要求故意拖延或者无理拒绝的，应当承担民事责任，并可能受到行政处罚。"},{id:"cs-3547",module:"changshi",prompt:"经营者提供商品或者服务，造成消费者财产损害的，应当依照法律规定或者当事人约定承担？",options:["修理、重作、更换、退货、补足商品数量、退还货款和服务费用或者赔偿损失等民事责任", "仅道歉", "仅赔偿", "仅退货"],answer:0,explanation:"经营者提供商品或者服务，造成消费者财产损害的，应当依照法律规定或者当事人约定承担修理、重作、更换、退货、补足商品数量、退还货款和服务费用或者赔偿损失等民事责任。"},{id:"cs-3548",module:"changshi",prompt:"经营者以预收款方式提供商品或者服务的，未按照约定提供的，消费者可以？",options:["要求履行约定或者退回预付款", "仅要求继续履行", "仅要求赔偿", "放弃权利"],answer:0,explanation:"经营者以预收款方式提供商品或者服务的，应当按照约定提供；未按照约定提供的，应当按照消费者的要求履行约定或者退回预付款，并应当承担预付款的利息和消费者必须支付的合理费用。"},{id:"cs-3549",module:"changshi",prompt:"经营者对行政处罚决定不服的，可以？",options:["申请行政复议或者提起行政诉讼", "拒绝执行", "申请仲裁", "向上级申诉"],answer:0,explanation:"经营者对行政处罚决定不服的，可以自收到处罚决定之日起15日内向上一级机关申请复议，或者依法向人民法院提起行政诉讼。"},{id:"cs-3550",module:"changshi",prompt:"消费者协会履行职能不包括？",options:["直接处罚经营者", "向消费者提供消费信息和咨询服务", "参与制定有关消费者权益的法律、法规、规章和强制性标准", "就损害消费者合法权益的行为提起诉讼"],answer:0,explanation:"消费者协会的职能包括提供消费信息咨询服务、参与制定相关法律法规和标准、就损害消费者合法权益的行为提起诉讼等；没有直接处罚权。"},{id:"cs-3551",module:"changshi",prompt:"消费者组织不得从事的活动是？",options:["以牟利为目的向社会推荐商品和服务", "提供消费信息", "受理消费者投诉", "开展消费教育"],answer:0,explanation:"消费者组织不得从事商品经营和营利性服务，不得以收取费用或者其他牟取利益的方式向消费者推荐商品和服务。"},{id:"cs-3552",module:"changshi",prompt:"经营者应当保证其提供的商品或者服务符合保障人身、财产安全的要求，对可能危及人身、财产安全的商品和服务，应当？",options:["向消费者作出真实的说明和明确的警示，并说明和标明正确使用商品或接受服务的方法以及防止危害发生的方法", "仅提供商品", "不作说明", "隐瞒风险"],answer:0,explanation:"经营者应当保证其提供的商品或者服务符合保障人身、财产安全的要求；对可能危及人身、财产安全的商品和服务，应当向消费者作出真实的说明和明确的警示，并说明和标明正确使用商品或者接受服务的方法以及防止危害发生的方法。"},{id:"cs-3553",module:"changshi",prompt:"经营者发现其提供的商品或者服务存在严重缺陷，即使正确使用仍然可能造成人身、财产损害的，应当？",options:["立即向有关行政部门报告和告知消费者，并采取防止危害发生的措施", "继续销售", "仅内部处理", "不作处理"],answer:0,explanation:"经营者发现其提供的商品或者服务存在缺陷，有危及人身、财产安全危险的，应当立即向有关行政部门报告和告知消费者，并采取停止销售、警示、召回、无害化处理、销毁、停止生产或者服务等措施。"},{id:"cs-3554",module:"changshi",prompt:"经营者不得以格式条款等方式作出排除或者限制消费者权利的规定，格式条款含有该内容的，其效力为？",options:["无效", "有效", "可撤销", "效力待定"],answer:0,explanation:"经营者以格式条款、通知、声明、店堂告示等方式作出排除或者限制消费者权利、减轻或者免除经营者责任、加重消费者责任等对消费者不公平、不合理规定的，其内容无效。"},{id:"cs-3555",module:"changshi",prompt:"消费者向有关行政部门投诉的，该部门应当自收到投诉之日起几个工作日内处理并告知消费者？",options:["7个工作日内", "3个工作日内", "15个工作日内", "30个工作日内"],answer:0,explanation:"消费者向有关行政部门投诉的，该部门应当自收到投诉之日起7个工作日内予以处理并告知消费者。"},{id:"cs-3556",module:"changshi",prompt:"对侵害众多消费者合法权益的行为，中国消费者协会以及在省、自治区、直辖市设立的消费者协会可以向人民法院提起？",options:["公益诉讼", "民事诉讼", "行政诉讼", "刑事诉讼"],answer:0,explanation:"对侵害众多消费者合法权益的行为，中国消费者协会以及在省、自治区、直辖市设立的消费者协会，可以向人民法院提起诉讼。"});
(window.YC_CS_BANK=window.YC_CS_BANK||[]).push({id:"cs-3557",module:"changshi",prompt:"根据民法典物权编，物权的种类不包括？",options:["债权", "所有权", "用益物权", "担保物权"],answer:0,explanation:"物权包括所有权、用益物权和担保物权；债权是请求特定人为特定行为的权利，不属于物权。"},{id:"cs-3558",module:"changshi",prompt:"物权法理论上，物权的特征不包括？",options:["请求性", "排他性", "支配性", "对世性"],answer:0,explanation:"物权的特征包括支配性、排他性、对世性、绝对性等；请求性是债权的特征。"},{id:"cs-3559",module:"changshi",prompt:"物权变动的公示方法，动产为？",options:["交付", "登记", "占有改定", "指示交付"],answer:0,explanation:"动产物权的设立和转让，自交付时发生效力，法律另有规定的除外。"},{id:"cs-3560",module:"changshi",prompt:"物权变动的公示方法，不动产为？",options:["登记", "交付", "占有", "使用"],answer:0,explanation:"不动产物权的设立、变更、转让和消灭，经依法登记发生效力；未经登记，不发生效力，法律另有规定的除外。"},{id:"cs-3561",module:"changshi",prompt:"国家所有的自然资源不包括？",options:["农村集体土地", "矿藏", "水流", "海域"],answer:0,explanation:"矿藏、水流、海域、城市的土地等属于国家所有；农村集体土地属于集体所有。"},{id:"cs-3562",module:"changshi",prompt:"业主对建筑物内的住宅、经营性用房等专有部分享有？",options:["占有、使用、收益和处分的权利", "仅使用权", "仅收益权", "仅处分权"],answer:0,explanation:"业主对建筑物内的住宅、经营性用房等专有部分享有占有、使用、收益和处分的权利。"},{id:"cs-3563",module:"changshi",prompt:"业主对建筑物专有部分以外的共有部分，享有？",options:["共有和共同管理的权利", "单独所有权", "排他处分权", "优先购买权"],answer:0,explanation:"业主对建筑物专有部分以外的共有部分，享有共有和共同管理的权利。"},{id:"cs-3564",module:"changshi",prompt:"建筑物区分所有权中，业主大会的决定对业主具有？",options:["约束力", "建议性", "参考性", "无约束力"],answer:0,explanation:"业主大会或者业主委员会的决定，对业主具有约束力。"},{id:"cs-3565",module:"changshi",prompt:"下列事项中，应当经专有部分面积占比2/3以上且人数占比2/3以上的业主参与表决的是？",options:["筹集建筑物及其附属设施的维修资金", "日常物业管理", "电梯维修", "保洁服务"],answer:0,explanation:"筹集建筑物及其附属设施的维修资金、改建重建、改变共有部分用途等重大事项，应当经专有部分面积占比2/3以上且人数占比2/3以上的业主参与表决，并经参与表决的业主同意。"},{id:"cs-3566",module:"changshi",prompt:"建设用地使用权的设立方式不包括？",options:["继承", "出让", "划拨", "转让"],answer:0,explanation:"建设用地使用权的设立方式包括出让、划拨、转让等；继承不是设立方式。"},{id:"cs-3567",module:"changshi",prompt:"宅基地使用权的取得方式是？",options:["申请审批", "买卖", "抵押", "租赁"],answer:0,explanation:"宅基地使用权的取得、行使和转让，适用土地管理的法律和国家有关规定，一般通过申请审批取得。"},{id:"cs-3568",module:"changshi",prompt:"地役权的设立目的是？",options:["提高自己不动产的效益", "担保债务履行", "居住", "承包经营"],answer:0,explanation:"地役权是按照合同约定利用他人的不动产，以提高自己不动产的效益的权利。"},{id:"cs-3569",module:"changshi",prompt:"抵押权的设立，不动产抵押自何时设立？",options:["登记时", "合同生效时", "交付时", "付款时"],answer:0,explanation:"以不动产抵押的，应当办理抵押登记，抵押权自登记时设立。"},{id:"cs-3570",module:"changshi",prompt:"抵押权的设立，动产抵押自何时设立？",options:["合同生效时（未经登记不得对抗善意第三人）", "登记时", "交付时", "付款时"],answer:0,explanation:"以动产抵押的，抵押权自抵押合同生效时设立；未经登记，不得对抗善意第三人。"},{id:"cs-3571",module:"changshi",prompt:"留置权的行使条件不包括？",options:["必须经过登记", "债权人合法占有债务人的动产", "债务已届清偿期", "动产的占有与债权属于同一法律关系（企业间留置除外）"],answer:0,explanation:"留置权的成立条件是债权人合法占有债务人的动产、债务已届清偿期、动产的占有与债权属于同一法律关系（企业间留置除外）；留置权无需登记。"},{id:"cs-3572",module:"changshi",prompt:"占有的保护方式不包括？",options:["确认占有权", "返还原物", "排除妨害", "消除危险"],answer:0,explanation:"占有的保护方式包括返还原物、排除妨害、消除危险等；确认占有权不是法定的占有保护方式。"},{id:"cs-3573",module:"changshi",prompt:"所有权人有权在自己的不动产或者动产上设立？",options:["用益物权和担保物权", "仅用益物权", "仅担保物权", "债权"],answer:0,explanation:"所有权人有权在自己的不动产或者动产上设立用益物权和担保物权。"},{id:"cs-3574",module:"changshi",prompt:"根据民法典物权编，用益物权包括？",options:["土地承包经营权、建设用地使用权、宅基地使用权、居住权、地役权", "抵押权、质权、留置权", "所有权、共有权", "债权、请求权"],answer:0,explanation:"用益物权包括土地承包经营权、建设用地使用权、宅基地使用权、居住权和地役权。"},{id:"cs-3575",module:"changshi",prompt:"根据民法典物权编，担保物权包括？",options:["抵押权、质权、留置权", "土地承包经营权、建设用地使用权", "所有权、共有权", "债权、请求权"],answer:0,explanation:"担保物权包括抵押权、质权和留置权。"},{id:"cs-3576",module:"changshi",prompt:"共有人对共有的不动产或者动产没有约定为按份共有或者共同共有的，除具有家庭关系等外，视为？",options:["按份共有", "共同共有", "单独所有", "国家所有"],answer:0,explanation:"共有人对共有的不动产或者动产没有约定为按份共有或者共同共有，或者约定不明确的，除共有人具有家庭关系等外，视为按份共有。"},{id:"cs-3577",module:"changshi",prompt:"合同编的调整范围不包括？",options:["婚姻、收养、监护等有关身份关系的协议", "买卖合同", "借款合同", "租赁合同"],answer:0,explanation:"合同编调整平等主体之间设立、变更、终止民事法律关系的协议；婚姻、收养、监护等有关身份关系的协议，适用有关身份关系的法律规定。"},{id:"cs-3578",module:"changshi",prompt:"根据民法典合同编，要约的撤销是指？",options:["在要约生效后，受要约人承诺前，要约人取消要约", "在要约生效前取消要约", "承诺后取消合同", "合同履行后解除"],answer:0,explanation:"要约可以撤销，撤销要约的通知应当在受要约人发出承诺之前到达受要约人。"},{id:"cs-3579",module:"changshi",prompt:"根据民法典合同编，承诺的方式不包括？",options:["默示沉默", "通知", "行为（依交易习惯）", "声明"],answer:0,explanation:"承诺应当以通知的方式作出，但根据交易习惯或者要约表明可以通过行为作出承诺的除外；单纯的沉默不构成承诺。"},{id:"cs-3580",module:"changshi",prompt:"承诺对要约的内容作出非实质性变更的，除要约人及时反对或要约表明不得变更外，承诺？",options:["有效，合同的内容以承诺的内容为准", "无效", "视为新要约", "效力待定"],answer:0,explanation:"承诺对要约的内容作出非实质性变更的，除要约人及时反对或者要约表明承诺不得对要约的内容作出任何变更外，该承诺有效，合同的内容以承诺的内容为准。"},{id:"cs-3581",module:"changshi",prompt:"合同成立的时间一般为？",options:["承诺生效时", "合同履行时", "合同解除时", "合同终止时"],answer:0,explanation:"承诺生效时合同成立，法律另有规定或者当事人另有约定的除外。"},{id:"cs-3582",module:"changshi",prompt:"合同生效的时间一般为？",options:["依法成立时", "合同履行时", "合同解除时", "合同终止时"],answer:0,explanation:"依法成立的合同，自成立时生效，法律另有规定或者当事人另有约定的除外。"},{id:"cs-3583",module:"changshi",prompt:"合同的权利义务终止后，当事人应当遵循什么原则？",options:["诚实信用原则，根据交易习惯履行通知、协助、保密等义务", "自由原则", "公平原则", "等价有偿原则"],answer:0,explanation:"合同的权利义务终止后，当事人应当遵循诚实信用原则，根据交易习惯履行通知、协助、保密等义务。"},{id:"cs-3584",module:"changshi",prompt:"违约金与实际损失的关系是？",options:["违约金低于实际损失的，可以请求增加；过分高于实际损失的，可以请求适当减少", "违约金一律有效", "违约金一律无效", "违约金与损失无关"],answer:0,explanation:"约定的违约金低于造成的损失的，人民法院或者仲裁机构可以根据当事人的请求予以增加；约定的违约金过分高于造成的损失的，可以根据当事人的请求予以适当减少。"},{id:"cs-3585",module:"changshi",prompt:"根据民法典合同编，定金合同的性质是？",options:["实践合同", "诺成合同", "要式合同", "单务合同"],answer:0,explanation:"定金合同自实际交付定金时成立，是实践合同。"},{id:"cs-3586",module:"changshi",prompt:"根据民法典合同编，定金罚则的内容是？",options:["给付定金一方不履行债务的，无权请求返还定金；收受定金一方不履行债务的，应当双倍返还定金", "仅返还本金", "仅返还利息", "不承担责任"],answer:0,explanation:"定金罚则是给付定金一方不履行债务或者履行债务不符合约定致使不能实现合同目的的，无权请求返还定金；收受定金的一方不履行债务或者履行债务不符合约定致使不能实现合同目的的，应当双倍返还定金。"},{id:"cs-3587",module:"changshi",prompt:"根据民法典合同编，保证期间的性质是？",options:["除斥期间，不因任何事由中断、中止", "诉讼时效", "除斥期间，可以中断", "可以延长"],answer:0,explanation:"保证期间是确定保证人承担保证责任的期间，不发生诉讼时效的中止、中断和延长。"},{id:"cs-3588",module:"changshi",prompt:"保证人承担保证责任后，有权向债务人？",options:["追偿", "索赔", "要求赔偿", "要求补偿"],answer:0,explanation:"保证人承担保证责任后，除当事人另有约定外，有权在其承担保证责任的范围内向债务人追偿，享有债权人对债务人的权利。"},{id:"cs-3589",module:"changshi",prompt:"一般保证的保证人在主合同纠纷未经审判或仲裁，并就债务人财产依法强制执行仍不能履行债务前，有权？",options:["拒绝承担保证责任（先诉抗辩权）", "直接承担", "拒绝一切", "要求债务人先行赔偿"],answer:0,explanation:"一般保证的保证人在主合同纠纷未经审判或者仲裁，并就债务人财产依法强制执行仍不能履行债务前，有权拒绝向债权人承担保证责任，即先诉抗辩权。"},{id:"cs-3590",module:"changshi",prompt:"连带责任保证的保证人不享有？",options:["先诉抗辩权", "追偿权", "抗辩权", "求偿权"],answer:0,explanation:"连带责任保证的保证人在主债务履行期届满而债务人未履行债务时，债权人可以请求债务人履行债务，也可以请求保证人在其保证范围内承担保证责任，保证人不享有先诉抗辩权。"},{id:"cs-3591",module:"changshi",prompt:"租赁合同的租赁期限届满，承租人继续使用租赁物，出租人未提出异议的，原租赁合同？",options:["继续有效，但租赁期限为不定期", "自动终止", "自动续租原期限", "无效"],answer:0,explanation:"租赁期限届满，承租人继续使用租赁物，出租人未提出异议的，原租赁合同继续有效，但是租赁期限为不定期。"},{id:"cs-3592",module:"changshi",prompt:"融资租赁合同中，租赁物不符合约定的，出租人？",options:["不承担责任（承租人依赖出租人技能确定租赁物或干预选择的除外）", "承担全部责任", "承担一半责任", "承担补充责任"],answer:0,explanation:"融资租赁合同中，租赁物不符合约定或者不符合使用目的的，出租人不承担责任，但承租人依赖出租人的技能确定租赁物或者出租人干预选择租赁物的除外。"},{id:"cs-3593",module:"changshi",prompt:"根据民法典合同编，建设工程合同包括？",options:["工程勘察、设计、施工合同", "仅施工合同", "仅设计合同", "仅勘察合同"],answer:0,explanation:"建设工程合同包括工程勘察、设计、施工合同。"},{id:"cs-3594",module:"changshi",prompt:"委托合同的任意解除权是指？",options:["委托人和受托人均可以随时解除委托合同", "仅委托人可以解除", "仅受托人可以解除", "均不能解除"],answer:0,explanation:"委托人和受托人均可以随时解除委托合同；因解除合同造成对方损失的，除不可归责于该当事人的事由外，应当赔偿损失。"},{id:"cs-3595",module:"changshi",prompt:"故意杀人罪的既遂标准是？",options:["被害人死亡", "行为人着手", "行为人预备", "行为人中止"],answer:0,explanation:"故意杀人罪是结果犯，以被害人死亡为既遂标准。"},{id:"cs-3596",module:"changshi",prompt:"故意伤害罪的成立要求伤害结果达到？",options:["轻伤以上", "轻微伤", "无伤", "重伤"],answer:0,explanation:"故意伤害罪要求伤害结果达到轻伤以上；轻微伤不构成故意伤害罪。"},{id:"cs-3597",module:"changshi",prompt:"强奸罪的加重情节不包括？",options:["双方自愿", "强奸妇女、奸淫幼女情节恶劣的", "强奸妇女、奸淫幼女多人的", "在公共场所当众强奸妇女、奸淫幼女的"],answer:0,explanation:"强奸罪的加重情节包括情节恶劣、多人、公共场所当众、二人以上轮奸、致人重伤死亡等；双方自愿不构成犯罪。"},{id:"cs-3598",module:"changshi",prompt:"抢劫罪的加重情节不包括？",options:["入户盗窃", "入户抢劫", "在公共交通工具上抢劫", "抢劫银行或者其他金融机构"],answer:0,explanation:"抢劫罪的加重情节包括入户抢劫、在公共交通工具上抢劫、抢劫银行或其他金融机构、多次抢劫、致人重伤死亡等；入户盗窃不构成抢劫罪的加重情节。"},{id:"cs-3599",module:"changshi",prompt:"盗窃罪的加重情节不包括？",options:["入户盗窃未遂", "数额巨大", "多次盗窃", "携带凶器盗窃"],answer:0,explanation:"盗窃罪的加重情节包括数额巨大或者有其他严重情节、数额特别巨大或者有其他特别严重情节；入户盗窃未遂不构成加重情节。"},{id:"cs-3600",module:"changshi",prompt:"诈骗罪的数额标准一般为？",options:["3000元至1万元以上", "100元以下", "10万元以上", "100万元以上"],answer:0,explanation:"诈骗公私财物价值3000元至1万元以上的，应当认定为数额较大，构成诈骗罪。"},{id:"cs-3601",module:"changshi",prompt:"职务侵占罪的主体是？",options:["公司、企业或者其他单位的工作人员", "国家工作人员", "一般公民", "军人"],answer:0,explanation:"职务侵占罪是指公司、企业或者其他单位的工作人员，利用职务上的便利，将本单位财物非法占为己有，数额较大的行为。"},{id:"cs-3602",module:"changshi",prompt:"挪用资金罪的主体是？",options:["公司、企业或者其他单位的工作人员", "国家工作人员", "一般公民", "军人"],answer:0,explanation:"挪用资金罪是指公司、企业或者其他单位的工作人员，利用职务上的便利，挪用本单位资金归个人使用或者借贷给他人，数额较大、超过3个月未还，或者虽未超过3个月，但数额较大、进行营利活动，或者进行非法活动的行为。"},{id:"cs-3603",module:"changshi",prompt:"敲诈勒索罪的客观方面表现为？",options:["以威胁或者要挟的方法，强索公私财物，数额较大或者多次敲诈勒索", "秘密窃取", "暴力劫取", "欺骗取得"],answer:0,explanation:"敲诈勒索罪是指以非法占有为目的，对被害人使用威胁或者要挟的方法，强索公私财物，数额较大或者多次敲诈勒索的行为。"},{id:"cs-3604",module:"changshi",prompt:"妨害公务罪的客观方面表现为？",options:["以暴力、威胁方法阻碍国家机关工作人员依法执行职务", "正常配合执法", "拒绝配合执法", "提出异议"],answer:0,explanation:"妨害公务罪是指以暴力、威胁方法阻碍国家机关工作人员依法执行职务的行为。"},{id:"cs-3605",module:"changshi",prompt:"聚众斗殴罪的主体是？",options:["首要分子和积极参加者", "一般参加者", "围观者", "组织者"],answer:0,explanation:"聚众斗殴罪是对首要分子和其他积极参加的追究刑事责任。"},{id:"cs-3606",module:"changshi",prompt:"寻衅滋事罪的行为方式不包括？",options:["正常维权", "随意殴打他人，情节恶劣的", "追逐、拦截、辱骂、恐吓他人，情节恶劣的", "强拿硬要或者任意损毁、占用公私财物，情节严重的"],answer:0,explanation:"寻衅滋事罪的行为方式包括随意殴打他人、追逐拦截辱骂恐吓他人、强拿硬要或任意损毁占用公私财物、在公共场所起哄闹事等；正常维权不属于。"},{id:"cs-3607",module:"changshi",prompt:"危险驾驶罪的主观方面是？",options:["故意", "过失", "既可以是故意也可以是过失", "无过错"],answer:0,explanation:"危险驾驶罪的主观方面是故意，即明知自己的行为会发生危害社会的结果，并且希望或者放任这种结果发生。"},{id:"cs-3608",module:"changshi",prompt:"交通肇事罪的主观方面是？",options:["过失", "故意", "既可以是故意也可以是过失", "无过错"],answer:0,explanation:"交通肇事罪的主观方面是过失，即行为人应当预见自己的行为可能发生危害社会的结果，因为疏忽大意而没有预见，或者已经预见而轻信能够避免。"},{id:"cs-3609",module:"changshi",prompt:"失火罪的主观方面是？",options:["过失", "故意", "既可以是故意也可以是过失", "无过错"],answer:0,explanation:"失火罪是指由于行为人的过失引起火灾，造成严重后果，危害公共安全的行为。"},{id:"cs-3610",module:"changshi",prompt:"放火罪的主观方面是？",options:["故意", "过失", "既可以是故意也可以是过失", "无过错"],answer:0,explanation:"放火罪是指故意放火焚烧公私财物，危害公共安全的行为，主观方面是故意。"},{id:"cs-3611",module:"changshi",prompt:"盗窃罪与抢劫罪的区别不包括？",options:["是否使用暴力或胁迫", "是否非法占有", "是否当场", "是否秘密"],answer:0,explanation:"盗窃罪与抢劫罪都以非法占有为目的，区别主要在于是否使用暴力、胁迫或其他强制方法，以及是否当场劫取财物。"},{id:"cs-3612",module:"changshi",prompt:"侵占罪的客观方面表现为？",options:["将代为保管的他人财物非法占为己有，数额较大，拒不退还", "秘密窃取", "暴力劫取", "欺骗取得"],answer:0,explanation:"侵占罪是指将代为保管的他人财物非法占为己有，数额较大，拒不退还的行为，或者将他人的遗忘物或者埋藏物非法占为己有，数额较大，拒不交出的行为。"},{id:"cs-3613",module:"changshi",prompt:"掩饰、隐瞒犯罪所得罪的行为方式不包括？",options:["事前通谋", "窝藏", "转移", "收购"],answer:0,explanation:"掩饰、隐瞒犯罪所得、犯罪所得收益罪是指明知是犯罪所得及其产生的收益而予以窝藏、转移、收购、代为销售或者以其他方法掩饰、隐瞒的行为；事前通谋的以共同犯罪论处。"},{id:"cs-3614",module:"changshi",prompt:"帮助信息网络犯罪活动罪的行为方式是？",options:["明知他人利用信息网络实施犯罪，为其犯罪提供互联网接入、服务器托管、网络存储、通讯传输等技术支持，或者提供广告推广、支付结算等帮助，情节严重", "正常使用网络", "正常上网", "正常购物"],answer:0,explanation:"帮助信息网络犯罪活动罪是指明知他人利用信息网络实施犯罪，为其犯罪提供互联网接入、服务器托管、网络存储、通讯传输等技术支持，或者提供广告推广、支付结算等帮助，情节严重的行为。"},{id:"cs-3615",module:"changshi",prompt:"行政行为的合法要件不包括？",options:["必须经过公证", "主体合法", "内容合法", "程序合法"],answer:0,explanation:"行政行为的合法要件包括主体合法、内容合法、程序合法等；公证不是合法要件。"},{id:"cs-3616",module:"changshi",prompt:"行政行为的撤销的法律后果是？",options:["该行政行为自始失去法律效力", "仅向后失效", "继续有效", "部分有效"],answer:0,explanation:"行政行为被撤销的，该行政行为自始失去法律效力，但撤销对公共利益有重大影响的除外。"},{id:"cs-3617",module:"changshi",prompt:"行政行为的废止的法律后果是？",options:["该行政行为自废止之日起失去法律效力", "自始无效", "继续有效", "部分有效"],answer:0,explanation:"行政行为被废止的，该行政行为自废止之日起失去法律效力，废止前的效力不受影响。"},{id:"cs-3618",module:"changshi",prompt:"行政行为的无效的情形不包括？",options:["程序轻微违法", "实施主体不具有行政主体资格", "没有依据", "内容重大且明显违法"],answer:0,explanation:"行政行为无效的情形包括实施主体不具有行政主体资格、没有依据、内容重大且明显违法等；程序轻微违法属于确认违法的情形。"},{id:"cs-3619",module:"changshi",prompt:"行政行为的效力开始于？",options:["行政行为作出并送达时", "当事人知道时", "法院判决时", "上级批准时"],answer:0,explanation:"行政行为自作出并送达时开始发生效力，法律另有规定的除外。"},{id:"cs-3620",module:"changshi",prompt:"行政行为的变更的法律后果是？",options:["行政行为部分内容改变，效力部分或全部改变", "自始无效", "继续有效", "部分无效"],answer:0,explanation:"行政行为被变更的，行政行为部分内容改变，效力部分或全部改变。"},{id:"cs-3621",module:"changshi",prompt:"行政行为的补正的法律后果是？",options:["程序瑕疵不影响行为效力的，可以补正", "一律无效", "一律撤销", "一律变更"],answer:0,explanation:"行政行为的程序瑕疵不影响行为效力的，可以补正；补正后行政行为继续有效。"},{id:"cs-3622",module:"changshi",prompt:"行政行为的生效要件不包括？",options:["必须经过公证", "行政主体合法", "内容合法", "程序合法"],answer:0,explanation:"行政行为的生效要件包括行政主体合法、内容合法、程序合法等；公证不是生效要件。"},{id:"cs-3623",module:"changshi",prompt:"行政行为的失效情形不包括？",options:["相对人同意", "行政行为被撤销", "行政行为被废止", "行政行为被变更"],answer:0,explanation:"行政行为的失效情形包括被撤销、被废止、被变更等；相对人同意不是失效情形。"},{id:"cs-3624",module:"changshi",prompt:"行政行为的追溯力是指？",options:["行政行为对作出前的事项是否有效力", "行政行为对作出后的事项是否有效力", "行政行为对第三人的效力", "行政行为对国家的效力"],answer:0,explanation:"行政行为的追溯力是指行政行为对作出前的事项是否有效力；一般行政行为不具有追溯力。"},{id:"cs-3625",module:"changshi",prompt:"劳动合同的约定条款包括？",options:["试用期、培训、保守秘密、补充保险和福利待遇等", "仅试用期", "仅培训", "仅福利"],answer:0,explanation:"劳动合同除必备条款外，用人单位与劳动者可以约定试用期、培训、保守秘密、补充保险和福利待遇等其他事项。"},{id:"cs-3626",module:"changshi",prompt:"竞业限制的适用对象是？",options:["高级管理人员、高级技术人员和其他负有保密义务的人员", "所有员工", "仅普通员工", "仅实习生"],answer:0,explanation:"竞业限制适用于用人单位的高级管理人员、高级技术人员和其他负有保密义务的人员。"},{id:"cs-3627",module:"changshi",prompt:"竞业限制的期限不得超过？",options:["2年", "1年", "3年", "5年"],answer:0,explanation:"竞业限制期限不得超过2年。"},{id:"cs-3628",module:"changshi",prompt:"竞业限制的经济补偿标准是？",options:["在竞业限制期限内按月给予劳动者经济补偿", "一次性支付", "无需补偿", "由劳动者承担"],answer:0,explanation:"用人单位应当在竞业限制期限内按月给予劳动者经济补偿；未支付补偿的，劳动者可以请求解除竞业限制约定。"},{id:"cs-3629",module:"changshi",prompt:"服务期的适用条件是？",options:["用人单位为劳动者提供专项培训费用，进行专业技术培训", "所有员工", "仅试用期员工", "仅实习生"],answer:0,explanation:"用人单位为劳动者提供专项培训费用，对其进行专业技术培训的，可以与该劳动者订立协议，约定服务期。"},{id:"cs-3630",module:"changshi",prompt:"违反服务期约定的违约金数额不得超过？",options:["用人单位提供的培训费用", "劳动者工资", "用人单位利润", "双方协商"],answer:0,explanation:"违反服务期约定的，劳动者应当按照约定向用人单位支付违约金，违约金的数额不得超过用人单位提供的培训费用。"},{id:"cs-3631",module:"changshi",prompt:"根据劳动合同法，保密义务的期限是？",options:["在职期间及离职后（商业秘密存续期间）", "仅在职期间", "仅离职后", "无期限"],answer:0,explanation:"劳动者对用人单位的商业秘密和与知识产权相关的保密事项负有保密义务，期限不限于在职期间。"},{id:"cs-3632",module:"changshi",prompt:"用人单位的规章制度应当？",options:["经民主程序制定，并公示或告知劳动者", "仅领导决定", "仅口头告知", "无需公示"],answer:0,explanation:"用人单位的规章制度应当经职工代表大会或者全体职工讨论，提出方案和意见，与工会或者职工代表平等协商确定，并公示或告知劳动者。"},{id:"cs-3633",module:"changshi",prompt:"用人单位拖欠劳动报酬的，劳动者可以？",options:["依法向人民法院申请支付令", "直接起诉", "直接仲裁", "直接执行"],answer:0,explanation:"用人单位拖欠或者未足额支付劳动报酬的，劳动者可以依法向当地人民法院申请支付令。"},{id:"cs-3634",module:"changshi",prompt:"经济性裁员的优先留用人员不包括？",options:["新入职员工", "与本单位订立较长期限的固定期限劳动合同的", "与本单位订立无固定期限劳动合同的", "家庭无其他就业人员，有需要扶养的老人或者未成年人的"],answer:0,explanation:"经济性裁员时，应当优先留用与本单位订立较长期限固定期限劳动合同、无固定期限劳动合同的人员，以及家庭无其他就业人员、有需要扶养的老人或未成年人的人员。"},{id:"cs-3635",module:"changshi",prompt:"用人单位应当在解除或终止劳动合同时出具？",options:["解除或者终止劳动合同的证明", "仅工资单", "仅社保单", "仅离职证明"],answer:0,explanation:"用人单位应当在解除或者终止劳动合同时出具解除或者终止劳动合同的证明，并在15日内为劳动者办理档案和社会保险关系转移手续。"},{id:"cs-3636",module:"changshi",prompt:"用人单位对已经解除或者终止的劳动合同的文本，至少保存？",options:["2年备查", "1年备查", "3年备查", "5年备查"],answer:0,explanation:"用人单位对已经解除或者终止的劳动合同的文本，至少保存2年备查。"},{id:"cs-3637",module:"changshi",prompt:"劳务派遣单位应当依照公司法的有关规定设立，注册资本不得少于？",options:["200万元", "100万元", "50万元", "500万元"],answer:0,explanation:"劳务派遣单位应当依照公司法的有关规定设立，注册资本不得少于200万元。"},{id:"cs-3638",module:"changshi",prompt:"用工单位不得将被派遣劳动者再派遣到？",options:["其他用人单位", "本单位", "关联单位", "子公司"],answer:0,explanation:"用工单位不得将被派遣劳动者再派遣到其他用人单位。"},{id:"cs-3639",module:"changshi",prompt:"反垄断法规定，垄断协议的豁免需要满足的条件不包括？",options:["损害消费者利益", "为实现特定目的所必需", "不会严重限制相关市场的竞争", "能够使消费者分享由此产生的利益"],answer:0,explanation:"垄断协议的豁免需要满足为实现特定目的所必需、不会严重限制相关市场的竞争、能够使消费者分享由此产生的利益等条件；损害消费者利益的行为不能豁免。"},{id:"cs-3640",module:"changshi",prompt:"反垄断法规定，滥用市场支配地位的行为不包括？",options:["正常定价", "以不公平的高价销售商品或者以不公平的低价购买商品", "没有正当理由，以低于成本的价格销售商品", "没有正当理由，拒绝与交易相对人进行交易"],answer:0,explanation:"滥用市场支配地位的行为包括不公平高价或低价、低于成本销售、拒绝交易、限定交易、搭售、差别待遇等；正常定价不属于。"},{id:"cs-3641",module:"changshi",prompt:"法律规则的结构不包括？",options:["法律后果的执行方式", "假定条件", "行为模式", "法律后果"],answer:0,explanation:"法律规则的结构包括假定条件、行为模式和法律后果三部分。"},{id:"cs-3642",module:"changshi",prompt:"法律规则的行为模式不包括？",options:["评价模式", "可为模式", "应为模式", "勿为模式"],answer:0,explanation:"法律规则的行为模式包括可为模式（授权性）、应为模式（命令性）和勿为模式（禁止性）。"},{id:"cs-3643",module:"changshi",prompt:"法律规则的法律后果包括？",options:["肯定性后果和否定性后果", "积极后果和消极后果", "奖励和惩罚", "权利和义务"],answer:0,explanation:"法律规则的法律后果包括肯定性后果（合法后果）和否定性后果（违法后果）。"},{id:"cs-3644",module:"changshi",prompt:"法律原则的适用条件不包括？",options:["可以随意适用", "穷尽法律规则后才能适用法律原则", "为实现个案正义", "有充分理由"],answer:0,explanation:"法律原则的适用应当穷尽法律规则后才能适用，为实现个案正义，并且有充分理由；不能随意适用。"},{id:"cs-3645",module:"changshi",prompt:"法律解释的体制是指？",options:["法律解释权的配置和法律解释的效力等级", "法律解释的方法", "法律解释的主体", "法律解释的对象"],answer:0,explanation:"法律解释的体制是指法律解释权的配置和法律解释的效力等级。"},{id:"cs-3646",module:"changshi",prompt:"法理学上，法律推理的前提是？",options:["法律规范和案件事实", "道德规范", "政策", "习惯"],answer:0,explanation:"法律推理的前提是法律规范和案件事实，通过推理将法律规范适用于案件事实。"},{id:"cs-3647",module:"changshi",prompt:"法律适用的基本步骤是？",options:["查明案件事实、确定法律规范、进行法律推理", "仅查明事实", "仅确定规范", "仅推理"],answer:0,explanation:"法律适用的基本步骤是查明案件事实、确定法律规范、进行法律推理，得出法律结论。"},{id:"cs-3648",module:"changshi",prompt:"法理学上，法律监督的客体是？",options:["所有国家机关、社会组织和公民的活动", "仅国家机关", "仅公民", "仅社会组织"],answer:0,explanation:"法律监督的客体是所有国家机关、社会组织和公民的活动，重点是国家机关及其工作人员的公务活动。"},{id:"cs-3649",module:"changshi",prompt:"法律意识的分类不包括？",options:["法律潜意识", "个人法律意识", "群体法律意识", "社会法律意识"],answer:0,explanation:"法律意识按照主体分为个人法律意识、群体法律意识和社会法律意识；法律潜意识不是规范分类。"},{id:"cs-3650",module:"changshi",prompt:"法律文化的构成不包括？",options:["法律潜意识", "法律制度", "法律思想", "法律设施"],answer:0,explanation:"法律文化的构成包括法律制度、法律思想、法律设施等；法律潜意识不是规范构成。"});
(window.YC_CS_BANK=window.YC_CS_BANK||[]).push({id:"cs-3651",module:"changshi",prompt:"我国宪法规定，国家保护在中国境内的外国人合法权益，在中国境内的外国人必须？",options:["遵守中华人民共和国的法律", "遵守国际法", "遵守本国法律", "遵守宗教教义"],answer:0,explanation:"宪法规定，中华人民共和国保护在中国境内的外国人的合法权利和利益，在中国境内的外国人必须遵守中华人民共和国的法律。"},{id:"cs-3652",module:"changshi",prompt:"我国宪法规定，中华人民共和国对于因为政治原因要求避难的外国人，可以给予？",options:["受庇护的权利", "永久居留权", "国籍", "豁免权"],answer:0,explanation:"宪法规定，中华人民共和国对于因为政治原因要求避难的外国人，可以给予受庇护的权利。"},{id:"cs-3653",module:"changshi",prompt:"我国宪法规定，国家维护社会秩序，镇压危害国家安全的犯罪活动，制裁危害社会治安、破坏社会主义经济和其他犯罪的活动，惩办和改造？",options:["犯罪分子", "违法人员", "违纪人员", "失信人员"],answer:0,explanation:"宪法规定，国家维护社会秩序，镇压危害国家安全的犯罪活动，制裁危害社会治安、破坏社会主义经济和其他犯罪的活动，惩办和改造犯罪分子。"},{id:"cs-3654",module:"changshi",prompt:"我国宪法规定，国家合理安排积累和消费，兼顾？",options:["国家、集体和个人的利益", "国家利益", "集体利益", "个人利益"],answer:0,explanation:"宪法规定，国家合理安排积累和消费，兼顾国家、集体和个人的利益，在发展生产的基础上，逐步改善人民的物质生活和文化生活。"},{id:"cs-3655",module:"changshi",prompt:"我国宪法规定，国家发展医疗卫生事业，发展现代医药和我国传统医药，鼓励和支持？",options:["农村集体经济组织、国家企业事业组织和街道组织举办各种医疗卫生设施", "私人医院", "外资医院", "个体诊所"],answer:0,explanation:"宪法规定，国家发展医疗卫生事业，发展现代医药和我国传统医药，鼓励和支持农村集体经济组织、国家企业事业组织和街道组织举办各种医疗卫生设施，开展群众性的卫生活动。"},{id:"cs-3656",module:"changshi",prompt:"我国宪法规定，国家发展体育事业，开展群众性的体育活动，增强？",options:["人民体质", "国家实力", "经济实力", "科技实力"],answer:0,explanation:"宪法规定，国家发展体育事业，开展群众性的体育活动，增强人民体质。"},{id:"cs-3657",module:"changshi",prompt:"我国宪法规定，国家发展为人民服务、为社会主义服务的文学艺术事业、新闻广播电视事业、出版发行事业、图书馆博物馆文化馆和其他文化事业，开展？",options:["群众性的文化活动", "商业性文化活动", "国际文化交流", "宗教活动"],answer:0,explanation:"宪法规定，国家发展为人民服务、为社会主义服务的文学艺术事业、新闻广播电视事业、出版发行事业、图书馆博物馆文化馆和其他文化事业，开展群众性的文化活动。"},{id:"cs-3658",module:"changshi",prompt:"我国宪法规定，国家保护名胜古迹、珍贵文物和其他重要？",options:["历史文化遗产", "自然资源", "矿产资源", "森林资源"],answer:0,explanation:"宪法规定，国家保护名胜古迹、珍贵文物和其他重要历史文化遗产。"},{id:"cs-3659",module:"changshi",prompt:"我国宪法规定，国家组织和鼓励植树造林，保护？",options:["林木", "矿产", "水源", "土地"],answer:0,explanation:"宪法规定，国家组织和鼓励植树造林，保护林木。"},{id:"cs-3660",module:"changshi",prompt:"我国宪法规定，国家加强武装力量的革命化、现代化、正规化建设，增强？",options:["国防力量", "经济实力", "科技实力", "文化实力"],answer:0,explanation:"宪法规定，国家加强武装力量的革命化、现代化、正规化建设，增强国防力量。"},{id:"cs-3661",module:"changshi",prompt:"我国宪法规定，国家在社会主义初级阶段，坚持公有制为主体、多种所有制经济共同发展的基本经济制度，坚持按劳分配为主体、多种分配方式并存的？",options:["分配制度", "经济制度", "政治制度", "法律制度"],answer:0,explanation:"宪法规定，国家在社会主义初级阶段，坚持公有制为主体、多种所有制经济共同发展的基本经济制度，坚持按劳分配为主体、多种分配方式并存的分配制度。"},{id:"cs-3662",module:"changshi",prompt:"我国宪法规定，国有经济是社会主义全民所有制经济，是国民经济中的？",options:["主导力量", "补充力量", "辅助力量", "次要力量"],answer:0,explanation:"宪法规定，国有经济是社会主义全民所有制经济，是国民经济中的主导力量。"},{id:"cs-3663",module:"changshi",prompt:"我国宪法规定，农村集体经济组织实行家庭承包经营为基础、统分结合的？",options:["双层经营体制", "单一经营体制", "集体经营体制", "个体经营体制"],answer:0,explanation:"宪法规定，农村集体经济组织实行家庭承包经营为基础、统分结合的双层经营体制。"},{id:"cs-3664",module:"changshi",prompt:"我国宪法规定，国家鼓励、支持和引导非公有制经济的发展，并对非公有制经济依法实行？",options:["监督和管理", "全面国有化", "限制发展", "取消登记"],answer:0,explanation:"宪法规定，国家保护个体经济、私营经济等非公有制经济的合法的权利和利益，国家鼓励、支持和引导非公有制经济的发展，并对非公有制经济依法实行监督和管理。"},{id:"cs-3665",module:"changshi",prompt:"我国宪法规定，国家实行社会主义？",options:["市场经济", "计划经济", "混合经济", "自然经济"],answer:0,explanation:"宪法规定，国家实行社会主义市场经济。"},{id:"cs-3666",module:"changshi",prompt:"我国宪法规定，国家加强经济立法，完善？",options:["宏观调控", "微观管理", "计划管理", "行政干预"],answer:0,explanation:"宪法规定，国家加强经济立法，完善宏观调控。"},{id:"cs-3667",module:"changshi",prompt:"我国宪法规定，国家依法禁止任何组织或者个人扰乱？",options:["社会经济秩序", "政治秩序", "文化秩序", "军事秩序"],answer:0,explanation:"宪法规定，国家依法禁止任何组织或者个人扰乱社会经济秩序。"},{id:"cs-3668",module:"changshi",prompt:"行政法上的行政主体是指？",options:["依法享有行政职权，能以自己的名义行使职权并独立承担责任的组织", "所有行政机关工作人员", "所有国家机关", "所有社会组织"],answer:0,explanation:"行政主体是依法享有行政职权，能以自己的名义行使职权，并独立承担法律责任的组织。"},{id:"cs-3669",module:"changshi",prompt:"行政主体的范围不包括？",options:["公务员个人", "行政机关", "法律法规授权的组织", "受委托的组织（以委托机关名义）"],answer:0,explanation:"行政主体包括行政机关和法律法规授权的组织；公务员个人不是行政主体，受委托的组织以委托机关的名义行使职权。"},{id:"cs-3670",module:"changshi",prompt:"行政法律关系的特征不包括？",options:["双方地位完全平等", "一方是行政主体", "具有隶属性", "具有非对等性"],answer:0,explanation:"行政法律关系的特征包括一方是行政主体、具有隶属性和非对等性等；双方地位完全平等是民事法律关系的特征。"},{id:"cs-3671",module:"changshi",prompt:"行政法律关系的客体不包括？",options:["行政主体的工作人员", "物", "行为", "人身权益"],answer:0,explanation:"行政法律关系的客体包括物、行为和人身权益等；行政主体的工作人员不是客体。"},{id:"cs-3672",module:"changshi",prompt:"行政行为的分类不包括？",options:["民事行为与刑事行为", "抽象行政行为与具体行政行为", "羁束行政行为与自由裁量行政行为", "依职权行政行为与依申请行政行为"],answer:0,explanation:"行政行为的分类包括抽象与具体、羁束与自由裁量、依职权与依申请等；民事行为与刑事行为不是行政行为的分类。"},{id:"cs-3673",module:"changshi",prompt:"行政法理论上，羁束行政行为是指？",options:["法律对行为的范围、条件、方式等作了明确规定的行政行为", "法律未作明确规定的行政行为", "需要协商的行政行为", "需要批准的行政行为"],answer:0,explanation:"羁束行政行为是指法律对行为的范围、条件、方式等作了明确规定的行政行为，行政主体没有选择余地。"},{id:"cs-3674",module:"changshi",prompt:"自由裁量行政行为是指？",options:["法律仅规定行为的范围、条件、幅度等，行政主体可以在法定范围内选择", "法律未作规定的行政行为", "需要协商的行政行为", "需要批准的行政行为"],answer:0,explanation:"自由裁量行政行为是指法律仅规定行为的范围、条件、幅度等，行政主体可以在法定范围内选择的行为。"},{id:"cs-3675",module:"changshi",prompt:"依职权行政行为是指？",options:["行政主体不需要相对人申请，主动作出的行政行为", "需要相对人申请的行政行为", "需要批准的行政行为", "需要协商的行政行为"],answer:0,explanation:"依职权行政行为是指行政主体不需要相对人申请，主动作出的行政行为，如行政处罚。"},{id:"cs-3676",module:"changshi",prompt:"依申请行政行为是指？",options:["行政主体需要相对人申请才能作出的行政行为", "行政主体主动作出的行政行为", "需要批准的行政行为", "需要协商的行政行为"],answer:0,explanation:"依申请行政行为是指行政主体需要相对人申请才能作出的行政行为，如行政许可。"},{id:"cs-3677",module:"changshi",prompt:"根据刑法规定，强奸罪的客体是？",options:["妇女的性自主权", "妇女的生命权", "妇女的健康权", "妇女的人身自由权"],answer:0,explanation:"强奸罪的客体是妇女的性自主权。"},{id:"cs-3678",module:"changshi",prompt:"根据刑法规定，抢劫罪的客体是？",options:["公私财物的所有权和他人的人身权利", "仅公私财物的所有权", "仅他人的人身权利", "国家利益"],answer:0,explanation:"抢劫罪的客体是复杂客体，既侵犯公私财物的所有权，又侵犯他人的人身权利。"},{id:"cs-3679",module:"changshi",prompt:"根据刑法规定，盗窃罪的客体是？",options:["公私财物的所有权", "他人的人身权利", "国家利益", "社会秩序"],answer:0,explanation:"盗窃罪的客体是公私财物的所有权。"},{id:"cs-3680",module:"changshi",prompt:"根据刑法规定，诈骗罪的客体是？",options:["公私财物的所有权", "他人的人身权利", "国家利益", "社会秩序"],answer:0,explanation:"诈骗罪的客体是公私财物的所有权。"},{id:"cs-3681",module:"changshi",prompt:"根据刑法规定，贪污罪的客体是？",options:["公共财物的所有权和国家工作人员职务行为的廉洁性", "仅公共财物的所有权", "仅职务行为的廉洁性", "国家利益"],answer:0,explanation:"贪污罪的客体是复杂客体，既侵犯公共财物的所有权，又侵犯国家工作人员职务行为的廉洁性。"},{id:"cs-3682",module:"changshi",prompt:"根据刑法规定，受贿罪的客体是？",options:["国家工作人员职务行为的廉洁性", "公共财物的所有权", "他人的人身权利", "社会秩序"],answer:0,explanation:"受贿罪的客体是国家工作人员职务行为的廉洁性。"},{id:"cs-3683",module:"changshi",prompt:"根据刑法规定，失火罪的客体是？",options:["公共安全", "他人的人身权利", "公私财物的所有权", "社会秩序"],answer:0,explanation:"失火罪的客体是公共安全。"},{id:"cs-3684",module:"changshi",prompt:"根据刑法规定，放火罪的客体是？",options:["公共安全", "他人的人身权利", "公私财物的所有权", "社会秩序"],answer:0,explanation:"放火罪的客体是公共安全。"},{id:"cs-3685",module:"changshi",prompt:"故意伤害罪的加重情节不包括？",options:["致人轻微伤", "致人重伤", "致人死亡", "以特别残忍手段致人重伤造成严重残疾"],answer:0,explanation:"故意伤害罪的加重情节包括致人重伤、致人死亡、以特别残忍手段致人重伤造成严重残疾；致人轻微伤不构成犯罪。"},{id:"cs-3686",module:"changshi",prompt:"诈骗罪的加重情节不包括？",options:["诈骗未遂", "数额巨大", "数额特别巨大", "有其他特别严重情节"],answer:0,explanation:"诈骗罪的加重情节包括数额巨大或者有其他严重情节、数额特别巨大或者有其他特别严重情节；诈骗未遂不构成加重情节。"},{id:"cs-3687",module:"changshi",prompt:"贪污罪的加重情节不包括？",options:["贪污数额特别巨大", "贪污数额巨大", "有其他特别严重情节", "贪污数额较小"],answer:0,explanation:"贪污罪的加重情节包括贪污数额巨大、数额特别巨大或有其他特别严重情节等；贪污数额较小不构成加重情节。"},{id:"cs-3688",module:"changshi",prompt:"受贿罪的加重情节不包括？",options:["受贿数额较小", "受贿数额巨大", "受贿数额特别巨大", "有其他特别严重情节"],answer:0,explanation:"受贿罪的加重情节包括受贿数额巨大、数额特别巨大或有其他特别严重情节等；受贿数额较小不构成加重情节。"},{id:"cs-3689",module:"changshi",prompt:"挪用公款罪的加重情节不包括？",options:["挪用公款数额较小", "挪用公款数额巨大", "挪用公款用于非法活动", "挪用公款数额较大、超过三个月未还"],answer:0,explanation:"挪用公款罪的加重情节包括挪用公款数额巨大、用于非法活动、数额较大超过三个月未还等；挪用公款数额较小不构成加重情节。"},{id:"cs-3690",module:"changshi",prompt:"民事诉讼中，普通程序的审限为？",options:["6个月", "3个月", "1年", "2年"],answer:0,explanation:"人民法院适用普通程序审理的一审民事案件，应当在立案之日起6个月内审结。"},{id:"cs-3691",module:"changshi",prompt:"民事诉讼中，简易程序的审限为？",options:["3个月", "6个月", "1年", "2年"],answer:0,explanation:"人民法院适用简易程序审理的一审民事案件，应当在立案之日起3个月内审结。"},{id:"cs-3692",module:"changshi",prompt:"民事诉讼中，第二审人民法院审理上诉案件的审限为？",options:["3个月（判决）/30日（裁定）", "6个月", "1年", "2年"],answer:0,explanation:"人民法院审理对判决的上诉案件，应当在第二审立案之日起3个月内审结；审理对裁定的上诉案件，应当在30日内作出终审裁定。"},{id:"cs-3693",module:"changshi",prompt:"民事诉讼中，特别程序的审限为？",options:["30日内（选民资格案件必须在选举日前审结）", "3个月", "6个月", "1年"],answer:0,explanation:"适用特别程序审理的案件，应当在立案之日起30日内或者公告期满后30日内审结；选民资格案件必须在选举日前审结。"},{id:"cs-3694",module:"changshi",prompt:"民事诉讼中，督促程序的申请条件不包括？",options:["双方存在重大争议", "请求给付金钱或汇票、本票、支票等", "债权人与债务人没有其他债务纠纷", "支付令能够送达债务人"],answer:0,explanation:"债权人请求债务人给付金钱、有价证券，符合债权人与债务人没有其他债务纠纷、支付令能够送达债务人等条件的，可以申请支付令；双方存在重大争议的不适用督促程序。"},{id:"cs-3695",module:"changshi",prompt:"民事诉讼中，公示催告程序的适用范围是？",options:["可以背书转让的票据被盗、遗失或者灭失", "所有案件", "仅合同纠纷", "仅侵权纠纷"],answer:0,explanation:"公示催告程序适用于按照规定可以背书转让的票据被盗、遗失或者灭失，以及法律规定可以申请公示催告的其他事项。"},{id:"cs-3696",module:"changshi",prompt:"民事诉讼中，执行程序的启动方式不包括？",options:["自动执行", "申请执行", "移送执行", "委托执行"],answer:0,explanation:"执行程序的启动方式包括申请执行、移送执行和委托执行；不存在自动执行。"},{id:"cs-3697",module:"changshi",prompt:"民事诉讼中，执行异议的提出主体是？",options:["案外人和当事人", "仅案外人", "仅当事人", "仅第三人"],answer:0,explanation:"执行过程中，案外人对执行标的提出书面异议的，人民法院应当自收到书面异议之日起15日内审查；当事人、利害关系人认为执行行为违反法律规定的，可以提出书面异议。"},{id:"cs-3698",module:"changshi",prompt:"民事诉讼中，执行和解是指？",options:["双方当事人在执行中自行和解达成协议", "法院强制和解", "第三人调解", "仲裁"],answer:0,explanation:"执行中，双方当事人自行和解达成协议的，执行员应当将协议内容记入笔录，由双方当事人签名或者盖章。"},{id:"cs-3699",module:"changshi",prompt:"民事诉讼中，执行担保是指？",options:["被执行人向人民法院提供担保，经申请执行人同意，可以暂缓执行", "申请执行人提供担保", "第三人提供担保", "国家提供担保"],answer:0,explanation:"被执行人向人民法院提供担保，并经申请执行人同意的，人民法院可以决定暂缓执行及暂缓执行的期限。"},{id:"cs-3700",module:"changshi",prompt:"民事诉讼中，执行中止的情形不包括？",options:["被执行人有财产可供执行", "申请人表示可以延期执行", "案外人对执行标的提出确有理由的异议", "作为一方当事人的公民死亡，需要等待继承人继承权利或者承担义务"],answer:0,explanation:"执行中止的情形包括申请人表示可以延期执行、案外人对执行标的提出确有理由的异议、当事人死亡需要等待继承人等；被执行人有财产可供执行不构成中止。"},{id:"cs-3701",module:"changshi",prompt:"民事诉讼中，执行终结的情形不包括？",options:["被执行人暂无财产", "申请人撤销申请", "据以执行的法律文书被撤销", "作为被执行人的公民死亡，无遗产可供执行，又无义务承担人"],answer:0,explanation:"执行终结的情形包括申请人撤销申请、据以执行的法律文书被撤销、被执行人死亡无遗产无义务承担人等；被执行人暂无财产不构成终结。"},{id:"cs-3702",module:"changshi",prompt:"民事诉讼中，涉外民事诉讼的期间可以？",options:["适当延长", "一律缩短", "一律不变", "由当事人决定"],answer:0,explanation:"涉外民事诉讼中，被告在中华人民共和国领域内没有住所的，人民法院可以适当延长答辩期、上诉期等期间。"},{id:"cs-3703",module:"changshi",prompt:"民事诉讼中，涉外财产保全的申请主体是？",options:["当事人", "仅原告", "仅被告", "仅第三人"],answer:0,explanation:"涉外民事诉讼中，当事人可以依照规定申请财产保全。"},{id:"cs-3704",module:"changshi",prompt:"民事诉讼中，司法协助的内容不包括？",options:["代为执行刑罚", "代为送达文书", "代为调查取证", "代为承认和执行判决、仲裁裁决"],answer:0,explanation:"司法协助的内容包括代为送达文书、代为调查取证、代为承认和执行判决或仲裁裁决等；代为执行刑罚不属于司法协助。"},{id:"cs-3705",module:"changshi",prompt:"民事诉讼中，一般司法协助可以由？",options:["缔约国法院之间根据条约或外交途径进行", "仅通过外交途径", "仅通过国际组织", "仅通过个人"],answer:0,explanation:"一般司法协助可以由缔约国法院之间根据条约或外交途径进行，也可以通过外交途径进行。"},{id:"cs-3706",module:"changshi",prompt:"民事诉讼中，对外国法院判决的承认和执行，应当？",options:["符合我国法律规定的条件", "一律承认", "一律拒绝", "由当事人决定"],answer:0,explanation:"对外国法院判决的承认和执行，应当符合我国法律规定的条件，如该国与我国有条约关系或互惠关系，判决已生效等。"},{id:"cs-3707",module:"changshi",prompt:"民事诉讼中，对外国仲裁裁决的承认和执行，适用？",options:["《纽约公约》或双边条约的规定", "仅国内法", "仅国际惯例", "由当事人决定"],answer:0,explanation:"对外国仲裁裁决的承认和执行，适用《承认及执行外国仲裁裁决公约》（《纽约公约》）或双边条约的规定。"},{id:"cs-3708",module:"changshi",prompt:"民事诉讼中，仲裁裁决的执行由谁管辖？",options:["被执行人住所地或者被执行的财产所在地人民法院", "仲裁委员会所在地法院", "申请人住所地法院", "任何法院"],answer:0,explanation:"仲裁裁决的执行由被执行人住所地或者被执行的财产所在地人民法院管辖。"},{id:"cs-3709",module:"changshi",prompt:"民事诉讼中，公证债权文书的执行由谁管辖？",options:["被执行人住所地或者被执行的财产所在地人民法院", "公证处所在地法院", "申请人住所地法院", "任何法院"],answer:0,explanation:"对公证机关依法赋予强制执行效力的公证债权文书，由被执行人住所地或者被执行的财产所在地人民法院执行。"},{id:"cs-3710",module:"changshi",prompt:"反垄断法规定，经营者集中的申报标准由谁规定？",options:["国务院", "全国人大常委会", "最高人民法院", "国家市场监督管理总局"],answer:0,explanation:"经营者集中达到国务院规定的申报标准的，经营者应当事先向国务院反垄断执法机构申报。"},{id:"cs-3711",module:"changshi",prompt:"反垄断法规定，滥用行政权力排除、限制竞争的行为不包括？",options:["正常的市场竞争", "限定或者变相限定单位或者个人经营、购买、使用其指定的经营者提供的商品", "妨碍商品在地区之间自由流通", "排斥或者限制外地经营者在本地投资"],answer:0,explanation:"滥用行政权力排除、限制竞争的行为包括限定交易、妨碍商品自由流通、排斥限制外地经营者投资等；正常的市场竞争不属于。"},{id:"cs-3712",module:"changshi",prompt:"反不正当竞争法规定，商业贿赂的对象不包括？",options:["普通消费者", "交易相对方的工作人员", "受交易相对方委托办理相关事务的单位或者个人", "利用职权或影响力影响交易的单位或者个人"],answer:0,explanation:"商业贿赂的对象包括交易相对方的工作人员、受交易相对方委托办理相关事务的单位或个人、利用职权或影响力影响交易的单位或个人；普通消费者不是商业贿赂的对象。"},{id:"cs-3713",module:"changshi",prompt:"消费者权益保护法规定，经营者应当保证其提供的商品或者服务符合保障人身、财产安全的要求，对可能危及人身、财产安全的商品和服务，应当？",options:["向消费者作出真实的说明和明确的警示，并说明和标明正确使用商品或接受服务的方法以及防止危害发生的方法", "仅提供商品", "不作说明", "隐瞒风险"],answer:0,explanation:"经营者应当保证其提供的商品或者服务符合保障人身、财产安全的要求；对可能危及人身、财产安全的商品和服务，应当向消费者作出真实的说明和明确的警示。"});
(window.YC_CS_BANK=window.YC_CS_BANK||[]).push({id:"cs-3714",module:"changshi",prompt:"全国人民代表大会的职权不包括？",options:["直接审理刑事案件", "修改宪法", "监督宪法的实施", "制定和修改刑事、民事、国家机构的和其他的基本法律"],answer:0,explanation:"全国人民代表大会的职权包括修改宪法、监督宪法实施、制定和修改基本法律等；不直接审理刑事案件。"},{id:"cs-3715",module:"changshi",prompt:"全国人民代表大会常务委员会的职权不包括？",options:["直接审理民事案件", "解释宪法", "监督宪法的实施", "制定和修改除应当由全国人民代表大会制定的法律以外的其他法律"],answer:0,explanation:"全国人大常委会的职权包括解释宪法、监督宪法实施、制定和修改非基本法律等；不直接审理民事案件。"},{id:"cs-3716",module:"changshi",prompt:"全国人民代表大会常务委员会委员长、副委员长的连续任职不得超过？",options:["两届", "一届", "三届", "没有限制"],answer:0,explanation:"全国人大常委会委员长、副委员长连续任职不得超过两届。"},{id:"cs-3717",module:"changshi",prompt:"国务院的职权不包括？",options:["直接审理行政案件", "规定行政措施，制定行政法规，发布决定和命令", "统一领导全国性行政工作", "改变或者撤销各部、各委员会发布的不适当的命令、指示和规章"],answer:0,explanation:"国务院的职权包括规定行政措施、制定行政法规、统一领导全国性行政工作等；不直接审理行政案件。"},{id:"cs-3718",module:"changshi",prompt:"国务院各部、各委员会的设立、撤销或者合并由谁决定？",options:["全国人民代表大会或全国人民代表大会常务委员会", "国务院自行决定", "国家主席决定", "中共中央决定"],answer:0,explanation:"国务院各部、各委员会的设立、撤销或者合并，经总理提出，由全国人民代表大会决定；在全国人大闭会期间，由全国人大常委会决定。"},{id:"cs-3719",module:"changshi",prompt:"中央军事委员会的组成人员包括？",options:["主席、副主席若干人、委员若干人", "仅主席", "仅副主席", "仅委员"],answer:0,explanation:"中央军事委员会由主席、副主席若干人、委员若干人组成，实行主席负责制。"},{id:"cs-3720",module:"changshi",prompt:"地方各级人民政府的职权不包括？",options:["直接审理行政案件", "执行本级人民代表大会及其常务委员会的决议", "执行上级国家行政机关的决定和命令", "管理本行政区域内的行政工作"],answer:0,explanation:"地方各级人民政府的职权包括执行本级人大及其常委会的决议、执行上级国家行政机关的决定和命令、管理本行政区域内的行政工作等；不直接审理行政案件。"},{id:"cs-3721",module:"changshi",prompt:"地方各级人民代表大会的职权不包括？",options:["直接审理民事案件", "在本行政区域内保证宪法、法律、行政法规的遵守和执行", "选举本级人民政府的省长、副省长、市长、副市长等", "改变或者撤销本级人民政府的不适当的决定和命令"],answer:0,explanation:"地方各级人民代表大会的职权包括保证宪法法律遵守执行、选举本级政府领导人员、改变撤销本级政府不适当的决定等；不直接审理民事案件。"},{id:"cs-3722",module:"changshi",prompt:"县级以上的地方各级人民代表大会常务委员会的职权不包括？",options:["直接审理刑事案件", "在本行政区域内保证宪法、法律、行政法规的遵守和执行", "讨论决定本行政区域内的重大事项", "监督本级人民政府、监察委员会、人民法院和人民检察院的工作"],answer:0,explanation:"县级以上地方各级人大常委会的职权包括保证宪法法律遵守执行、讨论决定重大事项、监督一府一委两院工作等；不直接审理刑事案件。"},{id:"cs-3723",module:"changshi",prompt:"乡镇人民代表大会的职权不包括？",options:["直接审理行政案件", "在本行政区域内保证宪法、法律、行政法规的遵守和执行", "选举本级人民代表大会主席团成员", "决定本行政区域内的经济、文化事业和公共事业的建设计划"],answer:0,explanation:"乡镇人民代表大会的职权包括保证宪法法律遵守执行、选举主席团成员、决定本行政区域内的经济文化事业和公共事业建设计划等；不直接审理行政案件。"},{id:"cs-3724",module:"changshi",prompt:"居民委员会的组成人员由谁选举产生？",options:["居民选举", "政府任命", "党委指定", "上级委派"],answer:0,explanation:"居民委员会主任、副主任和委员由居民选举产生。"},{id:"cs-3725",module:"changshi",prompt:"村民委员会的组成人员由谁选举产生？",options:["村民选举", "政府任命", "党委指定", "上级委派"],answer:0,explanation:"村民委员会主任、副主任和委员由村民直接选举产生。"},{id:"cs-3726",module:"changshi",prompt:"居民委员会和村民委员会的任期是？",options:["5年", "3年", "4年", "2年"],answer:0,explanation:"居民委员会和村民委员会每届任期5年，可以连选连任。"},{id:"cs-3727",module:"changshi",prompt:"监察委员会的组成人员包括？",options:["主任、副主任若干人、委员若干人", "仅主任", "仅副主任", "仅委员"],answer:0,explanation:"监察委员会由主任、副主任若干人、委员若干人组成，主任由本级人民代表大会选举产生。"},{id:"cs-3728",module:"changshi",prompt:"监察委员会的职权不包括？",options:["直接审理刑事案件", "对公职人员开展廉政教育", "对公职人员行使公权力的情况进行监督检查", "对涉嫌职务违法和职务犯罪进行调查"],answer:0,explanation:"监察委员会的职权包括对公职人员开展廉政教育、监督检查、调查职务违法和职务犯罪等；不直接审理刑事案件。"},{id:"cs-3729",module:"changshi",prompt:"人民法院的审判组织不包括？",options:["检察委员会", "独任庭", "合议庭", "审判委员会"],answer:0,explanation:"人民法院的审判组织包括独任庭、合议庭和审判委员会；检察委员会是人民检察院的组织。"},{id:"cs-3730",module:"changshi",prompt:"根据人民法院组织法，专门人民法院包括？",options:["军事法院、海事法院、知识产权法院、金融法院等", "仅军事法院", "仅海事法院", "仅知识产权法院"],answer:0,explanation:"专门人民法院包括军事法院、海事法院、知识产权法院、金融法院等。"},{id:"cs-3731",module:"changshi",prompt:"人民检察院的组织体系包括？",options:["最高人民检察院、地方各级人民检察院和专门人民检察院", "仅最高人民检察院", "仅地方各级人民检察院", "仅专门人民检察院"],answer:0,explanation:"人民检察院的组织体系包括最高人民检察院、地方各级人民检察院和专门人民检察院。"},{id:"cs-3732",module:"changshi",prompt:"监察机关的监察对象不包括？",options:["普通公民", "公务员", "国有企业管理人员", "公办事业单位管理人员"],answer:0,explanation:"监察机关的监察对象是所有行使公权力的公职人员，包括公务员、国企管理人员、公办事业单位管理人员等；普通公民不是监察对象。"},{id:"cs-3733",module:"changshi",prompt:"行政许可的审查方式不包括？",options:["刑事侦查", "书面审查", "实地核查", "听证"],answer:0,explanation:"行政许可的审查方式包括书面审查、实地核查、听证等；刑事侦查不属于行政许可程序。"},{id:"cs-3734",module:"changshi",prompt:"行政许可的决定方式不包括？",options:["刑事判决", "当场决定", "限期决定", "听证后决定"],answer:0,explanation:"行政许可的决定方式包括当场决定、限期决定、听证后决定等；刑事判决不属于行政许可决定。"},{id:"cs-3735",module:"changshi",prompt:"行政处罚的实施程序不包括？",options:["刑事侦查", "简易程序", "普通程序", "听证程序"],answer:0,explanation:"行政处罚的实施程序包括简易程序、普通程序和听证程序；刑事侦查不属于行政处罚程序。"},{id:"cs-3736",module:"changshi",prompt:"行政强制的实施程序不包括？",options:["刑事侦查", "行政强制措施程序", "行政强制执行程序", "代履行程序"],answer:0,explanation:"行政强制的实施程序包括行政强制措施程序、行政强制执行程序和代履行程序；刑事侦查不属于行政强制程序。"},{id:"cs-3737",module:"changshi",prompt:"行政强制措施的程序不包括？",options:["刑事侦查", "报批", "决定", "实施"],answer:0,explanation:"行政强制措施的程序包括报批、决定、实施等；刑事侦查不属于行政强制措施程序。"},{id:"cs-3738",module:"changshi",prompt:"行政强制执行的程序不包括？",options:["刑事侦查", "催告", "决定", "执行"],answer:0,explanation:"行政强制执行的程序包括催告、决定、执行等；刑事侦查不属于行政强制执行程序。"},{id:"cs-3739",module:"changshi",prompt:"代履行的适用条件不包括？",options:["必须经过法院判决", "排除妨碍、恢复原状等义务的履行", "当事人不履行", "经催告仍不履行"],answer:0,explanation:"代履行的适用条件是排除妨碍、恢复原状等义务的履行，当事人不履行，经催告仍不履行，其后果已经或者将危害交通安全、造成环境污染或者破坏自然资源等；不需要经过法院判决。"},{id:"cs-3740",module:"changshi",prompt:"行政协议的履行原则不包括？",options:["可以随意违约", "依法履行", "诚信履行", "合理履行"],answer:0,explanation:"行政协议的履行原则包括依法履行、诚信履行、合理履行等；可以随意违约不属于。"},{id:"cs-3741",module:"changshi",prompt:"行政协议的变更或解除的条件不包括？",options:["一方随意要求", "出现法定情形", "出现约定情形", "双方协商一致"],answer:0,explanation:"行政协议的变更或解除的条件包括出现法定情形、约定情形、双方协商一致等；一方随意要求不属于。"},{id:"cs-3742",module:"changshi",prompt:"行政赔偿的范围不包括？",options:["精神损害的金钱赔偿（致人精神损害造成严重后果的除外）", "人身权损害赔偿", "财产权损害赔偿", "精神损害抚慰金（造成严重后果的）"],answer:0,explanation:"行政赔偿的范围包括人身权损害赔偿、财产权损害赔偿、精神损害抚慰金（造成严重后果的）等；精神损害的金钱赔偿不属于一般赔偿范围。"},{id:"cs-3743",module:"changshi",prompt:"行政补偿的原则不包括？",options:["不予补偿", "依法补偿", "合理补偿", "及时补偿"],answer:0,explanation:"行政补偿的原则包括依法补偿、合理补偿、及时补偿等；不予补偿不属于。"},{id:"cs-3744",module:"changshi",prompt:"行政复议的范围不包括？",options:["内部人事奖惩决定", "行政处罚", "行政强制措施", "行政许可"],answer:0,explanation:"行政复议的范围包括行政处罚、行政强制措施、行政许可等外部行政行为；内部人事奖惩决定不属于行政复议范围。"},{id:"cs-3745",module:"changshi",prompt:"行政复议的程序不包括？",options:["刑事审判", "申请", "受理", "决定"],answer:0,explanation:"行政复议的程序包括申请、受理、决定等；刑事审判不属于行政复议程序。"},{id:"cs-3746",module:"changshi",prompt:"行政诉讼的范围不包括？",options:["内部人事奖惩决定", "行政处罚", "行政强制措施", "行政许可"],answer:0,explanation:"行政诉讼的范围包括行政处罚、行政强制措施、行政许可等外部行政行为；内部人事奖惩决定不属于行政诉讼范围。"},{id:"cs-3747",module:"changshi",prompt:"故意杀人罪的加重情节不包括？",options:["故意杀人未遂", "故意杀人情节恶劣", "故意杀人致人死亡", "故意杀人手段残忍"],answer:0,explanation:"故意杀人罪的加重情节包括情节恶劣、致人死亡、手段残忍等；故意杀人未遂不构成加重情节。"},{id:"cs-3748",module:"changshi",prompt:"交通肇事罪的加重情节不包括？",options:["轻微剐蹭", "致人重伤", "致人死亡", "使公私财产遭受重大损失"],answer:0,explanation:"交通肇事罪的加重情节包括致人重伤、致人死亡、使公私财产遭受重大损失等；轻微剐蹭不构成犯罪。"},{id:"cs-3749",module:"changshi",prompt:"危险驾驶罪的加重情节不包括？",options:["正常驾驶", "追逐竞驶情节恶劣", "醉酒驾驶", "严重超员、超速"],answer:0,explanation:"危险驾驶罪的加重情节包括追逐竞驶情节恶劣、醉酒驾驶、严重超员超速等；正常驾驶不构成犯罪。"},{id:"cs-3750",module:"changshi",prompt:"失火罪的加重情节不包括？",options:["轻微火灾", "致人重伤", "致人死亡", "使公私财产遭受重大损失"],answer:0,explanation:"失火罪的加重情节包括致人重伤、致人死亡、使公私财产遭受重大损失等；轻微火灾不构成犯罪。"},{id:"cs-3751",module:"changshi",prompt:"放火罪的加重情节不包括？",options:["放火未遂", "致人重伤", "致人死亡", "使公私财产遭受重大损失"],answer:0,explanation:"放火罪的加重情节包括致人重伤、致人死亡、使公私财产遭受重大损失等；放火未遂不构成加重情节。"},{id:"cs-3752",module:"changshi",prompt:"根据刑法规定，强奸罪的成立要求？",options:["违背妇女意志，使用暴力、胁迫或者其他手段强行与之发生性关系", "双方自愿", "正常交往", "正常恋爱"],answer:0,explanation:"强奸罪是指违背妇女意志，使用暴力、胁迫或者其他手段强行与妇女发生性关系的行为。"},{id:"cs-3753",module:"changshi",prompt:"根据刑法规定，抢劫罪的成立要求？",options:["以非法占有为目的，当场使用暴力、胁迫或者其他方法，强行劫取公私财物", "秘密窃取", "欺骗取得", "侵占代管财物"],answer:0,explanation:"抢劫罪是指以非法占有为目的，当场使用暴力、胁迫或者其他方法，强行劫取公私财物的行为。"},{id:"cs-3754",module:"changshi",prompt:"根据刑法规定，诈骗罪的成立要求？",options:["以非法占有为目的，用虚构事实或者隐瞒真相的方法，骗取数额较大的公私财物", "使用暴力", "秘密窃取", "当场劫取"],answer:0,explanation:"诈骗罪是指以非法占有为目的，用虚构事实或者隐瞒真相的方法，骗取数额较大的公私财物的行为。"},{id:"cs-3755",module:"changshi",prompt:"根据刑法规定，贪污罪的成立要求？",options:["国家工作人员利用职务上的便利，侵吞、窃取、骗取或者以其他手段非法占有公共财物", "一般公民", "公司员工", "军人"],answer:0,explanation:"贪污罪是指国家工作人员利用职务上的便利，侵吞、窃取、骗取或者以其他手段非法占有公共财物的行为。"},{id:"cs-3756",module:"changshi",prompt:"根据刑法规定，受贿罪的成立要求？",options:["国家工作人员利用职务上的便利，索取他人财物，或者非法收受他人财物，为他人谋取利益", "一般公民", "公司员工", "军人"],answer:0,explanation:"受贿罪是指国家工作人员利用职务上的便利，索取他人财物，或者非法收受他人财物，为他人谋取利益的行为。"},{id:"cs-3757",module:"changshi",prompt:"民事诉讼中，普通程序的适用范围是？",options:["除简易程序、特别程序、督促程序、公示催告程序以外的案件", "仅简易程序", "仅特别程序", "仅督促程序"],answer:0,explanation:"普通程序适用于除简易程序、特别程序、督促程序、公示催告程序以外的一审民事案件。"},{id:"cs-3758",module:"changshi",prompt:"民事诉讼中，简易程序的适用条件不包括？",options:["案件复杂", "事实清楚", "权利义务关系明确", "争议不大"],answer:0,explanation:"简易程序的适用条件是事实清楚、权利义务关系明确、争议不大；案件复杂不适用简易程序。"},{id:"cs-3759",module:"changshi",prompt:"民事诉讼中，特别程序的适用范围不包括？",options:["一般民事纠纷", "选民资格案件", "宣告失踪、宣告死亡案件", "认定公民无民事行为能力、限制民事行为能力案件"],answer:0,explanation:"特别程序适用于选民资格案件、宣告失踪、宣告死亡案件、认定公民无民事行为能力、限制民事行为能力案件等；一般民事纠纷不适用特别程序。"},{id:"cs-3760",module:"changshi",prompt:"民事诉讼中，督促程序的适用条件不包括？",options:["双方存在重大争议", "请求给付金钱或汇票、本票、支票等", "债权人与债务人没有其他债务纠纷", "支付令能够送达债务人"],answer:0,explanation:"督促程序的适用条件是请求给付金钱或汇票、本票、支票等，债权人与债务人没有其他债务纠纷，支付令能够送达债务人；双方存在重大争议的不适用。"});
(window.YC_CS_BANK=window.YC_CS_BANK||[]).push({id:"cs-3761",module:"changshi",prompt:"我国宪法规定，国家行政机关由谁产生、对它负责、受它监督？",options:["人民代表大会", "上级政府", "监察委员会", "人民法院"],answer:0,explanation:"国家行政机关由人民代表大会产生，对它负责，受它监督，体现人民代表大会制度的监督关系。"},{id:"cs-3762",module:"changshi",prompt:"我国宪法规定，人民依照法律规定，通过各种途径和形式，管理？",options:["国家事务、经济和文化事业、社会事务", "仅国家事务", "仅经济事务", "仅文化事务"],answer:0,explanation:"宪法规定，人民依照法律规定，通过各种途径和形式，管理国家事务，管理经济和文化事业，管理社会事务。"},{id:"cs-3763",module:"changshi",prompt:"我国宪法规定，中华人民共和国的国家机构实行？",options:["民主集中制的原则", "三权分立原则", "议行合一原则", "首长独裁原则"],answer:0,explanation:"宪法规定，中华人民共和国的国家机构实行民主集中制的原则。"},{id:"cs-3764",module:"changshi",prompt:"我国宪法规定，全国人民代表大会和地方各级人民代表大会都由？",options:["民主选举产生，对人民负责，受人民监督", "上级任命", "党委指定", "政协推荐"],answer:0,explanation:"宪法规定，全国人民代表大会和地方各级人民代表大会都由民主选举产生，对人民负责，受人民监督。"},{id:"cs-3765",module:"changshi",prompt:"我国宪法规定，国家行政机关、监察机关、审判机关、检察机关都由谁产生，对它负责，受它监督？",options:["人民代表大会", "上级机关", "党委", "政协"],answer:0,explanation:"宪法规定，国家行政机关、监察机关、审判机关、检察机关都由人民代表大会产生，对它负责，受它监督。"},{id:"cs-3766",module:"changshi",prompt:"我国宪法规定，中央和地方的国家机构职权的划分，遵循在中央统一领导下，充分发挥地方的？",options:["主动性、积极性的原则", "独立性的原则", "自治性的原则", "分散性的原则"],answer:0,explanation:"宪法规定，中央和地方的国家机构职权的划分，遵循在中央的统一领导下，充分发挥地方的主动性、积极性的原则。"},{id:"cs-3767",module:"changshi",prompt:"我国宪法规定，省、直辖市、县、市、市辖区、乡、民族乡、镇设立？",options:["人民代表大会和人民政府", "仅人民政府", "仅人民代表大会", "仅监察委员会"],answer:0,explanation:"宪法规定，省、直辖市、县、市、市辖区、乡、民族乡、镇设立人民代表大会和人民政府。"},{id:"cs-3768",module:"changshi",prompt:"我国宪法规定，地方各级人民政府实行？",options:["省长、市长、县长、区长、乡长、镇长负责制", "集体负责制", "合议制", "委员会制"],answer:0,explanation:"宪法规定，地方各级人民政府实行省长、市长、县长、区长、乡长、镇长负责制。"},{id:"cs-3769",module:"changshi",prompt:"我国宪法规定，居民委员会设在哪里？",options:["居民居住的地区", "政府机关", "企事业单位", "学校"],answer:0,explanation:"宪法规定，城市和农村按居民居住地区设立的居民委员会或者村民委员会是基层群众性自治组织。"},{id:"cs-3770",module:"changshi",prompt:"我国宪法规定，监察委员会依照法律规定独立行使？",options:["监察权", "审判权", "检察权", "立法权"],answer:0,explanation:"宪法规定，监察委员会依照法律规定独立行使监察权，不受行政机关、社会团体和个人的干涉。"},{id:"cs-3771",module:"changshi",prompt:"我国宪法规定，人民法院、人民检察院和公安机关办理刑事案件，应当分工负责，互相配合，互相？",options:["制约", "支持", "监督", "协助"],answer:0,explanation:"宪法规定，人民法院、人民检察院和公安机关办理刑事案件，应当分工负责，互相配合，互相制约，以保证准确有效地执行法律。"},{id:"cs-3772",module:"changshi",prompt:"行政法上的行政职权是指？",options:["行政主体依法享有的对一定领域或方面实施行政管理的权力", "民事权利", "刑事权力", "立法权力"],answer:0,explanation:"行政职权是行政主体依法享有的对一定领域或方面实施行政管理的权力，如行政处罚权、行政许可权等。"},{id:"cs-3773",module:"changshi",prompt:"行政法上的行政职责是指？",options:["行政主体依法必须履行的义务", "民事义务", "刑事义务", "道德义务"],answer:0,explanation:"行政职责是行政主体依法必须履行的义务，如依法行政、保护相对人合法权益等。"},{id:"cs-3774",module:"changshi",prompt:"行政法上的行政权限是指？",options:["行政职权的范围和界限", "行政职权的来源", "行政职权的行使方式", "行政职权的监督"],answer:0,explanation:"行政权限是行政职权的范围和界限，行政主体不得超越权限行使职权。"},{id:"cs-3775",module:"changshi",prompt:"行政法上的行政优益权是指？",options:["行政主体在行使行政职权时享有的优先权和受益权", "民事权利", "刑事权力", "立法权力"],answer:0,explanation:"行政优益权是行政主体在行使行政职权时享有的优先权和受益权，如行政优先权、行政受益权。"},{id:"cs-3776",module:"changshi",prompt:"行政法上的行政优先权是指？",options:["行政主体在行使行政职权时享有的优先条件", "民事权利", "刑事权力", "立法权力"],answer:0,explanation:"行政优先权是行政主体在行使行政职权时享有的优先条件，如先行处置权、获得社会协助权等。"},{id:"cs-3777",module:"changshi",prompt:"行政法上的行政受益权是指？",options:["行政主体为行使行政职权而享有的由国家提供物质保障的权力", "民事权利", "刑事权力", "立法权力"],answer:0,explanation:"行政受益权是行政主体为行使行政职权而享有的由国家提供物质保障的权力，如财政经费、办公条件等。"},{id:"cs-3778",module:"changshi",prompt:"行政法上的行政委托是指？",options:["行政主体将行政职权委托给其他行政机关或组织行使", "民事委托", "刑事委托", "立法委托"],answer:0,explanation:"行政委托是行政主体将行政职权委托给其他行政机关或组织行使，受委托的组织以委托机关的名义行使职权。"},{id:"cs-3779",module:"changshi",prompt:"行政法上的行政授权是指？",options:["法律法规将行政职权授予其他组织行使", "民事授权", "刑事授权", "立法授权"],answer:0,explanation:"行政授权是法律法规将行政职权授予其他组织行使，被授权的组织以自己的名义行使职权并承担责任。"},{id:"cs-3780",module:"changshi",prompt:"行政法上的行政协助是指？",options:["行政机关在行使职权时请求其他行政机关协助", "民事协助", "刑事协助", "立法协助"],answer:0,explanation:"行政协助是行政机关在行使职权时请求其他行政机关协助的制度。"},{id:"cs-3781",module:"changshi",prompt:"行政法上的行政规划是指？",options:["行政机关为实现特定目标而制定的发展规划和计划", "民事规划", "刑事规划", "立法规划"],answer:0,explanation:"行政规划是行政机关为实现特定目标而制定的发展规划和计划，如国民经济和社会发展规划等。"},{id:"cs-3782",module:"changshi",prompt:"行政法上的行政指导是指？",options:["行政机关通过建议、劝告等方式引导相对人作出或不作出某种行为", "行政命令", "行政处罚", "行政强制"],answer:0,explanation:"行政指导是行政机关通过建议、劝告、提醒等方式引导相对人作出或不作出某种行为的非强制性行为。"},{id:"cs-3783",module:"changshi",prompt:"行政法上的行政奖励是指？",options:["行政机关对作出贡献的单位或个人给予物质或精神奖励", "行政处罚", "行政强制", "行政处分"],answer:0,explanation:"行政奖励是行政机关对作出贡献的单位或个人给予物质或精神奖励的行为。"},{id:"cs-3784",module:"changshi",prompt:"行政法上的行政给付是指？",options:["行政机关对特定对象给予物质帮助的行为", "行政处罚", "行政强制", "行政处分"],answer:0,explanation:"行政给付是行政机关对特定对象（如贫困者、灾民等）给予物质帮助的行为，如发放救济金、抚恤金等。"},{id:"cs-3785",module:"changshi",prompt:"行政法上的行政确认是指？",options:["行政机关对特定法律事实或法律关系予以认定和确认的行为", "行政处罚", "行政强制", "行政处分"],answer:0,explanation:"行政确认是行政机关对特定法律事实或法律关系予以认定和确认的行为，如婚姻登记、学历认证等。"},{id:"cs-3786",module:"changshi",prompt:"行政法上的行政裁决是指？",options:["行政机关对特定民事纠纷进行裁决的行为", "行政判决", "行政调解", "行政处罚"],answer:0,explanation:"行政裁决是行政机关对特定民事纠纷进行裁决的行为，如对土地、水事等纠纷的裁决。"},{id:"cs-3787",module:"changshi",prompt:"死刑的适用条件不包括？",options:["犯罪时不满18周岁的人", "罪行极其严重", "不是审判时怀孕的妇女", "不是审判时已满75周岁的人（以特别残忍手段致人死亡的除外）"],answer:0,explanation:"死刑只适用于罪行极其严重的犯罪分子；犯罪时不满18周岁的人和审判时怀孕的妇女不适用死刑，审判时已满75周岁的人不适用死刑（以特别残忍手段致人死亡的除外）。"},{id:"cs-3788",module:"changshi",prompt:"根据刑法规定，死缓的适用条件是？",options:["应当判处死刑的犯罪分子，如果不是必须立即执行的，可以判处死刑同时宣告缓期2年执行", "所有死刑案件", "仅轻微案件", "仅经济犯罪"],answer:0,explanation:"死缓适用于应当判处死刑的犯罪分子，如果不是必须立即执行的，可以判处死刑同时宣告缓期2年执行。"},{id:"cs-3789",module:"changshi",prompt:"根据刑法规定，死缓的考验期为？",options:["2年", "1年", "3年", "5年"],answer:0,explanation:"死缓的考验期为2年，从判决确定之日起计算。"},{id:"cs-3790",module:"changshi",prompt:"死缓期间没有故意犯罪的，2年期满后减为？",options:["无期徒刑", "有期徒刑", "拘役", "管制"],answer:0,explanation:"死缓期间没有故意犯罪的，2年期满后减为无期徒刑；有重大立功表现的，减为25年有期徒刑。"},{id:"cs-3791",module:"changshi",prompt:"剥夺政治权利的期限一般为？",options:["1年以上5年以下", "6个月以下", "10年以上", "终身"],answer:0,explanation:"剥夺政治权利的期限一般为1年以上5年以下；判处死刑、无期徒刑的，剥夺政治权利终身。"},{id:"cs-3792",module:"changshi",prompt:"剥夺政治权利的效力当然施用于？",options:["主刑执行期间", "主刑执行前", "主刑执行后", "任何时候"],answer:0,explanation:"剥夺政治权利的效力当然施用于主刑执行期间，即判处有期徒刑、拘役附加剥夺政治权利的，剥夺政治权利的效力及于主刑执行期间。"},{id:"cs-3793",module:"changshi",prompt:"根据刑法规定，没收财产的范围是？",options:["犯罪分子个人所有财产的一部分或全部", "犯罪分子家属所有财产", "犯罪分子单位财产", "国家财产"],answer:0,explanation:"没收财产是没收犯罪分子个人所有财产的一部分或者全部；不得没收属于犯罪分子家属所有或者应有的财产。"},{id:"cs-3794",module:"changshi",prompt:"根据刑法规定，驱逐出境适用于？",options:["犯罪的外国人", "犯罪的中国人", "所有犯罪人", "无国籍人"],answer:0,explanation:"驱逐出境适用于犯罪的外国人，可以独立适用或者附加适用。"},{id:"cs-3795",module:"changshi",prompt:"非刑罚处理方法不包括？",options:["有期徒刑", "赔偿经济损失", "训诫", "责令具结悔过"],answer:0,explanation:"非刑罚处理方法包括赔偿经济损失、训诫、责令具结悔过、责令赔礼道歉等；有期徒刑是主刑。"},{id:"cs-3796",module:"changshi",prompt:"职业禁止的适用条件是？",options:["因利用职业便利实施犯罪，或者实施违背职业要求的特定义务的犯罪被判处刑罚的", "所有犯罪", "仅轻微犯罪", "仅过失犯罪"],answer:0,explanation:"因利用职业便利实施犯罪，或者实施违背职业要求的特定义务的犯罪被判处刑罚的，人民法院可以根据犯罪情况和预防再犯罪的需要，禁止其自刑罚执行完毕之日或者假释之日起从事相关职业。"},{id:"cs-3797",module:"changshi",prompt:"根据刑法规定，职业禁止的期限为？",options:["3年至5年", "1年至2年", "5年至10年", "终身"],answer:0,explanation:"职业禁止的期限为3年至5年。"},{id:"cs-3798",module:"changshi",prompt:"根据社区矫正法，社区矫正适用于？",options:["被判处管制、宣告缓刑、假释、暂予监外执行的犯罪分子", "所有犯罪分子", "仅重刑犯", "仅轻刑犯"],answer:0,explanation:"社区矫正适用于被判处管制、宣告缓刑、假释、暂予监外执行的犯罪分子。"},{id:"cs-3799",module:"changshi",prompt:"民事法律行为的有效要件不包括？",options:["必须经过公证", "行为人具有相应的民事行为能力", "意思表示真实", "不违反法律、行政法规的强制性规定，不违背公序良俗"],answer:0,explanation:"民事法律行为的有效要件包括行为人具有相应的民事行为能力、意思表示真实、不违反法律行政法规的强制性规定不违背公序良俗；公证不是有效要件。"},{id:"cs-3800",module:"changshi",prompt:"民事法律行为的附条件是指？",options:["当事人约定以将来不确定事实的发生或不发生作为效力条件", "以过去事实为条件", "以法定条件为条件", "以对方意思为条件"],answer:0,explanation:"民事法律行为可以附条件，附生效条件的，自条件成就时生效；附解除条件的，自条件成就时失效。"},{id:"cs-3801",module:"changshi",prompt:"民事法律行为的附期限是指？",options:["当事人约定以将来确定事实的到来作为效力条件", "以过去事实为条件", "以法定条件为条件", "以对方意思为条件"],answer:0,explanation:"民事法律行为可以附期限，附生效期限的，自期限届至时生效；附终止期限的，自期限届满时失效。"},{id:"cs-3802",module:"changshi",prompt:"根据民法典总则编，代理的种类包括？",options:["委托代理和法定代理", "仅委托代理", "仅法定代理", "仅指定代理"],answer:0,explanation:"代理包括委托代理和法定代理；民法典取消了指定代理的规定。"},{id:"cs-3803",module:"changshi",prompt:"委托代理的授权方式可以是？",options:["书面、口头或其他方式（法律规定书面形式的除外）", "仅书面", "仅口头", "仅公证"],answer:0,explanation:"委托代理授权可以采用书面形式、口头形式或者其他形式，法律规定采用书面形式的除外。"},{id:"cs-3804",module:"changshi",prompt:"代理权终止的情形不包括？",options:["代理人继续行使代理权", "代理期限届满或者代理事务完成", "被代理人取消委托或者代理人辞去委托", "代理人丧失民事行为能力"],answer:0,explanation:"代理权终止的情形包括代理期限届满或代理事务完成、被代理人取消委托或代理人辞去委托、代理人丧失民事行为能力等；代理人继续行使代理权不属于。"},{id:"cs-3805",module:"changshi",prompt:"无权代理的法律后果是？",options:["未经被代理人追认的，对被代理人不发生效力", "一律有效", "一律无效", "效力待定"],answer:0,explanation:"行为人没有代理权、超越代理权或者代理权终止后，仍然实施代理行为，未经被代理人追认的，对被代理人不发生效力。"},{id:"cs-3806",module:"changshi",prompt:"表见代理的构成要件不包括？",options:["代理人实际有代理权", "行为人没有代理权、超越代理权或者代理权终止", "相对人有理由相信行为人有代理权", "相对人善意且无过失"],answer:0,explanation:"表见代理的构成要件是行为人没有代理权、超越代理权或者代理权终止，相对人有理由相信行为人有代理权，相对人善意且无过失；代理人实际有代理权不属于。"},{id:"cs-3807",module:"changshi",prompt:"诉讼时效的起算点是？",options:["权利人知道或者应当知道权利受到损害以及义务人之日起", "权利产生之日", "权利行使之日", "义务履行之日"],answer:0,explanation:"诉讼时效期间自权利人知道或者应当知道权利受到损害以及义务人之日起计算。"},{id:"cs-3808",module:"changshi",prompt:"诉讼时效中止的事由是？",options:["在诉讼时效期间的最后6个月内，因不可抗力等障碍不能行使请求权", "权利人主张权利", "义务人同意履行", "提起诉讼"],answer:0,explanation:"在诉讼时效期间的最后6个月内，因不可抗力、无民事行为能力人没有法定代理人等障碍不能行使请求权的，诉讼时效中止。"},{id:"cs-3809",module:"changshi",prompt:"诉讼时效中断的事由不包括？",options:["时效期间届满", "权利人向义务人提出履行请求", "义务人同意履行义务", "权利人提起诉讼或申请仲裁"],answer:0,explanation:"诉讼时效中断的事由包括权利人向义务人提出履行请求、义务人同意履行义务、权利人提起诉讼或申请仲裁等；时效期间届满是时效完成的情形。"},{id:"cs-3810",module:"changshi",prompt:"根据民法典物权编，物权公示原则是指？",options:["物权变动应当以公开方式让他人知晓", "物权变动应当保密", "物权变动无需公示", "物权变动由当事人决定"],answer:0,explanation:"物权公示原则是指物权变动应当以公开方式让他人知晓，动产以交付为公示方法，不动产以登记为公示方法。"},{id:"cs-3811",module:"changshi",prompt:"根据民法典物权编，物权法定原则是指？",options:["物权的种类和内容由法律规定", "物权的种类和内容由当事人约定", "物权的种类和内容由法院认定", "物权的种类和内容由习惯确定"],answer:0,explanation:"物权法定原则是指物权的种类和内容由法律规定，当事人不得自行创设物权种类或改变物权内容。"},{id:"cs-3812",module:"changshi",prompt:"善意取得的构成要件不包括？",options:["转让人有处分权", "受让人受让时是善意的", "以合理的价格转让", "依法应当登记的已经登记，不需要登记的已经交付"],answer:0,explanation:"善意取得的构成要件是受让人受让时是善意的、以合理的价格转让、依法应当登记的已经登记不需要登记的已经交付；转让人有处分权不属于。"},{id:"cs-3813",module:"changshi",prompt:"拾得遗失物应当返还权利人，权利人领取遗失物时应当支付？",options:["保管遗失物等支出的必要费用", "报酬", "奖励", "补偿金"],answer:0,explanation:"权利人领取遗失物时，应当向拾得人或者有关部门支付保管遗失物等支出的必要费用。"},{id:"cs-3814",module:"changshi",prompt:"劳动合同的解除方式不包括？",options:["自动解除", "协商解除", "法定解除", "约定解除"],answer:0,explanation:"劳动合同的解除方式包括协商解除、法定解除和约定解除；不存在自动解除。"},{id:"cs-3815",module:"changshi",prompt:"用人单位可以随时解除劳动合同的情形不包括？",options:["劳动者怀孕", "劳动者在试用期间被证明不符合录用条件", "劳动者严重违反用人单位的规章制度", "劳动者被依法追究刑事责任"],answer:0,explanation:"用人单位可以随时解除劳动合同的情形包括劳动者在试用期间被证明不符合录用条件、严重违反规章制度、被依法追究刑事责任等；劳动者怀孕属于不得解除的情形。"},{id:"cs-3816",module:"changshi",prompt:"经济补偿的计算基数是？",options:["劳动者在劳动合同解除或者终止前12个月的平均工资", "劳动者最低工资", "当地社会平均工资", "用人单位利润"],answer:0,explanation:"经济补偿按劳动者在劳动合同解除或者终止前12个月的平均工资计算。"},{id:"cs-3817",module:"changshi",prompt:"经济补偿的计算上限是？",options:["劳动者月工资高于当地上年度职工月平均工资3倍的，按3倍支付，年限不超过12年", "无上限", "5倍", "10倍"],answer:0,explanation:"劳动者月工资高于用人单位所在地直辖市或设区的市级人民政府公布的本地区上年度职工月平均工资3倍的，按职工月平均工资3倍的数额支付，年限最高不超过12年。"},{id:"cs-3818",module:"changshi",prompt:"劳动争议的仲裁前置是指？",options:["劳动争议必须先经过仲裁，对仲裁裁决不服的才能起诉", "劳动争议必须先经过调解", "劳动争议必须先经过协商", "劳动争议必须先经过行政处理"],answer:0,explanation:"劳动争议仲裁是诉讼的前置程序，发生劳动争议，当事人必须先申请仲裁，对仲裁裁决不服的才能向人民法院起诉。"},{id:"cs-3819",module:"changshi",prompt:"劳动争议仲裁委员会的管辖原则是？",options:["劳动合同履行地或用人单位所在地", "劳动者户籍地", "用人单位注册地", "任意地"],answer:0,explanation:"劳动争议由劳动合同履行地或者用人单位所在地的劳动争议仲裁委员会管辖。"},{id:"cs-3820",module:"changshi",prompt:"劳动争议仲裁委员会应当在收到仲裁申请之日起多久内决定是否受理？",options:["5日内", "3日内", "10日内", "15日内"],answer:0,explanation:"劳动争议仲裁委员会收到仲裁申请之日起5日内，认为符合受理条件的，应当受理。"},{id:"cs-3821",module:"changshi",prompt:"劳动争议仲裁裁决的生效时间是？",options:["当事人收到裁决书之日起15日内不起诉的，裁决书发生法律效力", "裁决作出时", "当事人签收时", "法院判决时"],answer:0,explanation:"当事人对仲裁裁决不服的，可以自收到裁决书之日起15日内向人民法院提起诉讼；期满不起诉的，裁决书发生法律效力。"},{id:"cs-3822",module:"changshi",prompt:"劳动争议仲裁裁决的执行由谁管辖？",options:["人民法院", "劳动争议仲裁委员会", "劳动行政部门", "工会"],answer:0,explanation:"对发生法律效力的仲裁裁决书，一方当事人不履行的，另一方当事人可以依法向人民法院申请执行。"},{id:"cs-3823",module:"changshi",prompt:"反垄断法规定，垄断协议的认定标准不包括？",options:["是否损害经营者利益", "是否排除、限制竞争", "是否损害消费者利益", "是否违反法律规定"],answer:0,explanation:"垄断协议的认定标准包括是否排除、限制竞争，是否损害消费者利益，是否违反法律规定等；是否损害经营者利益不属于。"},{id:"cs-3824",module:"changshi",prompt:"反垄断法规定，市场支配地位的认定标准不包括？",options:["经营者的个人品德", "经营者的市场份额", "经营者控制市场的能力", "其他经营者的依赖程度"],answer:0,explanation:"市场支配地位的认定标准包括经营者的市场份额、控制市场的能力、其他经营者的依赖程度等；经营者的个人品德不属于。"},{id:"cs-3825",module:"changshi",prompt:"反不正当竞争法规定，商业混淆的认定标准不包括？",options:["是否使用与他人相同的商标", "是否擅自使用与他人有一定影响的商品名称、包装、装潢等相同或近似的标识", "是否引人误认", "是否造成混淆"],answer:0,explanation:"商业混淆的认定标准包括是否擅自使用与他人有一定影响的商品名称、包装、装潢等相同或近似的标识，是否引人误认，是否造成混淆等；是否使用与他人相同的商标不属于。"},{id:"cs-3826",module:"changshi",prompt:"消费者权益保护法规定，经营者的义务不包括？",options:["无限期无理由退货", "提供真实、全面的商品信息", "出具购货凭证或服务单据", "保证商品或服务质量"],answer:0,explanation:"经营者的义务包括提供真实全面的信息、出具凭证、保证质量、7日无理由退货（网络购物）等；无限期无理由退货不是法定义务。"},{id:"cs-3827",module:"changshi",prompt:"产品质量法规定，产品质量的责任主体不包括？",options:["消费者", "生产者", "销售者", "运输者、仓储者等第三人"],answer:0,explanation:"产品质量的责任主体包括生产者、销售者、运输者、仓储者等第三人；消费者不是责任主体。"},{id:"cs-3828",module:"changshi",prompt:"食品安全法规定，食品安全的责任主体不包括？",options:["消费者", "食品生产经营者", "监管部门", "检验机构"],answer:0,explanation:"食品安全的责任主体包括食品生产经营者、监管部门、检验机构等；消费者不是责任主体。"},{id:"cs-3829",module:"changshi",prompt:"广告法规定，广告的责任主体不包括？",options:["消费者", "广告主", "广告经营者", "广告发布者"],answer:0,explanation:"广告的责任主体包括广告主、广告经营者、广告发布者、广告代言人等；消费者不是责任主体。"},{id:"cs-3830",module:"changshi",prompt:"电子商务法规定，电子商务的责任主体不包括？",options:["消费者", "电子商务经营者", "电子商务平台经营者", "平台内经营者"],answer:0,explanation:"电子商务的责任主体包括电子商务经营者、电子商务平台经营者、平台内经营者等；消费者不是责任主体。"},{id:"cs-3831",module:"changshi",prompt:"税收征收管理法规定，税收的责任主体不包括？",options:["纳税人", "扣缴义务人", "税务机关", "消费者"],answer:0,explanation:"税收的责任主体包括纳税人、扣缴义务人、税务机关等；消费者不是责任主体。"},{id:"cs-3832",module:"changshi",prompt:"商业银行法规定，商业银行的责任主体不包括？",options:["存款人", "商业银行", "商业银行的工作人员", "监管部门"],answer:0,explanation:"商业银行的责任主体包括商业银行、商业银行的工作人员、监管部门等；存款人不是责任主体。"},{id:"cs-3833",module:"changshi",prompt:"法律关系的特征不包括？",options:["以情感为基础", "以法律规范为前提", "以权利义务为内容", "以国家强制力为保障"],answer:0,explanation:"法律关系的特征包括以法律规范为前提、以权利义务为内容、以国家强制力为保障等；以情感为基础不是法律关系的特征。"},{id:"cs-3834",module:"changshi",prompt:"法律关系的主体资格是指？",options:["能够依法享有权利、承担义务的资格", "能够行使权力的资格", "能够履行职责的资格", "能够获得利益的资格"],answer:0,explanation:"法律关系的主体资格是能够依法享有权利、承担义务的资格，包括权利能力和行为能力。"},{id:"cs-3835",module:"changshi",prompt:"法律关系的发生、变更和消灭的条件是？",options:["法律规范和法律事实", "道德规范", "政策", "习惯"],answer:0,explanation:"法律关系的发生、变更和消灭的条件是法律规范和法律事实；法律规范是前提，法律事实是直接原因。"},{id:"cs-3836",module:"changshi",prompt:"法律事实的分类不包括？",options:["道德事实", "法律事件", "法律行为", "事实构成"],answer:0,explanation:"法律事实的分类包括法律事件、法律行为和事实构成等；道德事实不属于法律事实。"},{id:"cs-3837",module:"changshi",prompt:"法律行为的分类不包括？",options:["道德行为", "合法行为", "违法行为", "善意行为与恶意行为"],answer:0,explanation:"法律行为的分类包括合法行为、违法行为、善意行为与恶意行为等；道德行为不属于法律行为。"},{id:"cs-3838",module:"changshi",prompt:"法律实施的保障不包括？",options:["道德保障", "法律保障", "政治保障", "经济保障"],answer:0,explanation:"法律实施的保障包括法律保障、政治保障、经济保障、社会保障等；道德保障不属于法律实施的保障。"},{id:"cs-3839",module:"changshi",prompt:"法律秩序的形成条件不包括？",options:["道德秩序", "法律规范", "法律实施", "法律意识"],answer:0,explanation:"法律秩序的形成条件包括法律规范、法律实施、法律意识等；道德秩序不属于法律秩序的形成条件。"});
(window.YC_CS_BANK=window.YC_CS_BANK||[]).push({id:"cs-3840",module:"changshi",prompt:"我国宪法规定，国家尊重和保障人权是在哪一年写入宪法的？",options:["2004年", "1999年", "2018年", "1982年"],answer:0,explanation:"2004年宪法修正案将国家尊重和保障人权写入宪法。"},{id:"cs-3841",module:"changshi",prompt:"我国宪法规定，公民的私有财产权的宪法依据是？",options:["公民的合法的私有财产不受侵犯", "私有财产神圣不可侵犯", "私有财产不受限制", "私有财产可以随意处置"],answer:0,explanation:"宪法规定，公民的合法的私有财产不受侵犯，国家依照法律规定保护公民的私有财产权和继承权。"},{id:"cs-3842",module:"changshi",prompt:"我国宪法规定，国家推行计划生育，使人口增长同经济和社会发展计划相适应，这是在？",options:["1982年宪法中规定的", "1975年宪法中规定的", "1978年宪法中规定的", "1954年宪法中规定的"],answer:0,explanation:"1982年宪法规定，国家推行计划生育，使人口的增长同经济和社会发展计划相适应。"},{id:"cs-3843",module:"changshi",prompt:"我国宪法规定，国家发展社会主义市场经济，禁止任何组织或者个人扰乱？",options:["社会经济秩序", "政治秩序", "文化秩序", "军事秩序"],answer:0,explanation:"宪法规定，国家实行社会主义市场经济，国家加强经济立法，完善宏观调控，国家依法禁止任何组织或者个人扰乱社会经济秩序。"},{id:"cs-3844",module:"changshi",prompt:"我国宪法规定，国有企业在法律规定的范围内有权？",options:["自主经营", "随意经营", "垄断经营", "无序经营"],answer:0,explanation:"宪法规定，国有企业在法律规定的范围内有权自主经营。"},{id:"cs-3845",module:"changshi",prompt:"我国宪法规定，集体经济组织在遵守有关法律的前提下，有独立进行？",options:["经济活动的自主权", "政治活动的自主权", "文化活动的自主权", "军事活动的自主权"],answer:0,explanation:"宪法规定，集体经济组织在遵守有关法律的前提下，有独立进行经济活动的自主权。"},{id:"cs-3846",module:"changshi",prompt:"我国宪法规定，国家维护社会秩序，制裁危害社会治安、破坏社会主义经济和其他犯罪的活动，惩办和改造？",options:["犯罪分子", "违法人员", "违纪人员", "失信人员"],answer:0,explanation:"宪法规定，国家维护社会秩序，制裁危害社会治安、破坏社会主义经济和其他犯罪的活动，惩办和改造犯罪分子。"},{id:"cs-3847",module:"changshi",prompt:"我国宪法规定，国家培养为社会主义服务的各种专业人才，扩大？",options:["知识分子队伍", "工人队伍", "农民队伍", "军人队伍"],answer:0,explanation:"宪法规定，国家培养为社会主义服务的各种专业人才，扩大知识分子队伍，创造条件，充分发挥他们在社会主义现代化建设中的作用。"},{id:"cs-3848",module:"changshi",prompt:"我国宪法规定，国家推广全国通用的？",options:["普通话", "方言", "外语", "少数民族语言"],answer:0,explanation:"宪法规定，国家推广全国通用的普通话。"},{id:"cs-3849",module:"changshi",prompt:"我国宪法规定，各民族都有使用和发展自己的语言文字的自由，都有保持或者改革自己的？",options:["风俗习惯的自由", "宗教信仰的自由", "政治信仰的自由", "生活方式的自由"],answer:0,explanation:"宪法规定，各民族都有使用和发展自己的语言文字的自由，都有保持或者改革自己的风俗习惯的自由。"},{id:"cs-3850",module:"changshi",prompt:"我国宪法规定，中华人民共和国各民族一律平等，国家保障各少数民族的合法的权利和利益，维护和发展各民族的？",options:["平等、团结、互助、和谐关系", "等级关系", "对立关系", "分离关系"],answer:0,explanation:"宪法规定，中华人民共和国各民族一律平等，国家保障各少数民族的合法的权利和利益，维护和发展各民族的平等、团结、互助、和谐关系。"},{id:"cs-3851",module:"changshi",prompt:"我国宪法规定，国家保障各少数民族的合法的权利和利益，禁止对任何民族的？",options:["歧视和压迫", "优待", "扶持", "帮助"],answer:0,explanation:"宪法规定，国家保障各少数民族的合法的权利和利益，维护和发展各民族的平等、团结、互助、和谐关系，禁止对任何民族的歧视和压迫，禁止破坏民族团结和制造民族分裂的行为。"},{id:"cs-3852",module:"changshi",prompt:"行政法上的行政行为是指？",options:["行政主体依法行使行政职权，产生法律效果的行为", "民事行为", "刑事行为", "立法行为"],answer:0,explanation:"行政行为是行政主体依法行使行政职权，产生法律效果的行为。"},{id:"cs-3853",module:"changshi",prompt:"行政法上的抽象行政行为是指？",options:["行政主体制定行政法规、规章和发布具有普遍约束力的决定、命令的行为", "行政处罚", "行政许可", "行政强制"],answer:0,explanation:"抽象行政行为是行政主体制定行政法规、规章和发布具有普遍约束力的决定、命令的行为。"},{id:"cs-3854",module:"changshi",prompt:"行政法上的具体行政行为是指？",options:["行政主体针对特定对象就特定事项作出的产生法律效果的行为", "制定行政法规", "制定规章", "发布决定"],answer:0,explanation:"具体行政行为是行政主体针对特定对象就特定事项作出的产生法律效果的行为，如行政处罚、行政许可等。"},{id:"cs-3855",module:"changshi",prompt:"行政法上的羁束行政行为是指？",options:["法律对行为的范围、条件、方式等作了明确规定的行政行为", "法律未作明确规定的行政行为", "需要协商的行政行为", "需要批准的行政行为"],answer:0,explanation:"羁束行政行为是法律对行为的范围、条件、方式等作了明确规定的行政行为，行政主体没有选择余地。"},{id:"cs-3856",module:"changshi",prompt:"行政法上的自由裁量行政行为是指？",options:["法律仅规定行为的范围、条件、幅度等，行政主体可以在法定范围内选择", "法律未作规定的行政行为", "需要协商的行政行为", "需要批准的行政行为"],answer:0,explanation:"自由裁量行政行为是法律仅规定行为的范围、条件、幅度等，行政主体可以在法定范围内选择的行为。"},{id:"cs-3857",module:"changshi",prompt:"行政法上的依职权行政行为是指？",options:["行政主体不需要相对人申请，主动作出的行政行为", "需要相对人申请的行政行为", "需要批准的行政行为", "需要协商的行政行为"],answer:0,explanation:"依职权行政行为是行政主体不需要相对人申请，主动作出的行政行为，如行政处罚。"},{id:"cs-3858",module:"changshi",prompt:"行政法上的依申请行政行为是指？",options:["行政主体需要相对人申请才能作出的行政行为", "行政主体主动作出的行政行为", "需要批准的行政行为", "需要协商的行政行为"],answer:0,explanation:"依申请行政行为是行政主体需要相对人申请才能作出的行政行为，如行政许可。"},{id:"cs-3859",module:"changshi",prompt:"行政法上的行政行为的生效要件不包括？",options:["必须经过公证", "行政主体合法", "内容合法", "程序合法"],answer:0,explanation:"行政行为的生效要件包括行政主体合法、内容合法、程序合法等；公证不是生效要件。"},{id:"cs-3860",module:"changshi",prompt:"行政法上的行政行为的失效情形不包括？",options:["相对人同意", "行政行为被撤销", "行政行为被废止", "行政行为被变更"],answer:0,explanation:"行政行为的失效情形包括被撤销、被废止、被变更等；相对人同意不是失效情形。"},{id:"cs-3861",module:"changshi",prompt:"行政法上的行政行为的追溯力是指？",options:["行政行为对作出前的事项是否有效力", "行政行为对作出后的事项是否有效力", "行政行为对第三人的效力", "行政行为对国家的效力"],answer:0,explanation:"行政行为的追溯力是行政行为对作出前的事项是否有效力；一般行政行为不具有追溯力。"},{id:"cs-3862",module:"changshi",prompt:"行政法上的行政行为的补正的法律后果是？",options:["程序瑕疵不影响行为效力的，可以补正", "一律无效", "一律撤销", "一律变更"],answer:0,explanation:"行政行为的程序瑕疵不影响行为效力的，可以补正；补正后行政行为继续有效。"},{id:"cs-3863",module:"changshi",prompt:"行政法上的行政行为的变更的法律后果是？",options:["行政行为部分内容改变，效力部分或全部改变", "自始无效", "继续有效", "部分无效"],answer:0,explanation:"行政行为被变更的，行政行为部分内容改变，效力部分或全部改变。"},{id:"cs-3864",module:"changshi",prompt:"行政法上的行政行为的撤销的法律后果是？",options:["该行政行为自始失去法律效力", "仅向后失效", "继续有效", "部分有效"],answer:0,explanation:"行政行为被撤销的，该行政行为自始失去法律效力，但撤销对公共利益有重大影响的除外。"},{id:"cs-3865",module:"changshi",prompt:"行政法上的行政行为的废止的法律后果是？",options:["该行政行为自废止之日起失去法律效力", "自始无效", "继续有效", "部分有效"],answer:0,explanation:"行政行为被废止的，该行政行为自废止之日起失去法律效力，废止前的效力不受影响。"},{id:"cs-3866",module:"changshi",prompt:"行政法上的行政行为的无效的情形不包括？",options:["程序轻微违法", "实施主体不具有行政主体资格", "没有依据", "内容重大且明显违法"],answer:0,explanation:"行政行为无效的情形包括实施主体不具有行政主体资格、没有依据、内容重大且明显违法等；程序轻微违法属于确认违法的情形。"},{id:"cs-3867",module:"changshi",prompt:"我国刑法规定的刑罚目的是？",options:["预防犯罪", "惩罚犯罪", "报复犯罪", "消灭犯罪"],answer:0,explanation:"我国刑罚的目的是预防犯罪，包括特殊预防和一般预防。"},{id:"cs-3868",module:"changshi",prompt:"我国刑法规定的犯罪构成要件不包括？",options:["犯罪动机", "犯罪客体", "犯罪客观方面", "犯罪主体"],answer:0,explanation:"我国刑法规定的犯罪构成要件包括犯罪客体、犯罪客观方面、犯罪主体和犯罪主观方面；犯罪动机不是构成要件。"},{id:"cs-3869",module:"changshi",prompt:"犯罪故意的种类不包括？",options:["犯罪动机", "直接故意", "间接故意", "明知"],answer:0,explanation:"犯罪故意的种类包括直接故意和间接故意；犯罪动机不是犯罪故意。"},{id:"cs-3870",module:"changshi",prompt:"犯罪过失的种类不包括？",options:["犯罪动机", "疏忽大意的过失", "过于自信的过失", "轻信能够避免"],answer:0,explanation:"犯罪过失的种类包括疏忽大意的过失和过于自信的过失；犯罪动机不是犯罪过失。"},{id:"cs-3871",module:"changshi",prompt:"危害行为的种类不包括？",options:["犯罪动机", "作为", "不作为", "持有"],answer:0,explanation:"危害行为的种类包括作为、不作为和持有；犯罪动机不是危害行为。"},{id:"cs-3872",module:"changshi",prompt:"危害结果的种类不包括？",options:["犯罪动机", "实害结果", "危险结果", "物质性结果与非物质性结果"],answer:0,explanation:"危害结果的种类包括实害结果、危险结果、物质性结果与非物质性结果等；犯罪动机不是危害结果。"},{id:"cs-3873",module:"changshi",prompt:"因果关系的种类不包括？",options:["犯罪动机", "必然因果关系", "偶然因果关系", "介入因素"],answer:0,explanation:"因果关系的种类包括必然因果关系、偶然因果关系、介入因素等；犯罪动机不是因果关系。"},{id:"cs-3874",module:"changshi",prompt:"民事法律行为的分类不包括？",options:["道德行为", "单方民事法律行为", "双方民事法律行为", "多方民事法律行为"],answer:0,explanation:"民事法律行为的分类包括单方、双方、多方民事法律行为等；道德行为不属于民事法律行为。"},{id:"cs-3875",module:"changshi",prompt:"单方民事法律行为是指？",options:["仅一方意思表示即可成立的民事法律行为", "需双方意思表示", "需多方意思表示", "需公证"],answer:0,explanation:"单方民事法律行为是仅一方意思表示即可成立的民事法律行为，如撤销、解除、抛弃等。"},{id:"cs-3876",module:"changshi",prompt:"双方民事法律行为是指？",options:["需双方意思表示一致才能成立的民事法律行为", "仅一方意思表示", "需多方意思表示", "需公证"],answer:0,explanation:"双方民事法律行为是需双方意思表示一致才能成立的民事法律行为，如合同。"},{id:"cs-3877",module:"changshi",prompt:"多方民事法律行为是指？",options:["需多方意思表示一致才能成立的民事法律行为", "仅一方意思表示", "需双方意思表示", "需公证"],answer:0,explanation:"多方民事法律行为是需多方意思表示一致才能成立的民事法律行为，如合伙协议、公司章程等。"},{id:"cs-3878",module:"changshi",prompt:"有偿民事法律行为是指？",options:["一方获得利益需支付对价的民事法律行为", "无需支付对价", "仅一方获益", "仅一方支付"],answer:0,explanation:"有偿民事法律行为是一方获得利益需支付对价的民事法律行为，如买卖合同。"},{id:"cs-3879",module:"changshi",prompt:"无偿民事法律行为是指？",options:["一方获得利益无需支付对价的民事法律行为", "需支付对价", "仅一方获益", "仅一方支付"],answer:0,explanation:"无偿民事法律行为是一方获得利益无需支付对价的民事法律行为，如赠与合同。"},{id:"cs-3880",module:"changshi",prompt:"诺成民事法律行为是指？",options:["意思表示一致即成立的民事法律行为", "需交付标的物", "需公证", "需登记"],answer:0,explanation:"诺成民事法律行为是意思表示一致即成立的民事法律行为，如买卖合同。"},{id:"cs-3881",module:"changshi",prompt:"实践民事法律行为是指？",options:["除意思表示一致外，还需交付标的物才能成立的民事法律行为", "意思表示一致即成立", "需公证", "需登记"],answer:0,explanation:"实践民事法律行为是除意思表示一致外，还需交付标的物才能成立的民事法律行为，如定金合同、自然人之间的借款合同。"},{id:"cs-3882",module:"changshi",prompt:"要式民事法律行为是指？",options:["法律规定或当事人约定必须采用特定形式的民事法律行为", "无形式要求", "仅口头形式", "仅书面形式"],answer:0,explanation:"要式民事法律行为是法律规定或当事人约定必须采用特定形式的民事法律行为，如建设工程合同应当采用书面形式。"},{id:"cs-3883",module:"changshi",prompt:"不要式民事法律行为是指？",options:["法律未规定或当事人未约定必须采用特定形式的民事法律行为", "必须采用特定形式", "仅口头形式", "仅书面形式"],answer:0,explanation:"不要式民事法律行为是法律未规定或当事人未约定必须采用特定形式的民事法律行为，当事人可以自由选择形式。"},{id:"cs-3884",module:"changshi",prompt:"主民事法律行为是指？",options:["能够独立存在的民事法律行为", "依附于其他行为", "无效行为", "可撤销行为"],answer:0,explanation:"主民事法律行为是能够独立存在的民事法律行为，如买卖合同。"},{id:"cs-3885",module:"changshi",prompt:"从民事法律行为是指？",options:["依附于主民事法律行为而存在的民事法律行为", "独立存在", "无效行为", "可撤销行为"],answer:0,explanation:"从民事法律行为是依附于主民事法律行为而存在的民事法律行为，如担保合同。"},{id:"cs-3886",module:"changshi",prompt:"物权行为的无因性是指？",options:["物权行为的效力不受债权行为效力的影响", "物权行为无效", "物权行为可撤销", "物权行为效力待定"],answer:0,explanation:"物权行为的无因性是物权行为的效力不受债权行为效力的影响，即债权行为无效或被撤销，不影响物权行为的效力。"},{id:"cs-3887",module:"changshi",prompt:"劳动合同的订立原则不包括？",options:["可以随意解除", "合法", "公平", "平等自愿、协商一致"],answer:0,explanation:"劳动合同的订立原则包括合法、公平、平等自愿、协商一致、诚实信用等；可以随意解除不属于。"},{id:"cs-3888",module:"changshi",prompt:"劳动合同的形式要求是？",options:["应当采用书面形式", "可以采用口头形式", "可以采用默示形式", "可以采用推定形式"],answer:0,explanation:"建立劳动关系，应当订立书面劳动合同；已建立劳动关系，未同时订立书面劳动合同的，应当自用工之日起1个月内订立。"},{id:"cs-3889",module:"changshi",prompt:"劳动合同的生效时间是？",options:["双方当事人签字或者盖章生效", "签订后立即生效", "劳动者入职时生效", "用人单位决定生效"],answer:0,explanation:"劳动合同由用人单位与劳动者协商一致，并经用人单位与劳动者在劳动合同文本上签字或者盖章生效。"},{id:"cs-3890",module:"changshi",prompt:"劳动合同的变更原则是？",options:["协商一致", "用人单位单方决定", "劳动者单方决定", "政府决定"],answer:0,explanation:"用人单位与劳动者协商一致，可以变更劳动合同约定的内容；变更劳动合同，应当采用书面形式。"},{id:"cs-3891",module:"changshi",prompt:"劳动合同的终止情形不包括？",options:["双方协商一致", "劳动合同期满", "劳动者开始依法享受基本养老保险待遇", "劳动者死亡，或者被人民法院宣告死亡或者宣告失踪"],answer:0,explanation:"劳动合同的终止情形包括劳动合同期满、劳动者开始依法享受基本养老保险待遇、劳动者死亡或被宣告死亡或宣告失踪等；双方协商一致是解除情形。"},{id:"cs-3892",module:"changshi",prompt:"劳动合同的解除情形不包括？",options:["劳动合同期满", "协商解除", "劳动者单方解除", "用人单位单方解除"],answer:0,explanation:"劳动合同的解除情形包括协商解除、劳动者单方解除、用人单位单方解除等；劳动合同期满是终止情形。"},{id:"cs-3893",module:"changshi",prompt:"经济性裁员的程序要求不包括？",options:["无需任何程序", "提前30日向工会或全体职工说明情况", "听取工会或职工的意见", "裁减人员方案经向劳动行政部门报告"],answer:0,explanation:"经济性裁员的程序要求包括提前30日向工会或全体职工说明情况、听取意见、裁减人员方案经向劳动行政部门报告等；无需任何程序不属于。"},{id:"cs-3894",module:"changshi",prompt:"经济性裁员的优先招用义务是？",options:["用人单位在6个月内重新招用人员的，应当通知被裁减的人员，并在同等条件下优先招用", "无需优先招用", "仅通知", "仅补偿"],answer:0,explanation:"用人单位在6个月内重新招用人员的，应当通知被裁减的人员，并在同等条件下优先招用被裁减的人员。"},{id:"cs-3895",module:"changshi",prompt:"劳务派遣的适用范围不包括？",options:["全部岗位", "临时性岗位", "辅助性岗位", "替代性岗位"],answer:0,explanation:"劳务派遣用工是补充形式，只能在临时性、辅助性或者替代性的工作岗位上实施。"},{id:"cs-3896",module:"changshi",prompt:"非全日制用工的特点不包括？",options:["必须签订书面劳动合同", "以小时计酬为主", "每日工作时间不超过4小时", "每周工作时间累计不超过24小时"],answer:0,explanation:"非全日制用工以小时计酬为主，劳动者在同一用人单位一般平均每日工作时间不超过4小时，每周工作时间累计不超过24小时；可以订立口头协议，不必须签订书面劳动合同。"},{id:"cs-3897",module:"changshi",prompt:"反垄断法规定，垄断协议的豁免条件不包括？",options:["损害消费者利益", "为实现特定目的所必需", "不会严重限制相关市场的竞争", "能够使消费者分享由此产生的利益"],answer:0,explanation:"垄断协议的豁免条件包括为实现特定目的所必需、不会严重限制相关市场的竞争、能够使消费者分享由此产生的利益等；损害消费者利益的行为不能豁免。"},{id:"cs-3898",module:"changshi",prompt:"反垄断法规定，市场支配地位的认定因素不包括？",options:["经营者的个人品德", "经营者的市场份额", "经营者控制市场的能力", "其他经营者的依赖程度"],answer:0,explanation:"市场支配地位的认定因素包括经营者的市场份额、控制市场的能力、其他经营者的依赖程度等；经营者的个人品德不属于。"},{id:"cs-3899",module:"changshi",prompt:"反不正当竞争法规定，商业混淆的认定因素不包括？",options:["是否使用与他人相同的商标", "是否擅自使用与他人有一定影响的商品名称、包装、装潢等相同或近似的标识", "是否引人误认", "是否造成混淆"],answer:0,explanation:"商业混淆的认定因素包括是否擅自使用与他人有一定影响的商品名称、包装、装潢等相同或近似的标识，是否引人误认，是否造成混淆等；是否使用与他人相同的商标不属于。"});
(window.YC_CS_BANK=window.YC_CS_BANK||[]).push({id:"cs-3900",module:"changshi",prompt:"刑罚目的理论中，特殊预防是指？",options:["防止犯罪人重新犯罪", "防止一般人犯罪", "惩罚犯罪人", "消灭犯罪"],answer:0,explanation:"特殊预防是指防止犯罪人重新犯罪，即通过对犯罪人适用刑罚，防止其再次犯罪。"},{id:"cs-3901",module:"changshi",prompt:"刑罚目的理论中，一般预防是指？",options:["防止一般人犯罪", "防止犯罪人重新犯罪", "惩罚犯罪人", "消灭犯罪"],answer:0,explanation:"一般预防是指防止一般人犯罪，即通过刑罚的威慑作用，防止一般人犯罪。"},{id:"cs-3902",module:"changshi",prompt:"民法理论上，负担行为是指？",options:["产生债权债务关系的行为", "产生物权变动", "产生身份关系", "产生继承关系"],answer:0,explanation:"负担行为是产生债权债务关系的行为，如买卖合同。"},{id:"cs-3903",module:"changshi",prompt:"民法理论上，处分行为是指？",options:["直接产生物权变动效果的行为", "产生债权债务关系", "产生身份关系", "产生继承关系"],answer:0,explanation:"处分行为是直接产生物权变动效果的行为，如交付、登记等。"});
(window.YC_CS_BANK=window.YC_CS_BANK||[]).push({id:"cs-3904",module:"changshi",prompt:"我国宪法规定，国家发展社会主义的教育事业，提高全国人民的科学文化水平，国家举办各种学校，普及？",options:["初等义务教育", "高等教育", "职业教育", "终身教育"],answer:0,explanation:"宪法规定，国家举办各种学校，普及初等义务教育，发展中等教育、职业教育和高等教育，并且发展学前教育。"},{id:"cs-3905",module:"changshi",prompt:"我国宪法规定，国家发展各种教育设施，扫除？",options:["文盲", "贫困", "疾病", "污染"],answer:0,explanation:"宪法规定，国家发展各种教育设施，扫除文盲，对工人、农民、国家工作人员和其他劳动者进行政治、文化、科学、技术、业务的教育。"},{id:"cs-3906",module:"changshi",prompt:"我国宪法规定，国家鼓励集体经济组织、国家企业事业组织和其他社会力量依照法律规定举办各种教育事业，这是关于？",options:["社会力量办学的规定", "政府办学的规定", "私人办学的禁止", "外资办学的禁止"],answer:0,explanation:"宪法规定，国家鼓励集体经济组织、国家企业事业组织和其他社会力量依照法律规定举办各种教育事业。"},{id:"cs-3907",module:"changshi",prompt:"我国宪法规定，国家通过推广普通话和规范汉字，促进？",options:["文化交流", "经济发展", "社会进步", "民族团结"],answer:0,explanation:"宪法规定，国家推广全国通用的普通话，促进文化交流和社会进步。"},{id:"cs-3908",module:"changshi",prompt:"我国宪法规定，国家发展自然科学和社会科学事业，普及科学和技术知识，奖励？",options:["科学研究成果和技术发明创造", "商业广告", "娱乐节目", "体育比赛"],answer:0,explanation:"宪法规定，国家发展自然科学和社会科学事业，普及科学和技术知识，奖励科学研究成果和技术发明创造。"},{id:"cs-3909",module:"changshi",prompt:"我国宪法规定，国家发展医疗卫生事业，保护人民健康，国家发展体育事业，增强？",options:["人民体质", "国家实力", "经济实力", "科技实力"],answer:0,explanation:"宪法规定，国家发展医疗卫生事业，保护人民健康；国家发展体育事业，增强人民体质。"},{id:"cs-3910",module:"changshi",prompt:"我国宪法规定，国家保护和改善生活环境和生态环境，防治污染和其他公害，国家组织和鼓励？",options:["植树造林，保护林木", "开垦荒地", "砍伐森林", "排放污水"],answer:0,explanation:"宪法规定，国家保护和改善生活环境和生态环境，防治污染和其他公害；国家组织和鼓励植树造林，保护林木。"},{id:"cs-3911",module:"changshi",prompt:"我国宪法规定，中华人民共和国公民有维护国家统一和全国各民族团结的义务，这是关于？",options:["公民基本义务的规定", "公民基本权利的规定", "国家机关职权的规定", "社会组织义务的规定"],answer:0,explanation:"宪法规定，中华人民共和国公民有维护国家统一和全国各民族团结的义务，这是公民的基本义务。"},{id:"cs-3912",module:"changshi",prompt:"我国宪法规定，中华人民共和国公民有维护祖国的安全、荣誉和利益的义务，不得有危害祖国的安全、荣誉和利益的行为，这是关于？",options:["公民基本义务的规定", "公民基本权利的规定", "国家机关职权的规定", "社会组织义务的规定"],answer:0,explanation:"宪法规定，中华人民共和国公民有维护祖国的安全、荣誉和利益的义务，不得有危害祖国的安全、荣誉和利益的行为。"},{id:"cs-3913",module:"changshi",prompt:"我国宪法规定，中华人民共和国公民有依照法律纳税的义务，这是关于？",options:["公民基本义务的规定", "公民基本权利的规定", "国家机关职权的规定", "社会组织义务的规定"],answer:0,explanation:"宪法规定，中华人民共和国公民有依照法律纳税的义务，这是公民的基本义务。"},{id:"cs-3914",module:"changshi",prompt:"我国宪法规定，中华人民共和国公民有劳动的权利和义务，国家通过各种途径，创造劳动就业条件，加强劳动保护，改善劳动条件，并在发展生产的基础上，提高？",options:["劳动报酬和福利待遇", "退休待遇", "社会保险待遇", "住房待遇"],answer:0,explanation:"宪法规定，中华人民共和国公民有劳动的权利和义务，国家通过各种途径，创造劳动就业条件，加强劳动保护，改善劳动条件，并在发展生产的基础上，提高劳动报酬和福利待遇。"},{id:"cs-3915",module:"changshi",prompt:"行政法上的行政主体资格的取得依据是？",options:["宪法和组织法等法律的规定", "行政机关自认", "上级机关口头授权", "行政相对人认可"],answer:0,explanation:"行政主体资格的取得依据是宪法和组织法等法律的规定，如国务院组织法、地方各级人民代表大会和地方各级人民政府组织法等。"},{id:"cs-3916",module:"changshi",prompt:"行政法上的行政主体资格的丧失情形不包括？",options:["行政机关更名", "行政机关被撤销", "行政机关被合并", "行政机关职权被收回"],answer:0,explanation:"行政主体资格的丧失情形包括行政机关被撤销、被合并、职权被收回等；行政机关更名不影响主体资格。"},{id:"cs-3917",module:"changshi",prompt:"行政法上的行政主体的种类不包括？",options:["公务员个人", "国务院", "地方各级人民政府", "法律法规授权的组织"],answer:0,explanation:"行政主体的种类包括国务院、地方各级人民政府、法律法规授权的组织等；公务员个人不是行政主体。"},{id:"cs-3918",module:"changshi",prompt:"行政法上的行政主体的职权来源不包括？",options:["行政相对人授权", "宪法和组织法的规定", "法律法规的授权", "上级机关的委托"],answer:0,explanation:"行政主体的职权来源包括宪法和组织法的规定、法律法规的授权、上级机关的委托等；行政相对人授权不属于。"},{id:"cs-3919",module:"changshi",prompt:"行政法上的行政主体的职责来源不包括？",options:["行政相对人的要求", "宪法和组织法的规定", "法律法规的规定", "上级机关的决定"],answer:0,explanation:"行政主体的职责来源包括宪法和组织法的规定、法律法规的规定、上级机关的决定等；行政相对人的要求不属于。"},{id:"cs-3920",module:"changshi",prompt:"行政法上的行政主体的权限范围不包括？",options:["行政相对人的意愿", "地域范围", "事项范围", "时间范围"],answer:0,explanation:"行政主体的权限范围包括地域范围、事项范围、时间范围等；行政相对人的意愿不属于。"},{id:"cs-3921",module:"changshi",prompt:"行政法上的行政主体的越权行为是指？",options:["超越法定权限范围行使职权的行为", "依法行使职权", "依法履行职责", "依法承担责任"],answer:0,explanation:"越权行为是行政主体超越法定权限范围行使职权的行为，包括超越地域范围、事项范围、时间范围等。"},{id:"cs-3922",module:"changshi",prompt:"行政法上的行政主体的滥用职权行为是指？",options:["违反法定目的行使职权的行为", "依法行使职权", "依法履行职责", "依法承担责任"],answer:0,explanation:"滥用职权行为是行政主体违反法定目的行使职权的行为，如以权谋私、打击报复等。"},{id:"cs-3923",module:"changshi",prompt:"行政法上的行政主体的不作为行为是指？",options:["不履行法定职责的行为", "依法履行职责", "依法行使职权", "依法承担责任"],answer:0,explanation:"不作为行为是行政主体不履行法定职责的行为，如不受理申请、不作出决定等。"},{id:"cs-3924",module:"changshi",prompt:"行政法上的行政主体的程序违法是指？",options:["违反法定程序行使职权的行为", "依法定程序行使职权", "依法履行职责", "依法承担责任"],answer:0,explanation:"程序违法是行政主体违反法定程序行使职权的行为，如不告知权利、不听取申辩等。"},{id:"cs-3925",module:"changshi",prompt:"行政法上的行政主体的证据不足是指？",options:["缺乏作出行政行为所必需的证据", "证据充分", "证据确凿", "证据合法"],answer:0,explanation:"证据不足是行政主体缺乏作出行政行为所必需的证据，如事实不清、证据不充分等。"},{id:"cs-3926",module:"changshi",prompt:"行政法上的行政主体的适用法律错误是指？",options:["适用了不应当适用的法律规范", "适用了正确的法律规范", "适用了上位法", "适用了特别法"],answer:0,explanation:"适用法律错误是行政主体适用了不应当适用的法律规范，如适用了已废止的法律、适用了效力等级较低的法律等。"},{id:"cs-3927",module:"changshi",prompt:"行政法上的行政主体的超越职权是指？",options:["超越法定权限范围行使职权的行为", "依法行使职权", "依法履行职责", "依法承担责任"],answer:0,explanation:"超越职权是行政主体超越法定权限范围行使职权的行为，包括超越地域范围、事项范围、时间范围等。"},{id:"cs-3928",module:"changshi",prompt:"行政法上的行政主体的主要证据不足是指？",options:["缺乏作出行政行为所必需的主要证据", "证据充分", "证据确凿", "证据合法"],answer:0,explanation:"主要证据不足是行政主体缺乏作出行政行为所必需的主要证据，如事实不清、主要证据缺失等。"},{id:"cs-3929",module:"changshi",prompt:"行政法上的行政主体的违反法定程序是指？",options:["违反法定程序行使职权的行为", "依法定程序行使职权", "依法履行职责", "依法承担责任"],answer:0,explanation:"违反法定程序是行政主体违反法定程序行使职权的行为，如不告知权利、不听取申辩等。"},{id:"cs-3930",module:"changshi",prompt:"我国刑法规定的犯罪的基本特征不包括？",options:["应受道德谴责性", "社会危害性", "刑事违法性", "应受刑罚处罚性"],answer:0,explanation:"犯罪的基本特征包括社会危害性、刑事违法性和应受刑罚处罚性；应受道德谴责性不是犯罪的基本特征。"},{id:"cs-3931",module:"changshi",prompt:"我国刑法规定的社会危害性是指？",options:["行为对刑法所保护的社会关系造成或可能造成损害的特性", "行为对个人利益的损害", "行为对道德的违反", "行为对习惯的违反"],answer:0,explanation:"社会危害性是行为对刑法所保护的社会关系造成或可能造成损害的特性，是犯罪的最基本特征。"},{id:"cs-3932",module:"changshi",prompt:"我国刑法规定的刑事违法性是指？",options:["行为违反刑法的规定，符合犯罪构成要件", "行为违反道德", "行为违反习惯", "行为违反政策"],answer:0,explanation:"刑事违法性是行为违反刑法的规定，符合犯罪构成要件，是罪刑法定原则的体现。"},{id:"cs-3933",module:"changshi",prompt:"我国刑法规定的应受刑罚处罚性是指？",options:["行为应当受到刑罚处罚的特性", "行为应当受到道德谴责", "行为应当受到行政处分", "行为应当受到民事制裁"],answer:0,explanation:"应受刑罚处罚性是行为应当受到刑罚处罚的特性，是犯罪的社会危害性和刑事违法性的法律后果。"},{id:"cs-3934",module:"changshi",prompt:"我国刑法规定的犯罪构成是指？",options:["刑法规定的，决定某种行为构成犯罪所必需的一切主观和客观要件的总和", "刑法规定的刑罚种类", "刑法规定的刑罚执行方式", "刑法规定的刑罚免除事由"],answer:0,explanation:"犯罪构成是刑法规定的，决定某种行为构成犯罪所必需的一切主观和客观要件的总和。"},{id:"cs-3935",module:"changshi",prompt:"我国刑法规定的犯罪构成的种类不包括？",options:["道德构成", "一般构成", "具体构成", "修正构成"],answer:0,explanation:"犯罪构成的种类包括一般构成、具体构成、修正构成等；道德构成不属于犯罪构成。"},{id:"cs-3936",module:"changshi",prompt:"我国刑法规定的犯罪构成的一般要件不包括？",options:["犯罪动机", "犯罪客体", "犯罪客观方面", "犯罪主体"],answer:0,explanation:"犯罪构成的一般要件包括犯罪客体、犯罪客观方面、犯罪主体和犯罪主观方面；犯罪动机不是犯罪构成的一般要件。"},{id:"cs-3937",module:"changshi",prompt:"我国刑法规定的犯罪客体的种类不包括？",options:["犯罪动机", "一般客体", "同类客体", "直接客体"],answer:0,explanation:"犯罪客体的种类包括一般客体、同类客体和直接客体；犯罪动机不是犯罪客体。"},{id:"cs-3938",module:"changshi",prompt:"我国刑法规定的犯罪客观方面的要件不包括？",options:["犯罪动机", "危害行为", "危害结果", "因果关系"],answer:0,explanation:"犯罪客观方面的要件包括危害行为、危害结果、因果关系等；犯罪动机不是客观方面的要件。"},{id:"cs-3939",module:"changshi",prompt:"我国刑法规定的犯罪主体的要件不包括？",options:["犯罪动机", "自然人或单位", "刑事责任能力", "刑事责任年龄"],answer:0,explanation:"犯罪主体的要件包括自然人或单位、刑事责任能力、刑事责任年龄等；犯罪动机不是主体的要件。"},{id:"cs-3940",module:"changshi",prompt:"我国刑法规定的犯罪主观方面的要件不包括？",options:["犯罪动机", "犯罪故意", "犯罪过失", "犯罪目的"],answer:0,explanation:"犯罪主观方面的要件包括犯罪故意、犯罪过失、犯罪目的等；犯罪动机不是主观方面的要件。"},{id:"cs-3941",module:"changshi",prompt:"我国刑法规定的犯罪故意的种类不包括？",options:["犯罪动机", "直接故意", "间接故意", "明知"],answer:0,explanation:"犯罪故意的种类包括直接故意和间接故意；犯罪动机不是犯罪故意。"},{id:"cs-3942",module:"changshi",prompt:"我国刑法规定的犯罪过失的种类不包括？",options:["犯罪动机", "疏忽大意的过失", "过于自信的过失", "轻信能够避免"],answer:0,explanation:"犯罪过失的种类包括疏忽大意的过失和过于自信的过失；犯罪动机不是犯罪过失。"},{id:"cs-3943",module:"changshi",prompt:"我国刑法规定的危害行为的种类不包括？",options:["犯罪动机", "作为", "不作为", "持有"],answer:0,explanation:"危害行为的种类包括作为、不作为和持有；犯罪动机不是危害行为。"},{id:"cs-3944",module:"changshi",prompt:"民事法律行为的生效要件不包括？",options:["必须经过公证", "行为人具有相应的民事行为能力", "意思表示真实", "不违反法律、行政法规的强制性规定，不违背公序良俗"],answer:0,explanation:"民事法律行为的生效要件包括行为人具有相应的民事行为能力、意思表示真实、不违反法律行政法规的强制性规定不违背公序良俗；公证不是生效要件。"},{id:"cs-3945",module:"changshi",prompt:"民事法律行为的无效情形不包括？",options:["意思表示真实", "无民事行为能力人实施的", "违反法律、行政法规的强制性规定的", "违背公序良俗的"],answer:0,explanation:"民事法律行为的无效情形包括无民事行为能力人实施的、违反法律行政法规的强制性规定的、违背公序良俗的等；意思表示真实是有效要件。"},{id:"cs-3946",module:"changshi",prompt:"民事法律行为的可撤销情形不包括？",options:["意思表示真实", "重大误解", "欺诈", "胁迫"],answer:0,explanation:"民事法律行为的可撤销情形包括重大误解、欺诈、胁迫、显失公平等；意思表示真实是有效要件。"},{id:"cs-3947",module:"changshi",prompt:"民事法律行为的效力待定情形不包括？",options:["无民事行为能力人实施的", "限制民事行为能力人实施的依法不能独立实施的", "无权代理", "无权处分"],answer:0,explanation:"民事法律行为的效力待定情形包括限制民事行为能力人实施的依法不能独立实施的、无权代理、无权处分等；无民事行为能力人实施的属于无效。"},{id:"cs-3948",module:"changshi",prompt:"代理权的行使原则不包括？",options:["可以随意处分被代理人利益", "亲自行使", "勤勉尽责", "诚信行使"],answer:0,explanation:"代理权的行使原则包括亲自行使、勤勉尽责、诚信行使等；可以随意处分被代理人利益不属于。"},{id:"cs-3949",module:"changshi",prompt:"代理权的终止情形不包括？",options:["代理人继续行使代理权", "代理期限届满或者代理事务完成", "被代理人取消委托或者代理人辞去委托", "代理人丧失民事行为能力"],answer:0,explanation:"代理权终止的情形包括代理期限届满或代理事务完成、被代理人取消委托或代理人辞去委托、代理人丧失民事行为能力等；代理人继续行使代理权不属于。"},{id:"cs-3950",module:"changshi",prompt:"无权代理的法律后果不包括？",options:["被代理人自动承担", "未经被代理人追认的，对被代理人不发生效力", "相对人有催告权", "善意相对人有撤销权"],answer:0,explanation:"无权代理的法律后果包括未经被代理人追认的对被代理人不发生效力、相对人有催告权、善意相对人有撤销权等；被代理人自动承担不属于。"},{id:"cs-3951",module:"changshi",prompt:"诉讼时效的适用范围不包括？",options:["请求停止侵害、排除妨碍、消除危险", "请求返还借款", "请求支付货款", "请求赔偿损失"],answer:0,explanation:"诉讼时效的适用范围是债权请求权；请求停止侵害、排除妨碍、消除危险等不适用诉讼时效。"},{id:"cs-3952",module:"changshi",prompt:"诉讼时效的中止事由是？",options:["在诉讼时效期间的最后6个月内，因不可抗力等障碍不能行使请求权", "权利人主张权利", "义务人同意履行", "提起诉讼"],answer:0,explanation:"在诉讼时效期间的最后6个月内，因不可抗力、无民事行为能力人没有法定代理人等障碍不能行使请求权的，诉讼时效中止。"},{id:"cs-3953",module:"changshi",prompt:"诉讼时效的中断事由不包括？",options:["时效期间届满", "权利人向义务人提出履行请求", "义务人同意履行义务", "权利人提起诉讼或申请仲裁"],answer:0,explanation:"诉讼时效中断的事由包括权利人向义务人提出履行请求、义务人同意履行义务、权利人提起诉讼或申请仲裁等；时效期间届满是时效完成的情形。"},{id:"cs-3954",module:"changshi",prompt:"物权公示原则的公示方法不包括？",options:["公证", "交付（动产）", "登记（不动产）", "占有"],answer:0,explanation:"物权公示原则的公示方法包括交付（动产）、登记（不动产）、占有等；公证不属于公示方法。"},{id:"cs-3955",module:"changshi",prompt:"物权法定原则的内容不包括？",options:["物权内容由当事人约定", "物权种类法定", "物权内容法定", "物权效力法定"],answer:0,explanation:"物权法定原则的内容包括物权种类法定、物权内容法定、物权效力法定等；物权内容由当事人约定不属于。"});
(window.YC_CS_BANK=window.YC_CS_BANK||[]).push({id:"cs-3956",module:"changshi",prompt:"我国宪法规定，人民行使国家权力的机关是？",options:["全国人民代表大会和地方各级人民代表大会", "国务院", "中国共产党", "人民法院"],answer:0,explanation:"宪法规定，中华人民共和国的一切权力属于人民；人民行使国家权力的机关是全国人民代表大会和地方各级人民代表大会。"},{id:"cs-3957",module:"changshi",prompt:"我国宪法规定，有选举权和被选举权的年满多少周岁的中华人民共和国公民可以被选为国家主席？",options:["45周岁", "40周岁", "35周岁", "50周岁"],answer:0,explanation:"宪法规定，有选举权和被选举权的年满45周岁的中华人民共和国公民可以被选为中华人民共和国主席、副主席。"},{id:"cs-3958",module:"changshi",prompt:"我国宪法规定，宅基地和自留地、自留山属于？",options:["集体所有", "国家所有", "个人所有", "农户所有"],answer:0,explanation:"宪法规定，宅基地和自留地、自留山，属于集体所有；任何组织或者个人不得侵占、买卖或者以其他形式非法转让土地。"},{id:"cs-3959",module:"changshi",prompt:"我国宪法规定，监察委员会是国家的？",options:["监察机关", "行政机关", "审判机关", "检察机关"],answer:0,explanation:"宪法规定，中华人民共和国各级监察委员会是国家的监察机关，依法对所有行使公权力的公职人员进行监察。"},{id:"cs-3960",module:"changshi",prompt:"我国宪法规定，地方各级监察委员会对谁负责？",options:["产生它的国家权力机关和上一级监察委员会", "仅本级人民政府", "仅上一级监察委员会", "本级政协"],answer:0,explanation:"宪法规定，地方各级监察委员会对产生它的国家权力机关和上一级监察委员会负责。"},{id:"cs-3961",module:"changshi",prompt:"我国宪法规定，全国人民代表大会常务委员会委员长、副委员长连续任职不得超过？",options:["两届", "一届", "三届", "无限制"],answer:0,explanation:"宪法规定，全国人民代表大会常务委员会委员长、副委员长连续任职不得超过两届。"},{id:"cs-3962",module:"changshi",prompt:"我国宪法规定，中华人民共和国国务院即？",options:["中央人民政府，是最高国家权力机关的执行机关", "最高审判机关", "最高监察机关", "最高检察机关"],answer:0,explanation:"宪法规定，中华人民共和国国务院，即中央人民政府，是最高国家权力机关的执行机关，是最高国家行政机关。"},{id:"cs-3963",module:"changshi",prompt:"我国宪法规定，各少数民族聚居的地方实行？",options:["区域自治", "高度自治", "特别行政区制度", "联邦制"],answer:0,explanation:"宪法规定，各少数民族聚居的地方实行区域自治，设立自治机关，行使自治权；各民族自治地方都是中华人民共和国不可分离的部分。"},{id:"cs-3964",module:"changshi",prompt:"我国宪法规定，国家工作人员就职时应当依照法律规定公开进行？",options:["宪法宣誓", "任职考试", "民主评议", "财产申报"],answer:0,explanation:"宪法规定，国家工作人员就职时应当依照法律规定公开进行宪法宣誓。"},{id:"cs-3965",module:"changshi",prompt:"我国宪法的修改由全国人民代表大会常务委员会或者多少以上的全国人民代表大会代表提议？",options:["五分之一", "十分之一", "三分之一", "二分之一"],answer:0,explanation:"宪法规定，宪法的修改由全国人民代表大会常务委员会或者五分之一以上的全国人民代表大会代表提议，并由全国人民代表大会以全体代表的三分之二以上的多数通过。"},{id:"cs-3966",module:"changshi",prompt:"自然人的民事权利能力终于？",options:["死亡", "丧失行为能力", "被判刑", "失踪"],answer:0,explanation:"自然人的民事权利能力终于死亡，包括自然死亡和宣告死亡；死亡后其民事权利能力消灭。"},{id:"cs-3967",module:"changshi",prompt:"8周岁以上的未成年人是？",options:["限制民事行为能力人", "无民事行为能力人", "完全民事行为能力人", "视同完全民事行为能力人"],answer:0,explanation:"民法规定，8周岁以上的未成年人为限制民事行为能力人，实施民事法律行为由其法定代理人代理或者经其法定代理人同意、追认。"},{id:"cs-3968",module:"changshi",prompt:"不满8周岁的未成年人是？",options:["无民事行为能力人", "限制民事行为能力人", "完全民事行为能力人", "部分民事行为能力人"],answer:0,explanation:"民法规定，不满8周岁的未成年人为无民事行为能力人，由其法定代理人代理实施民事法律行为。"},{id:"cs-3969",module:"changshi",prompt:"利害关系人可以向人民法院申请宣告失踪的条件是自然人下落不明满？",options:["2年", "1年", "3年", "4年"],answer:0,explanation:"民法规定，自然人下落不明满2年的，利害关系人可以向人民法院申请宣告该自然人为失踪人。"},{id:"cs-3970",module:"changshi",prompt:"因意外事件下落不明申请宣告死亡的，满几年即可？",options:["2年", "4年", "1年", "5年"],answer:0,explanation:"民法规定，自然人因意外事件下落不明满2年的，利害关系人可以向人民法院申请宣告死亡；一般情形下落不明满4年。"},{id:"cs-3971",module:"changshi",prompt:"要约人撤销要约的通知应当在什么时间之前到达受要约人？",options:["受要约人发出承诺之前", "合同履行完毕之前", "要约发出之前", "任何时间"],answer:0,explanation:"民法规定，要约可以撤销，撤销要约的通知应当在受要约人发出承诺之前到达受要约人。"},{id:"cs-3972",module:"changshi",prompt:"承诺应当在什么期限内到达要约人？",options:["要约确定的期限内", "一个月内", "一周内", "任意时间"],answer:0,explanation:"民法规定，承诺应当在要约确定的期限内到达要约人；要约没有确定期限的，承诺应当依照法律规定在合理期限内到达。"},{id:"cs-3973",module:"changshi",prompt:"侵权责任的归责原则包括过错责任原则和？",options:["无过错责任原则", "公平责任原则", "过错推定原则", "严格责任原则"],answer:0,explanation:"侵权责任的归责原则包括过错责任原则和无过错责任原则；法律规定的无过错责任情形，行为人即使没有过错也要承担责任。"},{id:"cs-3974",module:"changshi",prompt:"饲养的动物造成他人损害的，动物饲养人或者管理人应当承担侵权责任，但能够证明损害是因被侵权人故意或者重大过失造成的，可以？",options:["不承担或者减轻责任", "免除全部责任", "加重责任", "由被侵权人自担"],answer:0,explanation:"民法规定，饲养的动物造成他人损害的，动物饲养人或者管理人应当承担侵权责任；但能够证明损害是因被侵权人故意或者重大过失造成的，可以不承担或者减轻责任。"},{id:"cs-3975",module:"changshi",prompt:"遗嘱继承相对于法定继承的效力是？",options:["遗嘱继承优先于法定继承", "法定继承优先于遗嘱继承", "两者效力相同", "遗嘱继承无效"],answer:0,explanation:"继承开始后，按照法定继承办理；有遗嘱的，按照遗嘱继承或者遗赠办理，即遗嘱继承优先于法定继承。"},{id:"cs-3976",module:"changshi",prompt:"被继承人的子女先于被继承人死亡的，由被继承人的子女的直系晚辈血亲？",options:["代位继承", "转继承", "共同继承", "放弃继承"],answer:0,explanation:"民法规定，被继承人的子女先于被继承人死亡的，由被继承人的子女的直系晚辈血亲代位继承。"},{id:"cs-3977",module:"changshi",prompt:"民事主体的财产权利受法律平等保护，这体现了民法的？",options:["平等原则", "自愿原则", "公平原则", "诚信原则"],answer:0,explanation:"民法规定，民事主体在民事活动中的法律地位一律平等，体现平等原则；民事主体的财产权利受法律平等保护。"},{id:"cs-3978",module:"changshi",prompt:"向人民法院请求保护民事权利的普通诉讼时效期间为？",options:["3年", "1年", "2年", "5年"],answer:0,explanation:"民法规定，向人民法院请求保护民事权利的诉讼时效期间为3年，自权利人知道或者应当知道权利受到损害以及义务人之日起计算。"},{id:"cs-3979",module:"changshi",prompt:"我国刑法规定的主刑种类不包括？",options:["罚金", "管制", "拘役", "有期徒刑"],answer:0,explanation:"主刑包括管制、拘役、有期徒刑、无期徒刑和死刑；罚金属于附加刑。"},{id:"cs-3980",module:"changshi",prompt:"我国刑法规定，管制的期限为？",options:["3个月以上2年以下", "1个月以上6个月以下", "6个月以上15年以下", "1年以上3年以下"],answer:0,explanation:"刑法规定，管制的期限为3个月以上2年以下；数罪并罚时最高不能超过3年。"},{id:"cs-3981",module:"changshi",prompt:"我国刑法规定，拘役的期限为？",options:["1个月以上6个月以下", "3个月以上2年以下", "6个月以上1年以下", "15日以上3个月以下"],answer:0,explanation:"刑法规定，拘役的期限为1个月以上6个月以下；数罪并罚时最高不能超过1年。"},{id:"cs-3982",module:"changshi",prompt:"我国刑法规定，有期徒刑的期限一般为？",options:["6个月以上15年以下", "1个月以上6个月以下", "1年以上10年以下", "3个月以上2年以下"],answer:0,explanation:"刑法规定，有期徒刑的期限一般为6个月以上15年以下；数罪并罚等法定情形下可以超过15年。"},{id:"cs-3983",module:"changshi",prompt:"我国刑法规定，判处死刑缓期执行的期间为？",options:["2年", "1年", "3年", "5年"],answer:0,explanation:"刑法规定，对于应当判处死刑的犯罪分子，如果不是必须立即执行的，可以判处死刑同时宣告缓期2年执行。"},{id:"cs-3984",module:"changshi",prompt:"我国刑法规定，构成一般累犯的条件是刑罚执行完毕或者赦免以后，在几年以内再犯应当判处有期徒刑以上刑罚之罪？",options:["5年", "3年", "2年", "10年"],answer:0,explanation:"刑法规定，被判处有期徒刑以上刑罚的犯罪分子，刑罚执行完毕或者赦免以后，在5年以内再犯应当判处有期徒刑以上刑罚之罪的，是累犯，应当从重处罚。"},{id:"cs-3985",module:"changshi",prompt:"我国刑法规定，犯罪以后自动投案，如实供述自己的罪行的，是？",options:["自首", "立功", "坦白", "悔过"],answer:0,explanation:"刑法规定，犯罪以后自动投案，如实供述自己的罪行的，是自首；对于自首的犯罪分子，可以从轻或者减轻处罚。"},{id:"cs-3986",module:"changshi",prompt:"我国刑法规定，犯罪分子揭发他人犯罪行为，查证属实的，或者提供重要线索得以侦破其他案件的，属于？",options:["立功", "自首", "坦白", "中止"],answer:0,explanation:"刑法规定，犯罪分子有揭发他人犯罪行为查证属实，或者提供重要线索得以侦破其他案件等立功表现的，可以从轻或者减轻处罚；重大立功可以减轻或者免除处罚。"},{id:"cs-3987",module:"changshi",prompt:"我国刑法规定，数罪并罚时管制最高不能超过？",options:["3年", "2年", "1年", "5年"],answer:0,explanation:"刑法规定，数罪并罚时管制最高不能超过3年，拘役最高不能超过1年。"},{id:"cs-3988",module:"changshi",prompt:"我国刑法规定，适用缓刑的条件是被判处？",options:["拘役或者3年以下有期徒刑", "无期徒刑", "死刑缓期执行", "管制"],answer:0,explanation:"刑法规定，对于被判处拘役或者3年以下有期徒刑的犯罪分子，同时符合犯罪情节较轻、有悔罪表现等条件的，可以宣告缓刑。"},{id:"cs-3989",module:"changshi",prompt:"我国刑法规定，被判处有期徒刑的犯罪分子适用假释，应当已执行原判刑期的？",options:["二分之一以上", "三分之一以上", "四分之一以上", "三分之二以上"],answer:0,explanation:"刑法规定，被判处有期徒刑的犯罪分子，执行原判刑期二分之一以上，认真遵守监规、接受教育改造，确有悔改表现，没有再犯罪的危险的，可以假释。"},{id:"cs-3990",module:"changshi",prompt:"我国刑法规定，法定最高刑为不满5年有期徒刑的犯罪，追诉期限为？",options:["5年", "10年", "15年", "20年"],answer:0,explanation:"刑法规定，法定最高刑为不满5年有期徒刑的，经过5年不再追诉；法定最高刑为5年以上不满10年的，经过10年。"},{id:"cs-3991",module:"changshi",prompt:"我国刑法规定，正当防卫明显超过必要限度造成重大损害的，应当负刑事责任，但是应当？",options:["减轻或者免除处罚", "从重处罚", "加重处罚", "同等处罚"],answer:0,explanation:"刑法规定，正当防卫明显超过必要限度造成重大损害的，应当负刑事责任，但是应当减轻或者免除处罚。"},{id:"cs-3992",module:"changshi",prompt:"我国刑法规定，为了使国家、公共利益、本人或者他人的人身、财产和其他权利免受正在进行的不法侵害，而采取的制止不法侵害的行为，对不法侵害人造成损害的，属于？",options:["正当防卫，不负刑事责任", "紧急避险", "过失犯罪", "故意犯罪"],answer:0,explanation:"刑法规定，正当防卫针对正在进行的不法侵害，没有明显超过必要限度的，不负刑事责任。"},{id:"cs-3993",module:"changshi",prompt:"我国行政许可法规定，可以设定行政许可的规范性文件不包括？",options:["部门规章", "法律", "行政法规", "地方性法规"],answer:0,explanation:"行政许可法规定，法律、行政法规、国务院决定、地方性法规和省级政府规章可以设定行政许可；部门规章不得设定行政许可。"},{id:"cs-3994",module:"changshi",prompt:"我国行政许可法规定，省、自治区、直辖市人民政府规章可以设定临时性的行政许可，期限为？",options:["1年", "6个月", "2年", "3个月"],answer:0,explanation:"行政许可法规定，尚未制定法律、行政法规和地方性法规的，省级政府规章可以设定临时性的行政许可，临时性行政许可实施满1年需要继续实施的，应当提请本级人民代表大会及其常务委员会制定地方性法规。"},{id:"cs-3995",module:"changshi",prompt:"我国行政许可法规定，行政机关应当自受理行政许可申请之日起多少日内作出行政许可决定？",options:["20日", "10日", "30日", "15日"],answer:0,explanation:"行政许可法规定，除可以当场作出行政许可决定的外，行政机关应当自受理行政许可申请之日起20日内作出行政许可决定；延长不得超过10日。"},{id:"cs-3996",module:"changshi",prompt:"我国行政处罚法规定，行政拘留只能由谁设定？",options:["法律", "行政法规", "地方性法规", "部门规章"],answer:0,explanation:"行政处罚法规定，限制人身自由的行政处罚，只能由法律设定；行政拘留是限制人身自由的处罚，只能由法律设定。"},{id:"cs-3997",module:"changshi",prompt:"我国行政处罚法规定，违法行为在几年内未被发现的，不再给予行政处罚？",options:["2年", "1年", "3年", "5年"],answer:0,explanation:"行政处罚法规定，违法行为在2年内未被发现的，不再给予行政处罚；涉及公民生命健康安全、金融安全且有危害后果的，延长至5年。"},{id:"cs-3998",module:"changshi",prompt:"我国行政复议法规定，公民、法人或者其他组织申请行政复议的期限是自知道该行政行为之日起？",options:["60日内", "30日内", "90日内", "6个月内"],answer:0,explanation:"行政复议法规定，公民、法人或者其他组织认为行政行为侵犯其合法权益的，可以自知道该行政行为之日起60日内提出行政复议申请。"},{id:"cs-3999",module:"changshi",prompt:"我国行政诉讼法规定，对行政行为提起诉讼的直接起诉期限是自知道或者应当知道作出行政行为之日起？",options:["6个月内", "3个月内", "60日内", "1年内"],answer:0,explanation:"行政诉讼法规定，公民、法人或者其他组织直接向人民法院提起诉讼的，应当自知道或者应当知道作出行政行为之日起6个月内提出。"},{id:"cs-4000",module:"changshi",prompt:"我国行政诉讼法规定，被告对作出的行政行为负有？",options:["举证责任", "申请回避的责任", "调解的责任", "反诉的责任"],answer:0,explanation:"行政诉讼法规定，被告对作出的行政行为负有举证责任，应当提供作出该行政行为的证据和所依据的规范性文件。"},{id:"cs-4001",module:"changshi",prompt:"我国行政诉讼法规定，人民法院审理行政案件，对行政行为是否合法进行？",options:["审查", "调解", "仲裁", "备案"],answer:0,explanation:"行政诉讼法规定，人民法院审理行政案件，对行政行为是否合法进行审查；行政赔偿、补偿及行使自由裁量权的案件可以调解。"},{id:"cs-4002",module:"changshi",prompt:"我国国家赔偿法规定，赔偿请求人请求国家赔偿的时效为？",options:["2年", "1年", "6个月", "3年"],answer:0,explanation:"国家赔偿法规定，赔偿请求人请求国家赔偿的时效为2年，自其知道或者应当知道国家机关及其工作人员行使职权时的行为侵犯其人身权、财产权之日起计算。"},{id:"cs-4003",module:"changshi",prompt:"我国行政强制法规定，行政强制的种类不包括？",options:["行政拘留", "查封", "扣押", "冻结"],answer:0,explanation:"行政强制包括行政强制措施和行政强制执行；行政强制措施包括限制公民人身自由、查封、扣押、冻结等；行政拘留属于行政处罚。"},{id:"cs-4004",module:"changshi",prompt:"我国行政处罚法规定，行政处罚的种类不包括？",options:["查封场所", "警告", "罚款", "吊销许可证"],answer:0,explanation:"行政处罚的种类包括警告、罚款、没收违法所得、责令停产停业、暂扣或者吊销许可证件、行政拘留等；查封场所属于行政强制措施。"},{id:"cs-4005",module:"changshi",prompt:"我国行政许可法规定，行政许可需要行政机关内多个机构办理的，应当确定？",options:["一个机构统一受理行政许可申请", "分别受理", "由申请人逐个申请", "由上级机关受理"],answer:0,explanation:"行政许可法规定，行政许可需要行政机关内多个机构办理的，该行政机关应当确定一个机构统一受理行政许可申请，统一送达行政许可决定。"},{id:"cs-4006",module:"changshi",prompt:"我国行政复议法规定，行政复议机关应当自受理申请之日起多少日内作出行政复议决定？",options:["60日内", "30日内", "90日内", "15日内"],answer:0,explanation:"行政复议法规定，行政复议机关应当自受理申请之日起60日内作出行政复议决定；法律规定少于60日的除外。"},{id:"cs-4007",module:"changshi",prompt:"我国国家赔偿法规定，行政赔偿义务机关是？",options:["行使行政职权侵犯公民合法权益的行政机关", "人民法院", "人民检察院", "监察委员会"],answer:0,explanation:"国家赔偿法规定，行政机关及其工作人员行使行政职权侵犯公民、法人和其他组织的合法权益造成损害的，该行政机关为赔偿义务机关。"},{id:"cs-4008",module:"changshi",prompt:"我国劳动法规定，劳动者平均每周工作时间不超过？",options:["44小时", "40小时", "48小时", "36小时"],answer:0,explanation:"劳动法规定，劳动者每日工作时间不超过8小时、平均每周工作时间不超过44小时；国务院规定的标准工时为每日8小时、每周40小时。"},{id:"cs-4009",module:"changshi",prompt:"我国劳动法规定，用人单位应当保证劳动者每周至少休息？",options:["1日", "2日", "半日", "3日"],answer:0,explanation:"劳动法规定，用人单位应当保证劳动者每周至少休息1日。"},{id:"cs-4010",module:"changshi",prompt:"我国劳动法规定，用人单位由于生产经营需要，经与工会和劳动者协商后可以延长工作时间，一般每日不得超过？",options:["1小时", "2小时", "3小时", "4小时"],answer:0,explanation:"劳动法规定，延长工作时间一般每日不得超过1小时；因特殊原因需要延长工作时间的，在保障劳动者身体健康的条件下每日不得超过3小时，每月不得超过36小时。"},{id:"cs-4011",module:"changshi",prompt:"我国劳动法规定，女职工生育享受不少于多少天的产假？",options:["90天", "60天", "120天", "45天"],answer:0,explanation:"劳动法规定，女职工生育享受不少于90天的产假；现行的女职工劳动保护特别规定为98天。"},{id:"cs-4012",module:"changshi",prompt:"我国劳动合同法规定，劳动合同期限3个月以上不满1年的，试用期不得超过？",options:["1个月", "2个月", "3个月", "6个月"],answer:0,explanation:"劳动合同法规定，劳动合同期限3个月以上不满1年的，试用期不得超过1个月；1年以上不满3年的，不得超过2个月。"},{id:"cs-4013",module:"changshi",prompt:"我国劳动合同法规定，3年以上固定期限和无固定期限的劳动合同，试用期不得超过？",options:["6个月", "3个月", "2个月", "12个月"],answer:0,explanation:"劳动合同法规定，3年以上固定期限和无固定期限的劳动合同，试用期不得超过6个月。"},{id:"cs-4014",module:"changshi",prompt:"我国劳动合同法规定，劳动者在试用期的工资不得低于本单位相同岗位最低档工资或者劳动合同约定工资的？",options:["80%", "70%", "60%", "90%"],answer:0,explanation:"劳动合同法规定，劳动者在试用期的工资不得低于本单位相同岗位最低档工资或者劳动合同约定工资的80%，并不得低于用人单位所在地的最低工资标准。"},{id:"cs-4015",module:"changshi",prompt:"我国劳动合同法规定，经济补偿按劳动者在本单位工作的年限，每满1年支付？",options:["1个月工资", "2个月工资", "半个月工资", "3个月工资"],answer:0,explanation:"劳动合同法规定，经济补偿按劳动者在本单位工作的年限，每满1年支付1个月工资的标准向劳动者支付；6个月以上不满1年的，按1年计算。"},{id:"cs-4016",module:"changshi",prompt:"我国劳动法规定，用人单位与劳动者发生劳动争议，可以协商解决，也可以申请？",options:["调解、仲裁、提起诉讼", "直接起诉", "行政拘留", "信访"],answer:0,explanation:"劳动法规定，劳动争议发生后，当事人可以协商解决，也可以申请调解、仲裁、提起诉讼；仲裁是提起诉讼的前置程序。"},{id:"cs-4017",module:"changshi",prompt:"我国劳动合同法规定，用人单位自用工之日起超过1个月不满1年未与劳动者订立书面劳动合同的，应当？",options:["向劳动者每月支付2倍的工资", "支付3倍工资", "支付补偿金", "无需承担责任"],answer:0,explanation:"劳动合同法规定，用人单位自用工之日起超过1个月不满1年未与劳动者订立书面劳动合同的，应当向劳动者每月支付2倍的工资。"},{id:"cs-4018",module:"changshi",prompt:"我国消费者权益保护法规定，经营者采用网络、电视、电话、邮购等方式销售商品，消费者有权自收到商品之日起多少日内退货？",options:["7日", "3日", "15日", "30日"],answer:0,explanation:"消费者权益保护法规定，经营者采用网络、电视、电话、邮购等方式销售商品，消费者有权自收到商品之日起7日内退货，且无需说明理由。"},{id:"cs-4019",module:"changshi",prompt:"我国消费者权益保护法规定，经营者提供商品或者服务有欺诈行为的，增加赔偿的金额为消费者购买商品的价款或者接受服务的费用的？",options:["3倍", "1倍", "2倍", "5倍"],answer:0,explanation:"消费者权益保护法规定，经营者提供商品或者服务有欺诈行为的，应当按照消费者的要求增加赔偿其受到的损失，增加赔偿的金额为价款的3倍；不足500元的，为500元。"},{id:"cs-4020",module:"changshi",prompt:"我国消费者权益保护法规定，经营者明知商品或者服务存在缺陷仍然向消费者提供，造成消费者死亡或者健康严重损害的，受害人可以要求所受损失几倍以下的惩罚性赔偿？",options:["2倍", "1倍", "3倍", "5倍"],answer:0,explanation:"消费者权益保护法规定，经营者明知商品或者服务存在缺陷仍然向消费者提供，造成消费者或者其他受害人死亡或者健康严重损害的，受害人可以要求所受损失2倍以下的惩罚性赔偿。"},{id:"cs-4021",module:"changshi",prompt:"我国个人所得税法规定，工资、薪金所得的基本减除费用标准为每月？",options:["5000元", "3500元", "6000元", "8000元"],answer:0,explanation:"个人所得税法规定，居民个人的综合所得，以每一纳税年度的收入额减除费用6万元（即每月5000元）以及专项扣除、专项附加扣除等后的余额，为应纳税所得额。"},{id:"cs-4022",module:"changshi",prompt:"我国个人所得税法规定的专项附加扣除不包括？",options:["基本生活消费", "子女教育", "大病医疗", "住房贷款利息"],answer:0,explanation:"个人所得税专项附加扣除包括子女教育、继续教育、大病医疗、住房贷款利息、住房租金、赡养老人等；基本生活消费不属于专项附加扣除。"},{id:"cs-4023",module:"changshi",prompt:"我国反垄断法禁止具有竞争关系的经营者达成？",options:["垄断协议", "合作协议", "联营协议", "加盟协议"],answer:0,explanation:"反垄断法禁止具有竞争关系的经营者达成排除、限制竞争的垄断协议，如固定价格、限制数量、分割市场等协议。"},{id:"cs-4024",module:"changshi",prompt:"我国反不正当竞争法规定，经营者不得采用财物或者其他手段贿赂？",options:["交易相对方的工作人员等，以谋取交易机会或者竞争优势", "消费者", "竞争对手的员工", "新闻媒体"],answer:0,explanation:"反不正当竞争法规定，经营者不得采用财物或者其他手段贿赂交易相对方的工作人员、受托人以及利用职权影响交易的单位或个人，以谋取交易机会或者竞争优势。"},{id:"cs-4025",module:"changshi",prompt:"我国电子商务法规定，电子商务经营者应当依法办理？",options:["市场主体登记", "税务登记", "商标注册", "专利登记"],answer:0,explanation:"电子商务法规定，电子商务经营者应当依法办理市场主体登记；但是个人销售自产农副产品、家庭手工业产品等依法不需要登记的除外。"},{id:"cs-4026",module:"changshi",prompt:"我国消费者权益保护法规定，消费者在购买、使用商品时，其合法权益受到损害的，可以向谁要求赔偿？",options:["销售者", "生产者", "广告发布者", "电商平台"],answer:0,explanation:"消费者权益保护法规定，消费者在购买、使用商品时，其合法权益受到损害的，可以向销售者要求赔偿；属于生产者责任的，销售者赔偿后有权向生产者追偿。"},{id:"cs-4027",module:"changshi",prompt:"我国产品质量法规定，生产者应当对其生产的产品质量负责，产品质量应当符合？",options:["保障人体健康和人身、财产安全的国家标准、行业标准", "企业内部标准", "消费者个人要求", "国际最高标准"],answer:0,explanation:"产品质量法规定，产品质量应当检验合格，符合保障人体健康和人身、财产安全的国家标准、行业标准。"},{id:"cs-4028",module:"changshi",prompt:"我国民事诉讼法规定，第一审民事案件原则上由哪一级人民法院管辖？",options:["基层人民法院", "中级人民法院", "高级人民法院", "最高人民法院"],answer:0,explanation:"民事诉讼法规定，第一审民事案件原则上由基层人民法院管辖；重大涉外案件等由中级人民法院管辖。"},{id:"cs-4029",module:"changshi",prompt:"我国民事诉讼法规定，对公民提起的民事诉讼，由哪一法院管辖？",options:["被告住所地人民法院", "原告住所地人民法院", "行为发生地人民法院", "任意人民法院"],answer:0,explanation:"民事诉讼法规定，对公民提起的民事诉讼，由被告住所地人民法院管辖；被告住所地与经常居住地不一致的，由经常居住地人民法院管辖。"},{id:"cs-4030",module:"changshi",prompt:"我国民事诉讼法规定，当事人对自己提出的主张，有责任提供证据，这被称为？",options:["谁主张，谁举证", "举证责任倒置", "法院依职权调查", "免证事实"],answer:0,explanation:"民事诉讼法规定，当事人对自己提出的主张，有责任提供证据，即谁主张，谁举证；特殊情形下实行举证责任倒置。"},{id:"cs-4031",module:"changshi",prompt:"我国民事诉讼法规定，人民法院适用简易程序审理案件，应当在立案之日起多少个月内审结？",options:["3个月", "6个月", "1个月", "12个月"],answer:0,explanation:"民事诉讼法规定，适用简易程序审理的案件，应当在立案之日起3个月内审结。"},{id:"cs-4032",module:"changshi",prompt:"我国民事诉讼法规定，适用普通程序审理的案件，应当在立案之日起多少个月内审结？",options:["6个月", "3个月", "9个月", "12个月"],answer:0,explanation:"民事诉讼法规定，适用普通程序审理的案件，应当在立案之日起6个月内审结；有特殊情况需要延长的，经批准可以延长。"},{id:"cs-4033",module:"changshi",prompt:"我国刑事诉讼法规定，公诉案件中被告人有罪的举证责任由谁承担？",options:["人民检察院", "人民法院", "被告人", "辩护人"],answer:0,explanation:"刑事诉讼法规定，公诉案件中被告人有罪的举证责任由人民检察院承担；自诉案件中由自诉人承担。"},{id:"cs-4034",module:"changshi",prompt:"我国刑事诉讼法规定的强制措施不包括？",options:["行政拘留", "拘传", "取保候审", "监视居住"],answer:0,explanation:"刑事诉讼的强制措施包括拘传、取保候审、监视居住、拘留和逮捕；行政拘留属于行政处罚。"},{id:"cs-4035",module:"changshi",prompt:"我国刑事诉讼法规定，不服判决的上诉期限为？",options:["10日", "5日", "15日", "30日"],answer:0,explanation:"刑事诉讼法规定，不服判决的上诉和抗诉的期限为10日，不服裁定的上诉和抗诉的期限为5日，从接到判决书、裁定书的第2日起算。"},{id:"cs-4036",module:"changshi",prompt:"我国行政诉讼法规定，行政诉讼的被告是？",options:["作出行政行为的行政机关", "行政行为的相对人", "人民法院", "人民检察院"],answer:0,explanation:"行政诉讼法规定，公民、法人或者其他组织直接向人民法院提起诉讼的，作出行政行为的行政机关是被告。"},{id:"cs-4037",module:"changshi",prompt:"我国民事诉讼法规定，起诉必须符合的条件不包括？",options:["必须经过公证", "原告是与本案有直接利害关系的公民、法人和其他组织", "有明确的被告", "有具体的诉讼请求和事实、理由"],answer:0,explanation:"民事诉讼法规定，起诉必须符合的条件包括原告适格、有明确的被告、有具体的诉讼请求和事实理由、属于人民法院受理范围和管辖；公证不是起诉条件。"},{id:"cs-4038",module:"changshi",prompt:"我国刑事诉讼法规定，对犯罪嫌疑人逮捕后的侦查羁押期限不得超过？",options:["2个月", "1个月", "3个月", "6个月"],answer:0,explanation:"刑事诉讼法规定，对犯罪嫌疑人逮捕后的侦查羁押期限不得超过2个月；案情复杂、期限届满不能终结的案件，可以经批准延长。"},{id:"cs-4039",module:"changshi",prompt:"我国民事诉讼法规定，当事人不服一审判决的，有权在判决书送达之日起多少日内向上一级人民法院提起上诉？",options:["15日", "10日", "30日", "60日"],answer:0,explanation:"民事诉讼法规定，当事人不服地方人民法院第一审判决的，有权在判决书送达之日起15日内向上一级人民法院提起上诉；对裁定不服的为10日。"},{id:"cs-4040",module:"changshi",prompt:"法的社会作用主要体现在维护阶级统治和？",options:["执行社会公共事务", "规范个人道德", "调整国际关系", "发展市场经济"],answer:0,explanation:"法的社会作用主要体现在维护阶级统治和执行社会公共事务两个方面。"},{id:"cs-4041",module:"changshi",prompt:"当代中国法的渊源主要是以宪法为核心的？",options:["各种制定法", "判例法", "习惯法", "国际条约"],answer:0,explanation:"当代中国法的渊源主要是以宪法为核心的各种制定法，包括法律、行政法规、地方性法规、自治条例和单行条例等。"},{id:"cs-4042",module:"changshi",prompt:"我国司法解释由谁作出？",options:["最高人民法院和最高人民检察院", "国务院", "全国人大常委会", "司法部"],answer:0,explanation:"司法解释是国家最高司法机关对法律的解释，由最高人民法院和最高人民检察院作出；全国人大常委会作出立法解释。"},{id:"cs-4043",module:"changshi",prompt:"法不溯及既往原则的例外是？",options:["有利于保护当事人的规定可以溯及既往", "任何情况都可以溯及既往", "新法一律溯及既往", "旧法继续适用"],answer:0,explanation:"法不溯及既往是基本原则，但为了更好保护公民、法人和其他组织的权利和利益而作的特别规定除外，即有利溯及。"},{id:"cs-4044",module:"changshi",prompt:"法律部门的划分标准主要是？",options:["调整对象和调整方法", "制定机关", "生效时间", "文字长短"],answer:0,explanation:"法律部门的划分标准主要是法律所调整的社会关系（调整对象）和调整方法。"},{id:"cs-4045",module:"changshi",prompt:"法律权利与法律义务的关系是？",options:["相互依存、相互转化", "相互对立", "互不相关", "权利优先于义务"],answer:0,explanation:"法律权利与法律义务相互依存、不可分割，没有无义务的权利，也没有无权利的义务。"},{id:"cs-4046",module:"changshi",prompt:"法律面前人人平等原则体现的是？",options:["法的平等价值", "法的秩序价值", "法的效率价值", "法的自由价值"],answer:0,explanation:"法律面前人人平等原则体现的是法的平等价值，即任何人都平等地受法律保护和平等地承担法律义务。"},{id:"cs-4047",module:"changshi",prompt:"法律解释中，对法律条文本身的含义所作的解释称为？",options:["文义解释", "历史解释", "体系解释", "目的解释"],answer:0,explanation:"文义解释是按照法律条文的字面含义和通常理解所作的解释，是最基本的解释方法。"});
(window.YC_CS_BANK=window.YC_CS_BANK||[]).push({id:"cs-4048",module:"changshi",prompt:"根据民法典合同编的规定，承诺生效时会产生什么法律后果？",options:["合同成立", "合同生效", "合同无效", "合同终止"],answer:0,explanation:"民法规定，承诺生效时合同成立，但是法律另有规定或者当事人另有约定的除外。"},{id:"cs-4049",module:"changshi",prompt:"从法理学角度看，法治的核心要求是什么？",options:["规范公权力、保障私权利", "严刑峻法", "依法治民", "以法治国与以德治国完全等同"],answer:0,explanation:"法治的核心是规范和约束公权力，保障公民、法人和其他组织的合法权益，坚持法律面前人人平等。"});
(window.YC_CS_BANK=window.YC_CS_BANK||[]).push({id:"cs-4050",module:"changshi",prompt:"我国宪法规定，中华人民共和国公民的人格尊严不受侵犯，禁止用任何方法对公民进行？",options:["侮辱、诽谤和诬告陷害", "批评教育", "纪律处分", "行政处罚"],answer:0,explanation:"宪法规定，公民的人格尊严不受侵犯，禁止用任何方法对公民进行侮辱、诽谤和诬告陷害。"},{id:"cs-4051",module:"changshi",prompt:"我国宪法规定，中华人民共和国公民的住宅不受侵犯，禁止非法搜查或者非法侵入公民的？",options:["住宅", "店铺", "车辆", "办公室"],answer:0,explanation:"宪法规定，公民的住宅不受侵犯，禁止非法搜查或者非法侵入公民的住宅。"},{id:"cs-4052",module:"changshi",prompt:"我国宪法规定，中华人民共和国主席根据全国人民代表大会的决定和全国人民代表大会常务委员会的决定，行使？",options:["公布法律，任免国务院总理等职权", "审判权", "检察权", "立法权"],answer:0,explanation:"宪法规定，国家主席根据全国人民代表大会的决定和全国人民代表大会常务委员会的决定，公布法律，任免国务院总理、副总理等人员，授予国家的勋章和荣誉称号等。"},{id:"cs-4053",module:"changshi",prompt:"我国宪法规定，最高人民法院是国家的？",options:["最高审判机关", "最高检察机关", "最高行政机关", "最高监察机关"],answer:0,explanation:"宪法规定，中华人民共和国最高人民法院是国家的最高审判机关；最高人民检察院是国家的最高检察机关。"},{id:"cs-4054",module:"changshi",prompt:"我国宪法规定，最高人民检察院对谁负责？",options:["全国人民代表大会和全国人民代表大会常务委员会", "国务院", "最高人民法院", "国家监察委员会"],answer:0,explanation:"宪法规定，最高人民检察院对全国人民代表大会和全国人民代表大会常务委员会负责；地方各级人民检察院对产生它的国家权力机关和上级人民检察院负责。"},{id:"cs-4055",module:"changshi",prompt:"我国宪法规定，全国人民代表大会有权罢免？",options:["国家主席、国务院总理等由它产生的人员", "任何公民", "外国元首", "地方企业负责人"],answer:0,explanation:"宪法规定，全国人民代表大会有权罢免国家主席、副主席，国务院总理、副总理等由它产生的人员。"},{id:"cs-4056",module:"changshi",prompt:"我国宪法规定，中华人民共和国公民在法律面前？",options:["一律平等", "基本平等", "有条件平等", "部分平等"],answer:0,explanation:"宪法规定，中华人民共和国公民在法律面前一律平等；任何公民享有宪法和法律规定的权利，同时必须履行宪法和法律规定的义务。"},{id:"cs-4057",module:"changshi",prompt:"我国宪法规定，由于国家机关和国家工作人员侵犯公民权利而受到损失的人，有依照法律规定？",options:["取得赔偿的权利", "获得补偿的义务", "申请复议的义务", "提起仲裁的权利"],answer:0,explanation:"宪法规定，由于国家机关和国家工作人员侵犯公民权利而受到损失的人，有依照法律规定取得赔偿的权利。"},{id:"cs-4058",module:"changshi",prompt:"所有权是最完整的物权，包括占有、使用、收益和？",options:["处分", "租赁", "抵押", "质押"],answer:0,explanation:"所有权是所有权人对自己的不动产或者动产，依法享有占有、使用、收益和处分的权利；处分权能是所有权的核心权能。"},{id:"cs-4059",module:"changshi",prompt:"善意取得制度的适用条件不包括？",options:["出让人有权处分", "受让人受让时是善意的", "以合理的价格转让", "依法应当登记的已登记，不需要登记的已交付"],answer:0,explanation:"善意取得要求出让人无权处分、受让人善意、以合理价格转让并完成登记或交付；出让人有权处分时不发生善意取得问题。"},{id:"cs-4060",module:"changshi",prompt:"按份共有人对共有的不动产或者动产享有的份额，没有约定或者约定不明确的，按照？",options:["出资额确定", "人数平均确定", "使用情况确定", "登记先后确定"],answer:0,explanation:"民法规定，按份共有人对共有的不动产或者动产享有的份额，没有约定或者约定不明确的，按照出资额确定；不能确定出资额的，视为等额享有。"},{id:"cs-4061",module:"changshi",prompt:"担保物权包括抵押权、质权和？",options:["留置权", "地役权", "居住权", "土地承包经营权"],answer:0,explanation:"担保物权包括抵押权、质权和留置权；地役权、居住权、土地承包经营权属于用益物权。"},{id:"cs-4062",module:"changshi",prompt:"债务人或者第三人有权处分的下列财产可以抵押，但不包括？",options:["土地所有权", "建筑物", "生产设备", "交通运输工具"],answer:0,explanation:"民法规定，土地所有权不得抵押；建筑物、生产设备、交通运输工具等可以抵押。"},{id:"cs-4063",module:"changshi",prompt:"当事人约定债务人履行债务后，定金应当抵作价款或者收回；给付定金的一方不履行债务的，无权请求返还定金，收受定金的一方不履行债务的，应当？",options:["双倍返还定金", "返还定金", "三倍返还定金", "不返还定金"],answer:0,explanation:"民法规定，收受定金的一方不履行债务致使不能实现合同目的的，应当双倍返还定金，即定金罚则。"},{id:"cs-4064",module:"changshi",prompt:"保证的方式包括一般保证和？",options:["连带责任保证", "共同保证", "最高额保证", "定期保证"],answer:0,explanation:"民法规定，保证的方式包括一般保证和连带责任保证；当事人对保证方式没有约定或者约定不明确的，按照一般保证承担保证责任。"},{id:"cs-4065",module:"changshi",prompt:"自然人的姓名权、肖像权、名誉权、荣誉权、隐私权等受到侵害的，有权请求行为人？",options:["承担民事责任", "承担刑事责任", "承担行政责任", "承担政治责任"],answer:0,explanation:"民法规定，人格权受到侵害的，受害人有权请求行为人承担民事责任，包括停止侵害、消除影响、恢复名誉、赔礼道歉、赔偿损失等。"},{id:"cs-4066",module:"changshi",prompt:"结婚年龄，男不得早于多少周岁，女不得早于多少周岁？",options:["男22周岁，女20周岁", "男20周岁，女18周岁", "男25周岁，女23周岁", "男18周岁，女18周岁"],answer:0,explanation:"民法典规定，结婚年龄，男不得早于22周岁，女不得早于20周岁。"},{id:"cs-4067",module:"changshi",prompt:"我国民法典规定的离婚冷静期是自婚姻登记机关收到离婚登记申请之日起多少日内？",options:["30日", "15日", "60日", "90日"],answer:0,explanation:"民法典规定，自婚姻登记机关收到离婚登记申请之日起30日内，任何一方不愿意离婚的，可以向婚姻登记机关撤回离婚登记申请。"},{id:"cs-4068",module:"changshi",prompt:"夫妻在婚姻关系存续期间所得的工资、奖金、劳务报酬等财产属于？",options:["夫妻共同财产", "个人财产", "家庭共有财产", "单位财产"],answer:0,explanation:"民法典规定，夫妻在婚姻关系存续期间所得的工资、奖金、劳务报酬、生产经营收益、投资收益等归夫妻共同所有。"},{id:"cs-4069",module:"changshi",prompt:"违约责任的方式不包括？",options:["行政拘留", "继续履行", "采取补救措施", "赔偿损失"],answer:0,explanation:"违约责任的方式包括继续履行、采取补救措施、赔偿损失、支付违约金、定金罚则等；行政拘留属于行政处罚。"},{id:"cs-4070",module:"changshi",prompt:"当事人既约定违约金，又约定定金的，一方违约时，对方可以选择适用？",options:["违约金或者定金条款", "同时适用违约金和定金", "只能适用定金", "只能适用违约金"],answer:0,explanation:"民法规定，当事人既约定违约金，又约定定金的，一方违约时，对方可以选择适用违约金或者定金条款，不能同时适用。"},{id:"cs-4071",module:"changshi",prompt:"无民事行为能力人或者限制民事行为能力人在幼儿园、学校学习、生活期间受到人身损害的，幼儿园、学校未尽到教育、管理职责的，应当？",options:["承担侵权责任", "不承担责任", "承担全部责任", "由家长承担责任"],answer:0,explanation:"民法典规定，无民事行为能力人在幼儿园、学校学习、生活期间受到人身损害的，幼儿园、学校未尽到教育、管理职责的，应当承担侵权责任。"},{id:"cs-4072",module:"changshi",prompt:"我国刑法规定，已满12周岁不满14周岁的人，犯故意杀人、故意伤害罪，致人死亡或者以特别残忍手段致人重伤造成严重残疾，情节恶劣，经最高人民检察院核准追诉的，应当？",options:["负刑事责任", "不负刑事责任", "负行政责任", "负民事责任"],answer:0,explanation:"刑法修正案（十一）规定，已满12周岁不满14周岁的人犯故意杀人、故意伤害罪，致人死亡等情节恶劣的，经最高人民检察院核准追诉的，应当负刑事责任。"},{id:"cs-4073",module:"changshi",prompt:"为了犯罪，准备工具、制造条件的，是？",options:["犯罪预备", "犯罪未遂", "犯罪中止", "犯罪既遂"],answer:0,explanation:"刑法规定，为了犯罪，准备工具、制造条件的，是犯罪预备；对于预备犯，可以比照既遂犯从轻、减轻处罚或者免除处罚。"},{id:"cs-4074",module:"changshi",prompt:"在共同犯罪中起主要作用的，是？",options:["主犯", "从犯", "胁从犯", "教唆犯"],answer:0,explanation:"刑法规定，在共同犯罪中起主要作用的，是主犯，应当按照其所参与的或者组织、指挥的全部犯罪处罚。"},{id:"cs-4075",module:"changshi",prompt:"在共同犯罪中起次要或者辅助作用的，是？",options:["从犯", "主犯", "首要分子", "实行犯"],answer:0,explanation:"刑法规定，在共同犯罪中起次要或者辅助作用的，是从犯；对于从犯，应当从轻、减轻处罚或者免除处罚。"},{id:"cs-4076",module:"changshi",prompt:"公司、企业、事业单位、机关、团体实施的危害社会的行为，法律规定为单位犯罪的，应当？",options:["负刑事责任", "不负刑事责任", "只追究个人责任", "只追究单位民事责任"],answer:0,explanation:"刑法规定，公司、企业、事业单位、机关、团体实施的危害社会的行为，法律规定为单位犯罪的，应当负刑事责任；对单位判处罚金，并对其直接负责的主管人员和其他直接责任人员判处刑罚。"},{id:"cs-4077",module:"changshi",prompt:"以非法占有为目的，秘密窃取公私财物数额较大或者多次盗窃公私财物的行为，构成？",options:["盗窃罪", "抢劫罪", "诈骗罪", "侵占罪"],answer:0,explanation:"盗窃罪是以非法占有为目的，秘密窃取公私财物数额较大或者多次盗窃、入户盗窃、携带凶器盗窃、扒窃公私财物的行为。"},{id:"cs-4078",module:"changshi",prompt:"以暴力、胁迫或者其他方法抢劫公私财物的，构成？",options:["抢劫罪", "盗窃罪", "抢夺罪", "诈骗罪"],answer:0,explanation:"抢劫罪是以暴力、胁迫或者其他方法抢劫公私财物的行为；抢劫罪侵犯的是财产权和人身权双重客体。"},{id:"cs-4079",module:"changshi",prompt:"国家工作人员利用职务上的便利，侵吞、窃取、骗取或者以其他手段非法占有公共财物的，构成？",options:["贪污罪", "受贿罪", "职务侵占罪", "挪用公款罪"],answer:0,explanation:"贪污罪是国家工作人员利用职务上的便利，侵吞、窃取、骗取或者以其他手段非法占有公共财物的行为。"},{id:"cs-4080",module:"changshi",prompt:"国家工作人员利用职务上的便利，索取他人财物的，或者非法收受他人财物，为他人谋取利益的，构成？",options:["受贿罪", "贪污罪", "行贿罪", "挪用公款罪"],answer:0,explanation:"受贿罪是国家工作人员利用职务上的便利，索取他人财物，或者非法收受他人财物，为他人谋取利益的行为。"},{id:"cs-4081",module:"changshi",prompt:"国家工作人员利用职务上的便利，挪用公款归个人使用，进行非法活动的，或者挪用公款数额较大、进行营利活动的，或者挪用公款数额较大、超过3个月未还的，构成？",options:["挪用公款罪", "贪污罪", "受贿罪", "挪用资金罪"],answer:0,explanation:"挪用公款罪是国家工作人员利用职务上的便利，挪用公款归个人使用，进行非法活动，或者挪用公款数额较大、进行营利活动，或者挪用公款数额较大、超过3个月未还的行为。"},{id:"cs-4082",module:"changshi",prompt:"我国刑法规定，对于犯罪情节轻微不需要判处刑罚的，可以？",options:["免予刑事处罚", "从重处罚", "加重处罚", "判处死刑"],answer:0,explanation:"刑法规定，对于犯罪情节轻微不需要判处刑罚的，可以免予刑事处罚，但是可以根据案件的不同情况予以训诫或者责令具结悔过、赔礼道歉、赔偿损失。"},{id:"cs-4083",module:"changshi",prompt:"我国行政复议法规定，可以申请行政复议的事项不包括？",options:["行政机关的内部奖惩决定", "对行政处罚不服", "对行政强制措施不服", "对行政许可不服"],answer:0,explanation:"行政复议法规定，对行政机关作出的行政处分或者其他人事处理决定不服的，不能申请行政复议，可以依照有关法律、行政法规提出申诉。"},{id:"cs-4084",module:"changshi",prompt:"我国行政复议法规定，对国务院部门的具体行政行为不服的，向谁申请行政复议？",options:["作出该行为的国务院部门", "国务院", "最高人民法院", "本级人民政府"],answer:0,explanation:"行政复议法规定，对国务院部门的具体行政行为不服的，向作出该行为的国务院部门申请行政复议；对行政复议决定不服的，可以向人民法院提起行政诉讼，也可以向国务院申请裁决。"},{id:"cs-4085",module:"changshi",prompt:"我国政府信息公开条例规定，行政机关公开政府信息，应当坚持以公开为常态、不公开为例外，遵循？",options:["公正、公平、合法、便民的原则", "保密优先的原则", "效率优先的原则", "自愿公开的原则"],answer:0,explanation:"政府信息公开条例规定，行政机关公开政府信息，应当坚持以公开为常态、不公开为例外，遵循公正、公平、合法、便民的原则。"},{id:"cs-4086",module:"changshi",prompt:"我国公务员法规定，公务员是指依法履行公职、纳入国家行政编制、由国家财政负担工资福利的？",options:["工作人员", "领导干部", "技术人员", "临时人员"],answer:0,explanation:"公务员法规定，公务员是指依法履行公职、纳入国家行政编制、由国家财政负担工资福利的工作人员。"},{id:"cs-4087",module:"changshi",prompt:"我国公务员法规定，公务员录用采取公开考试、严格考察、平等竞争、择优录取的办法，录用担任一级主任科员以下及其他相当职级层次的公务员，采取的办法是？",options:["公开考试、严格考察、平等竞争、择优录取", "直接任命", "内部推荐", "协商确定"],answer:0,explanation:"公务员法规定，录用公务员应当采取公开考试、严格考察、平等竞争、择优录取的办法。"},{id:"cs-4088",module:"changshi",prompt:"我国公务员法规定，公务员的处分种类不包括？",options:["刑事拘留", "警告", "记过", "撤职"],answer:0,explanation:"公务员的处分种类包括警告、记过、记大过、降级、撤职、开除；刑事拘留是刑事强制措施，不是处分。"},{id:"cs-4089",module:"changshi",prompt:"我国公务员法规定，公务员辞去公职或者退休的，原系领导成员、县处级以上领导职务的公务员在离职多少年内，不得到与原工作业务直接相关的企业任职？",options:["3年", "1年", "2年", "5年"],answer:0,explanation:"公务员法规定，原系领导成员、县处级以上领导职务的公务员在离职3年内，其他公务员在离职2年内，不得到与原工作业务直接相关的企业任职。"},{id:"cs-4090",module:"changshi",prompt:"我国行政强制法规定，行政强制执行的方式不包括？",options:["罚款", "加处罚款或者滞纳金", "划拨存款、汇款", "拍卖查封、扣押的财物"],answer:0,explanation:"行政强制执行的方式包括加处罚款或者滞纳金、划拨存款汇款、拍卖查封扣押的财物等；罚款属于行政处罚。"},{id:"cs-4091",module:"changshi",prompt:"我国行政强制法规定，查封、扣押的期限不得超过？",options:["30日", "15日", "60日", "90日"],answer:0,explanation:"行政强制法规定，查封、扣押的期限不得超过30日；情况复杂的，经行政机关负责人批准可以延长，但是延长期限不得超过30日。"},{id:"cs-4092",module:"changshi",prompt:"我国行政诉讼法规定，人民法院不受理公民、法人或者其他组织对下列事项提起的诉讼，其中包括？",options:["国防、外交等国家行为", "行政处罚", "行政强制措施", "行政许可"],answer:0,explanation:"行政诉讼法规定，国防、外交等国家行为，行政法规、规章或者行政机关制定、发布的具有普遍约束力的决定、命令等，不属于行政诉讼受案范围。"},{id:"cs-4093",module:"changshi",prompt:"我国行政诉讼法规定，行政诉讼中，经复议的案件，复议机关决定维持原行政行为的，作出原行政行为的行政机关和复议机关是？",options:["共同被告", "仅原机关为被告", "仅复议机关为被告", "第三人"],answer:0,explanation:"行政诉讼法规定，经复议的案件，复议机关决定维持原行政行为的，作出原行政行为的行政机关和复议机关是共同被告。"},{id:"cs-4094",module:"changshi",prompt:"我国行政诉讼法规定，行政诉讼的判决类型不包括？",options:["刑事判决", "判决驳回诉讼请求", "判决撤销或者部分撤销", "判决履行职责"],answer:0,explanation:"行政诉讼的判决类型包括驳回诉讼请求、撤销或部分撤销、履行职责、确认违法、变更判决等；刑事判决属于刑事诉讼。"},{id:"cs-4095",module:"changshi",prompt:"我国行政处罚法规定，当事人有权进行陈述和申辩，行政机关必须充分听取当事人的意见，不得因当事人申辩而？",options:["给予更重的处罚", "减轻处罚", "免除处罚", "不予处罚"],answer:0,explanation:"行政处罚法规定，行政机关必须充分听取当事人的意见，对当事人提出的事实、理由和证据应当进行复核；不得因当事人申辩而给予更重的处罚。"},{id:"cs-4096",module:"changshi",prompt:"我国劳动合同法规定，用人单位与劳动者协商一致，可以？",options:["解除劳动合同", "变更劳动合同", "终止劳动合同", "撤销劳动合同"],answer:0,explanation:"劳动合同法规定，用人单位与劳动者协商一致，可以解除劳动合同；协商一致也可以变更劳动合同约定的内容。"},{id:"cs-4097",module:"changshi",prompt:"我国劳动合同法规定，劳动者提前多少日以书面形式通知用人单位，可以解除劳动合同？",options:["30日", "15日", "7日", "60日"],answer:0,explanation:"劳动合同法规定，劳动者提前30日以书面形式通知用人单位，可以解除劳动合同；劳动者在试用期内提前3日通知用人单位，可以解除劳动合同。"},{id:"cs-4098",module:"changshi",prompt:"我国劳动合同法规定，用人单位以暴力、威胁或者非法限制人身自由的手段强迫劳动者劳动的，劳动者可以？",options:["立即解除劳动合同，不需事先告知用人单位", "提前30日通知后解除", "提前3日通知后解除", "不得解除"],answer:0,explanation:"劳动合同法规定，用人单位以暴力、威胁或者非法限制人身自由的手段强迫劳动者劳动的，或者用人单位违章指挥、强令冒险作业危及劳动者人身安全的，劳动者可以立即解除劳动合同，不需事先告知用人单位。"},{id:"cs-4099",module:"changshi",prompt:"我国劳动合同法规定，劳动者在试用期被证明不符合录用条件的，用人单位可以？",options:["解除劳动合同", "延长试用期", "扣发工资", "追究违约责任"],answer:0,explanation:"劳动合同法规定，劳动者在试用期间被证明不符合录用条件的，用人单位可以解除劳动合同。"},{id:"cs-4100",module:"changshi",prompt:"我国劳动合同法规定，劳动者不能胜任工作，经过培训或者调整工作岗位，仍不能胜任工作的，用人单位提前30日以书面形式通知劳动者本人或者额外支付劳动者1个月工资后，可以？",options:["解除劳动合同", "直接辞退", "扣发工资", "追究违约责任"],answer:0,explanation:"劳动合同法规定，劳动者不能胜任工作，经过培训或者调整工作岗位，仍不能胜任工作的，用人单位提前30日以书面形式通知劳动者本人或者额外支付劳动者1个月工资后，可以解除劳动合同。"},{id:"cs-4101",module:"changshi",prompt:"我国劳动合同法规定，连续订立2次固定期限劳动合同，且劳动者没有法定过失性情形的，续订劳动合同的，应当？",options:["订立无固定期限劳动合同", "订立固定期限劳动合同", "终止劳动合同", "订立以完成一定工作任务为期限的劳动合同"],answer:0,explanation:"劳动合同法规定，连续订立2次固定期限劳动合同，且劳动者没有法定过失性情形的，续订劳动合同的，除劳动者提出订立固定期限劳动合同外，应当订立无固定期限劳动合同。"},{id:"cs-4102",module:"changshi",prompt:"我国劳动合同法规定，劳务派遣只能在什么性质的岗位上实施？",options:["临时性、辅助性或者替代性", "长期性、核心性", "管理性、技术性", "全部岗位"],answer:0,explanation:"劳动合同法规定，劳务派遣只能在临时性、辅助性或者替代性的工作岗位上实施。"},{id:"cs-4103",module:"changshi",prompt:"我国劳动合同法规定，劳务派遣单位应当与被派遣劳动者订立几年以上的固定期限劳动合同？",options:["2年以上", "1年以上", "3年以上", "5年以上"],answer:0,explanation:"劳动合同法规定，劳务派遣单位应当与被派遣劳动者订立2年以上的固定期限劳动合同，按月支付劳动报酬；被派遣劳动者在无工作期间，劳务派遣单位应当按照所在地最低工资标准，按月支付报酬。"},{id:"cs-4104",module:"changshi",prompt:"我国劳动合同法规定，非全日制用工，是指以小时计酬为主，劳动者在同一用人单位一般平均每日工作时间不超过？",options:["4小时", "2小时", "6小时", "8小时"],answer:0,explanation:"劳动合同法规定，非全日制用工是指以小时计酬为主，劳动者在同一用人单位一般平均每日工作时间不超过4小时，每周工作时间累计不超过24小时的用工形式。"},{id:"cs-4105",module:"changshi",prompt:"我国劳动合同法规定，非全日制用工劳动报酬结算支付周期最长不得超过？",options:["15日", "7日", "30日", "60日"],answer:0,explanation:"劳动合同法规定，非全日制用工劳动报酬结算支付周期最长不得超过15日；非全日制用工不得约定试用期。"},{id:"cs-4106",module:"changshi",prompt:"我国社会保险法规定，基本养老保险个人账户的资金余额可以？",options:["依法继承", "没收", "归单位所有", "归社保基金"],answer:0,explanation:"社会保险法规定，个人死亡的，个人账户余额可以继承；参加基本养老保险的个人，因病或者非因工死亡的，其遗属可以领取丧葬补助金和抚恤金。"},{id:"cs-4107",module:"changshi",prompt:"我国社会保险法规定，用人单位应当自用工之日起多少日内为其职工向社会保险经办机构申请办理社会保险登记？",options:["30日", "15日", "60日", "90日"],answer:0,explanation:"社会保险法规定，用人单位应当自用工之日起30日内为其职工向社会保险经办机构申请办理社会保险登记。"},{id:"cs-4108",module:"changshi",prompt:"我国反垄断法规定，禁止经营者滥用市场支配地位，具有市场支配地位的经营者不得？",options:["没有正当理由，以不公平的高价销售商品或者以不公平的低价购买商品", "正常定价", "正常促销", "正常竞争"],answer:0,explanation:"反垄断法规定，具有市场支配地位的经营者不得没有正当理由，以不公平的高价销售商品或者以不公平的低价购买商品，不得没有正当理由拒绝交易、限定交易等。"},{id:"cs-4109",module:"changshi",prompt:"我国反垄断法规定，经营者集中达到国务院规定的申报标准的，经营者应当？",options:["事先向国务院反垄断执法机构申报，未申报的不得实施集中", "事后补报", "无需申报", "向法院申报"],answer:0,explanation:"反垄断法规定，经营者集中达到国务院规定的申报标准的，经营者应当事先向国务院反垄断执法机构申报，未申报的不得实施集中。"},{id:"cs-4110",module:"changshi",prompt:"我国价格法规定，经营者进行价格活动，应当遵守法律、法规，执行依法制定的政府指导价、政府定价和法定的价格干预措施、紧急措施，不得有？",options:["不正当价格行为", "正常定价行为", "正常促销行为", "正常竞争行为"],answer:0,explanation:"价格法规定，经营者不得有相互串通操纵市场价格、捏造散布涨价信息、哄抬价格、价格歧视等不正当价格行为。"},{id:"cs-4111",module:"changshi",prompt:"我国广告法规定，广告不得有虚假或者引人误解的内容，不得欺骗、误导消费者，这体现了广告的？",options:["真实性要求", "艺术性要求", "娱乐性要求", "时效性要求"],answer:0,explanation:"广告法规定，广告应当真实、合法，不得含有虚假或者引人误解的内容，不得欺骗、误导消费者。"},{id:"cs-4112",module:"changshi",prompt:"我国广告法规定，药品广告的内容不得含有？",options:["表示功效、安全性的断言或者保证", "药品名称", "生产企业名称", "批准文号"],answer:0,explanation:"广告法规定，药品广告不得含有表示功效、安全性的断言或者保证，不得说明治愈率或者有效率等。"},{id:"cs-4113",module:"changshi",prompt:"我国食品安全法规定，食品生产经营者对其生产经营的食品安全负责，食品安全的第一责任人是？",options:["食品生产经营者", "监管部门", "消费者", "检验机构"],answer:0,explanation:"食品安全法规定，食品生产经营者对其生产经营食品的安全负责，是食品安全的第一责任人。"},{id:"cs-4114",module:"changshi",prompt:"我国食品安全法规定，禁止生产经营的食品不包括？",options:["符合食品安全标准的食品", "用非食品原料生产的食品", "腐败变质的食品", "超过保质期的食品"],answer:0,explanation:"食品安全法规定，禁止生产经营用非食品原料生产的食品、腐败变质、油脂酸败、霉变生虫、污秽不洁、混有异物、掺假掺杂或者感官性状异常的食品、超过保质期的食品等。"},{id:"cs-4115",module:"changshi",prompt:"我国消费者权益保护法规定，经营者不得以格式条款、通知、声明、店堂告示等方式，作出排除或者限制消费者权利、减轻或者免除经营者责任、加重消费者责任等对消费者不公平、不合理的规定，格式条款含有该内容的，其内容？",options:["无效", "有效", "可撤销", "效力待定"],answer:0,explanation:"消费者权益保护法规定，经营者以格式条款等方式作出的对消费者不公平、不合理的规定，其内容无效。"},{id:"cs-4116",module:"changshi",prompt:"我国消费者权益保护法规定，消费者协会的性质是？",options:["依法成立的对商品和服务进行社会监督的保护消费者合法权益的社会组织", "行政机关", "司法机关", "企业"],answer:0,explanation:"消费者权益保护法规定，消费者协会是依法成立的对商品和服务进行社会监督的保护消费者合法权益的社会组织。"},{id:"cs-4117",module:"changshi",prompt:"我国税收征收管理法规定，纳税人未按照规定期限缴纳税款的，税务机关除责令限期缴纳外，从滞纳税款之日起，按日加收滞纳税款多少的滞纳金？",options:["万分之五", "千分之五", "百分之一", "万分之十"],answer:0,explanation:"税收征收管理法规定，纳税人未按照规定期限缴纳税款的，税务机关除责令限期缴纳外，从滞纳税款之日起，按日加收滞纳税款万分之五的滞纳金。"},{id:"cs-4118",module:"changshi",prompt:"我国反不正当竞争法规定，经营者不得对其商品的性能、功能、质量、销售状况、用户评价、曾获荣誉等作？",options:["虚假或者引人误解的商业宣传，欺骗、误导消费者", "真实宣传", "正常宣传", "合理宣传"],answer:0,explanation:"反不正当竞争法规定，经营者不得对其商品的性能、功能、质量、销售状况、用户评价、曾获荣誉等作虚假或者引人误解的商业宣传，欺骗、误导消费者。"},{id:"cs-4119",module:"changshi",prompt:"我国电子商务法规定，电子商务平台经营者知道或者应当知道平台内经营者销售的商品或者提供的服务不符合保障人身、财产安全的要求，未采取必要措施的，依法与该平台内经营者承担？",options:["连带责任", "按份责任", "补充责任", "无责任"],answer:0,explanation:"电子商务法规定，电子商务平台经营者知道或者应当知道平台内经营者销售的商品或者提供的服务不符合保障人身、财产安全的要求，未采取必要措施的，依法与该平台内经营者承担连带责任。"},{id:"cs-4120",module:"changshi",prompt:"我国民事诉讼法规定，审判人员、书记员、翻译人员、鉴定人、勘验人有法定情形的，当事人有权申请其？",options:["回避", "作证", "出庭", "调解"],answer:0,explanation:"民事诉讼法规定，审判人员、书记员、翻译人员、鉴定人、勘验人有法定情形的，当事人有权用口头或者书面方式申请他们回避。"},{id:"cs-4121",module:"changshi",prompt:"我国民事诉讼法规定，人民法院对于可能因当事人一方的行为或者其他原因，使判决难以执行或者造成当事人其他损害的案件，根据对方当事人的申请，可以裁定对其财产进行？",options:["保全", "先予执行", "调解", "仲裁"],answer:0,explanation:"民事诉讼法规定，人民法院对于可能因当事人一方的行为或者其他原因，使判决难以执行或者造成当事人其他损害的案件，根据对方当事人的申请，可以裁定对其财产进行保全、责令其作出一定行为或者禁止其作出一定行为。"},{id:"cs-4122",module:"changshi",prompt:"我国民事诉讼法规定，人民法院审理民事案件，根据当事人自愿的原则，在事实清楚的基础上，分清是非，进行？",options:["调解", "仲裁", "公证", "行政裁决"],answer:0,explanation:"民事诉讼法规定，人民法院审理民事案件，根据当事人自愿的原则，在事实清楚的基础上，分清是非，进行调解；调解不成的，应当及时判决。"},{id:"cs-4123",module:"changshi",prompt:"我国民事诉讼法规定，当事人对已经发生法律效力的判决、裁定，认为有错误的，可以向上一级人民法院申请？",options:["再审", "上诉", "仲裁", "复议"],answer:0,explanation:"民事诉讼法规定，当事人对已经发生法律效力的判决、裁定，认为有错误的，可以向上一级人民法院申请再审；当事人申请再审的，不停止判决、裁定的执行。"},{id:"cs-4124",module:"changshi",prompt:"我国刑事诉讼法规定的证据种类不包括？",options:["新闻报道", "物证", "书证", "证人证言"],answer:0,explanation:"刑事诉讼的证据种类包括物证、书证、证人证言、被害人陈述、犯罪嫌疑人供述和辩解、鉴定意见、勘验检查笔录、视听资料、电子数据等；新闻报道不是法定证据种类。"},{id:"cs-4125",module:"changshi",prompt:"我国刑事诉讼法规定，犯罪嫌疑人、被告人除自己行使辩护权以外，还可以委托？",options:["1至2人作为辩护人", "3至5人作为辩护人", "1人作为辩护人", "任意人数作为辩护人"],answer:0,explanation:"刑事诉讼法规定，犯罪嫌疑人、被告人除自己行使辩护权以外，还可以委托1至2人作为辩护人。"},{id:"cs-4126",module:"changshi",prompt:"我国刑事诉讼法规定，下列人员可以被委托为辩护人的是？",options:["律师", "正在被执行刑罚的人", "被依法限制人身自由的人", "无行为能力人"],answer:0,explanation:"刑事诉讼法规定，律师、人民团体或者犯罪嫌疑人所在单位推荐的人、监护人和亲友等可以被委托为辩护人；正在被执行刑罚或者依法被剥夺、限制人身自由的人不得担任辩护人。"},{id:"cs-4127",module:"changshi",prompt:"我国刑事诉讼法规定，人民检察院认为犯罪嫌疑人的犯罪事实已经查清，证据确实、充分，依法应当追究刑事责任的，应当作出？",options:["起诉决定", "不起诉决定", "撤案决定", "缓刑决定"],answer:0,explanation:"刑事诉讼法规定，人民检察院认为犯罪嫌疑人的犯罪事实已经查清，证据确实、充分，依法应当追究刑事责任的，应当作出起诉决定，按照审判管辖的规定，向人民法院提起公诉。"},{id:"cs-4128",module:"changshi",prompt:"我国刑事诉讼法规定，对于犯罪情节轻微，依照刑法规定不需要判处刑罚或者免除刑罚的，人民检察院可以作出？",options:["不起诉决定", "起诉决定", "逮捕决定", "拘留决定"],answer:0,explanation:"刑事诉讼法规定，对于犯罪情节轻微，依照刑法规定不需要判处刑罚或者免除刑罚的，人民检察院可以作出不起诉决定。"},{id:"cs-4129",module:"changshi",prompt:"我国行政诉讼法规定，人民法院审理行政案件，不适用？",options:["调解", "判决", "裁定", "开庭审理"],answer:0,explanation:"行政诉讼法规定，人民法院审理行政案件，不适用调解；但是行政赔偿、补偿以及行政机关行使法律、法规规定的自由裁量权的案件可以调解。"},{id:"cs-4130",module:"changshi",prompt:"我国行政诉讼法规定，行政行为有实施主体不具有行政主体资格等重大且明显违法情形的，人民法院判决？",options:["确认无效", "确认有效", "维持", "变更"],answer:0,explanation:"行政诉讼法规定，行政行为有实施主体不具有行政主体资格或者没有依据等重大且明显违法情形，原告申请确认行政行为无效的，人民法院判决确认无效。"},{id:"cs-4131",module:"changshi",prompt:"我国民事诉讼法规定，第二审人民法院对上诉案件，应当组成合议庭，开庭审理；经过阅卷、调查和询问当事人，对没有提出新的事实、证据或者理由，合议庭认为不需要开庭审理的，可以？",options:["不开庭审理", "直接判决", "发回重审", "中止审理"],answer:0,explanation:"民事诉讼法规定，第二审人民法院对上诉案件，应当组成合议庭，开庭审理；对没有提出新的事实、证据或者理由，合议庭认为不需要开庭审理的，可以不开庭审理。"},{id:"cs-4132",module:"changshi",prompt:"法的效力范围包括法的空间效力、时间效力和？",options:["对人的效力", "对物的效力", "对事的效力", "对国的效力"],answer:0,explanation:"法的效力范围包括法的空间效力、时间效力和对人的效力三个方面。"},{id:"cs-4133",module:"changshi",prompt:"法律监督按照监督的主体可以分为？",options:["国家监督和社会监督", "内部监督和外部监督", "事前监督和事后监督", "直接监督和间接监督"],answer:0,explanation:"法律监督按照监督的主体可以分为国家监督和社会监督；国家监督包括权力机关、行政机关、监察机关、司法机关的监督等。"},{id:"cs-4134",module:"changshi",prompt:"法律关系的内容是指？",options:["法律权利和法律义务", "法律主体和法律客体", "法律事实和法律行为", "法律规范和法律条文"],answer:0,explanation:"法律关系的内容是指法律关系主体之间的法律权利和法律义务。"},{id:"cs-4135",module:"changshi",prompt:"法律事实中的事件是指？",options:["不以人的意志为转移的客观事实", "人的有意识的活动", "合同的签订", "判决的作出"],answer:0,explanation:"法律事实中的事件是不以人的意志为转移的客观事实，如出生、死亡、自然灾害等；法律行为是人的有意识的活动。"},{id:"cs-4136",module:"changshi",prompt:"法律责任产生的原因不包括？",options:["道德约束", "违法行为", "违约行为", "法律规定"],answer:0,explanation:"法律责任产生的原因包括违法行为、违约行为和法律规定等；道德约束不是法律责任产生的原因。"},{id:"cs-4137",module:"changshi",prompt:"法律制裁与法律责任的区别在于？",options:["法律制裁是承担法律责任的特定方式", "两者完全相同", "法律制裁先于法律责任", "法律责任是法律制裁的结果"],answer:0,explanation:"法律责任是行为人因违法行为而承担的不利后果，法律制裁是国家对违法者实施的惩罚性强制措施，是承担法律责任的特定方式。"},{id:"cs-4138",module:"changshi",prompt:"立法程序一般包括法律案的提出、审议、表决和？",options:["公布", "起草", "调研", "论证"],answer:0,explanation:"立法程序一般包括法律案的提出、审议、表决和公布四个环节。"});
(window.YC_CS_BANK=window.YC_CS_BANK||[]).push({id:"cs-4139",module:"changshi",prompt:"根据我国刑法的规定，共同犯罪是指什么情形？",options:["二人以上共同故意犯罪", "二人以上共同过失犯罪", "一人多次犯罪", "多人同时在场"],answer:0,explanation:"刑法规定，共同犯罪是指二人以上共同故意犯罪；二人以上共同过失犯罪，不以共同犯罪论处。"});
(window.YC_CS_BANK=window.YC_CS_BANK||[]).push({id:"cs-4140",module:"changshi",prompt:"我国宪法规定，全国人民代表大会代表和地方各级人民代表大会代表的选举，由谁主持？",options:["全国人民代表大会常务委员会和地方各级人民代表大会常务委员会", "国务院", "人民法院", "监察委员会"],answer:0,explanation:"选举法规定，全国人民代表大会常务委员会主持全国人民代表大会代表的选举；省、自治区、直辖市、设区的市、自治州的人大常委会主持本级人大代表的选举。"},{id:"cs-4141",module:"changshi",prompt:"我国宪法规定，不设区的市、市辖区、县、自治县、乡、民族乡、镇的人民代表大会代表，由选民？",options:["直接选举", "间接选举", "任命产生", "推荐产生"],answer:0,explanation:"宪法规定，全国人民代表大会代表，省、自治区、直辖市、设区的市、自治州的人民代表大会代表由下一级人民代表大会选举；不设区的市、市辖区、县、自治县、乡、民族乡、镇的人民代表大会代表由选民直接选举。"},{id:"cs-4142",module:"changshi",prompt:"我国宪法规定，全国人民代表大会代表受谁的监督？",options:["原选举单位", "国务院", "最高人民法院", "监察委员会"],answer:0,explanation:"宪法规定，全国人民代表大会代表受原选举单位的监督；原选举单位有权依照法律规定的程序罢免本单位选出的代表。"},{id:"cs-4143",module:"changshi",prompt:"我国宪法规定，各民族都有使用和发展自己的语言文字的自由，都有保持或者改革自己的风俗习惯的？",options:["自由", "义务", "责任", "权利限制"],answer:0,explanation:"宪法规定，各民族都有使用和发展自己的语言文字的自由，都有保持或者改革自己的风俗习惯的自由。"},{id:"cs-4144",module:"changshi",prompt:"我国宪法规定，民族自治地方的自治机关是自治区、自治州、自治县的？",options:["人民代表大会和人民政府", "人民法院", "监察委员会", "政协"],answer:0,explanation:"宪法规定，民族自治地方的自治机关是自治区、自治州、自治县的人民代表大会和人民政府。"},{id:"cs-4145",module:"changshi",prompt:"我国宪法规定，中华人民共和国的首都是？",options:["北京", "上海", "南京", "西安"],answer:0,explanation:"宪法规定，中华人民共和国的首都是北京。"},{id:"cs-4146",module:"changshi",prompt:"我国宪法规定，特别行政区的制度由谁以法律规定？",options:["全国人民代表大会", "国务院", "最高人民法院", "特别行政区自行决定"],answer:0,explanation:"宪法规定，国家在必要时得设立特别行政区；在特别行政区内实行的制度按照具体情况由全国人民代表大会以法律规定。"},{id:"cs-4147",module:"changshi",prompt:"我国宪法规定，中华人民共和国公民有受教育的权利和义务，国家培养青年、少年、儿童在品德、智力、体质等方面？",options:["全面发展", "单一发展", "自由发展", "局部发展"],answer:0,explanation:"宪法规定，公民有受教育的权利和义务；国家培养青年、少年、儿童在品德、智力、体质等方面全面发展。"},{id:"cs-4148",module:"changshi",prompt:"我国宪法规定，全国人民代表大会常务委员会有权解释？",options:["宪法和法律", "行政法规", "地方性法规", "部门规章"],answer:0,explanation:"宪法规定，全国人民代表大会常务委员会有权解释宪法和法律，监督宪法的实施。"},{id:"cs-4149",module:"changshi",prompt:"我国宪法规定，中华人民共和国公民的通信自由和通信秘密受法律的保护，属于公民的？",options:["基本权利", "基本义务", "政治权利", "经济权利"],answer:0,explanation:"宪法规定，公民的通信自由和通信秘密受法律保护，这是公民的基本权利之一。"},{id:"cs-4150",module:"changshi",prompt:"我国宪法规定，任何公民，非经人民检察院批准或者决定或者人民法院决定，并由公安机关执行，不受？",options:["逮捕", "传唤", "询问", "约谈"],answer:0,explanation:"宪法规定，任何公民，非经人民检察院批准或者决定或者人民法院决定，并由公安机关执行，不受逮捕。"},{id:"cs-4151",module:"changshi",prompt:"要约邀请是希望他人向自己发出要约的表示，下列属于要约邀请的是？",options:["拍卖公告、招标公告、招股说明书、债券募集办法、基金招募说明书、商业广告和宣传、寄送的价目表等", "已确定的合同条款", "承诺通知", "仲裁条款"],answer:0,explanation:"民法规定，拍卖公告、招标公告、招股说明书、债券募集办法、基金招募说明书、商业广告和宣传、寄送的价目表等为要约邀请；商业广告和宣传的内容符合要约条件的，构成要约。"},{id:"cs-4152",module:"changshi",prompt:"格式条款是当事人为了重复使用而预先拟定，并在订立合同时未与对方协商的条款，提供格式条款的一方应当遵循公平原则确定当事人之间的权利和义务，并采取合理的方式提示对方注意？",options:["免除或者减轻其责任等与对方有重大利害关系的条款", "全部条款", "无关条款", "次要条款"],answer:0,explanation:"民法规定，提供格式条款的一方应当遵循公平原则确定当事人之间的权利和义务，并采取合理的方式提示对方注意免除或者减轻其责任等与对方有重大利害关系的条款。"},{id:"cs-4153",module:"changshi",prompt:"标的物毁损、灭失的风险，交付之前由谁承担，交付之后由谁承担？",options:["交付之前由出卖人承担，交付之后由买受人承担", "全部由出卖人承担", "全部由买受人承担", "由法院决定"],answer:0,explanation:"民法规定，标的物毁损、灭失的风险，在标的物交付之前由出卖人承担，交付之后由买受人承担，但是法律另有规定或者当事人另有约定的除外。"},{id:"cs-4154",module:"changshi",prompt:"借款合同对支付利息约定不明确，当事人不能达成补充协议的，利息按照？",options:["当地或者当事人的交易方式、交易习惯、市场利率等因素确定", "出借人主张确定", "借款人主张确定", "视为无利息"],answer:0,explanation:"民法规定，借款合同对支付利息约定不明确，当事人不能达成补充协议的，按照当地或者当事人的交易方式、交易习惯、市场利率等因素确定利息；自然人之间借款的，视为没有利息。"},{id:"cs-4155",module:"changshi",prompt:"从建筑物中抛掷物品或者从建筑物上坠落的物品造成他人损害的，由侵权人依法承担侵权责任；经调查难以确定具体侵权人的，除能够证明自己不是侵权人的外，由可能加害的建筑物使用人？",options:["给予补偿", "不承担责任", "承担全部责任", "承担刑事责任"],answer:0,explanation:"民法典规定，从建筑物中抛掷物品或者从建筑物上坠落的物品造成他人损害的，经调查难以确定具体侵权人的，除能够证明自己不是侵权人的外，由可能加害的建筑物使用人给予补偿。"},{id:"cs-4156",module:"changshi",prompt:"网络用户利用网络服务实施侵权行为，权利人有权通知网络服务提供者采取删除、屏蔽、断开链接等必要措施，这被称为？",options:["通知规则", "公告规则", "公示规则", "备案规则"],answer:0,explanation:"民法典规定，网络用户利用网络服务实施侵权行为，权利人有权通知网络服务提供者采取删除、屏蔽、断开链接等必要措施；未及时采取必要措施的，对损害的扩大部分与该网络用户承担连带责任。"},{id:"cs-4157",module:"changshi",prompt:"因产品存在缺陷造成他人损害的，由谁承担侵权责任？",options:["生产者", "销售者", "运输者", "仓储者"],answer:0,explanation:"民法典规定，因产品存在缺陷造成他人损害的，生产者应当承担侵权责任；因销售者的过错使产品存在缺陷的，由销售者承担侵权责任。"},{id:"cs-4158",module:"changshi",prompt:"患者在诊疗活动中受到损害，医疗机构或者其医务人员有过错的，由谁承担赔偿责任？",options:["医疗机构", "医务人员个人", "保险公司", "患者本人"],answer:0,explanation:"民法典规定，患者在诊疗活动中受到损害，医疗机构或者其医务人员有过错的，由医疗机构承担赔偿责任。"},{id:"cs-4159",module:"changshi",prompt:"业主对建筑物内的住宅、经营性用房等专有部分享有所有权，对专有部分以外的共有部分享有？",options:["共有和共同管理的权利", "单独所有权", "使用权", "处分权"],answer:0,explanation:"民法典规定，业主对建筑物内的住宅、经营性用房等专有部分享有所有权，对专有部分以外的共有部分享有共有和共同管理的权利。"},{id:"cs-4160",module:"changshi",prompt:"不动产的相邻权利人应当按照有利生产、方便生活、团结互助、公平合理的原则，正确处理？",options:["相邻关系", "合同关系", "劳动关系", "婚姻关系"],answer:0,explanation:"民法典规定，不动产的相邻权利人应当按照有利生产、方便生活、团结互助、公平合理的原则，正确处理相邻关系。"},{id:"cs-4161",module:"changshi",prompt:"居住权是用益物权的一种，居住权自何时设立？",options:["居住权合同生效并办理登记时", "合同签订时", "口头约定时", "实际入住时"],answer:0,explanation:"民法典规定，设立居住权的，应当向登记机构申请居住权登记，居住权自登记时设立；居住权无偿设立，不得转让、继承。"},{id:"cs-4162",module:"changshi",prompt:"当事人约定由债务人向第三人履行债务的，债务人未向第三人履行债务或者履行债务不符合约定的，应当向谁承担违约责任？",options:["债权人", "第三人", "法院", "担保人"],answer:0,explanation:"民法规定，当事人约定由债务人向第三人履行债务的，债务人未向第三人履行债务或者履行债务不符合约定的，应当向债权人承担违约责任。"},{id:"cs-4163",module:"changshi",prompt:"合同解除后，尚未履行的，终止履行；已经履行的，根据履行情况和合同性质，当事人可以请求恢复原状或者采取其他补救措施，并有权请求？",options:["赔偿损失", "加倍赔偿", "惩罚性赔偿", "精神赔偿"],answer:0,explanation:"民法规定，合同解除后，尚未履行的，终止履行；已经履行的，当事人可以请求恢复原状或者采取其他补救措施，并有权请求赔偿损失。"},{id:"cs-4164",module:"changshi",prompt:"限制民事行为能力人订立的纯获利益的合同效力是？",options:["有效", "无效", "效力待定", "可撤销"],answer:0,explanation:"民法规定，限制民事行为能力人订立的纯获利益的合同或者与其年龄、智力、精神健康状况相适应的合同，有效；其他合同须经法定代理人同意或者追认。"},{id:"cs-4165",module:"changshi",prompt:"以非法占有为目的，用虚构事实或者隐瞒真相的方法，骗取公私财物数额较大的行为，构成？",options:["诈骗罪", "盗窃罪", "抢劫罪", "侵占罪"],answer:0,explanation:"诈骗罪是以非法占有为目的，用虚构事实或者隐瞒真相的方法，骗取公私财物数额较大的行为。"},{id:"cs-4166",module:"changshi",prompt:"以非法占有为目的，在签订、履行合同过程中，骗取对方当事人财物数额较大的行为，构成？",options:["合同诈骗罪", "诈骗罪", "侵占罪", "盗窃罪"],answer:0,explanation:"合同诈骗罪是以非法占有为目的，在签订、履行合同过程中，骗取对方当事人财物数额较大的行为；合同诈骗罪与诈骗罪是特殊与一般的关系。"},{id:"cs-4167",module:"changshi",prompt:"以非法占有为目的，使用诈骗方法非法集资，数额较大的行为，构成？",options:["集资诈骗罪", "非法吸收公众存款罪", "合同诈骗罪", "诈骗罪"],answer:0,explanation:"集资诈骗罪是以非法占有为目的，使用诈骗方法非法集资，数额较大的行为；非法吸收公众存款罪不以非法占有为目的。"},{id:"cs-4168",module:"changshi",prompt:"在道路上驾驶机动车，追逐竞驶，情节恶劣的，或者醉酒驾驶机动车的，构成？",options:["危险驾驶罪", "交通肇事罪", "以危险方法危害公共安全罪", "故意伤害罪"],answer:0,explanation:"危险驾驶罪是在道路上驾驶机动车追逐竞驶情节恶劣、醉酒驾驶机动车、从事校车业务或旅客运输严重超员超速、违规运输危险化学品危及公共安全的行为。"},{id:"cs-4169",module:"changshi",prompt:"违反交通运输管理法规，因而发生重大事故，致人重伤、死亡或者使公私财产遭受重大损失的，构成？",options:["交通肇事罪", "危险驾驶罪", "故意杀人罪", "过失致人死亡罪"],answer:0,explanation:"交通肇事罪是违反交通运输管理法规，因而发生重大事故，致人重伤、死亡或者使公私财产遭受重大损失的行为。"},{id:"cs-4170",module:"changshi",prompt:"故意伤害他人身体的，处3年以下有期徒刑、拘役或者管制；致人重伤的，处？",options:["3年以上10年以下有期徒刑", "10年以上有期徒刑", "死刑", "无期徒刑"],answer:0,explanation:"刑法规定，故意伤害致人重伤的，处3年以上10年以下有期徒刑；致人死亡或者以特别残忍手段致人重伤造成严重残疾的，处10年以上有期徒刑、无期徒刑或者死刑。"},{id:"cs-4171",module:"changshi",prompt:"故意杀人的，处死刑、无期徒刑或者？",options:["10年以上有期徒刑", "3年以上10年以下有期徒刑", "拘役", "管制"],answer:0,explanation:"刑法规定，故意杀人的，处死刑、无期徒刑或者10年以上有期徒刑；情节较轻的，处3年以上10年以下有期徒刑。"},{id:"cs-4172",module:"changshi",prompt:"以勒索财物为目的绑架他人的，或者绑架他人作为人质的，构成？",options:["绑架罪", "非法拘禁罪", "敲诈勒索罪", "拐卖妇女儿童罪"],answer:0,explanation:"绑架罪是以勒索财物为目的绑架他人的，或者绑架他人作为人质的行为。"},{id:"cs-4173",module:"changshi",prompt:"非法拘禁他人或者以其他方法非法剥夺他人人身自由的，构成？",options:["非法拘禁罪", "绑架罪", "拐卖妇女儿童罪", "故意伤害罪"],answer:0,explanation:"非法拘禁罪是非法拘禁他人或者以其他方法非法剥夺他人人身自由的行为；具有殴打、侮辱情节的，从重处罚。"},{id:"cs-4174",module:"changshi",prompt:"敲诈勒索公私财物，数额较大或者多次敲诈勒索的，构成？",options:["敲诈勒索罪", "诈骗罪", "抢劫罪", "盗窃罪"],answer:0,explanation:"敲诈勒索罪是以非法占有为目的，对被害人使用威胁或者要挟的方法，强行索要公私财物，数额较大或者多次敲诈勒索的行为。"},{id:"cs-4175",module:"changshi",prompt:"我国刑法规定，犯罪分子具有刑法规定的从重处罚、从轻处罚情节的，应当在？",options:["法定刑的限度以内判处刑罚", "法定刑以外判处刑罚", "加重处罚", "减轻处罚"],answer:0,explanation:"刑法规定，犯罪分子具有从重处罚、从轻处罚情节的，应当在法定刑的限度以内判处刑罚；具有减轻处罚情节的，应当在法定刑以下判处刑罚。"},{id:"cs-4176",module:"changshi",prompt:"我国刑法规定，法定最高刑为10年以上有期徒刑的犯罪，追诉期限为？",options:["15年", "10年", "20年", "5年"],answer:0,explanation:"刑法规定，法定最高刑为10年以上有期徒刑的，经过15年不再追诉；法定最高刑为无期徒刑、死刑的，经过20年。"},{id:"cs-4177",module:"changshi",prompt:"我国刑法规定，在人民检察院、公安机关、国家安全机关立案侦查或者在人民法院受理案件以后，逃避侦查或者审判的，追诉期限？",options:["不受限制", "缩短一半", "延长一倍", "重新计算"],answer:0,explanation:"刑法规定，在司法机关立案侦查或者受理案件以后，逃避侦查或者审判的，不受追诉期限的限制；被害人在追诉期限内提出控告，司法机关应当立案而不予立案的，也不受追诉期限的限制。"},{id:"cs-4178",module:"changshi",prompt:"我国刑法规定，被判处无期徒刑的犯罪分子，实际执行多少年以上，可以假释？",options:["13年", "10年", "15年", "20年"],answer:0,explanation:"刑法规定，被判处无期徒刑的犯罪分子，实际执行13年以上，认真遵守监规、接受教育改造，确有悔改表现，没有再犯罪的危险的，可以假释。"},{id:"cs-4179",module:"changshi",prompt:"我国刑法规定，对于累犯和因故意杀人、强奸、抢劫、绑架、放火、爆炸、投放危险物质或者有组织的暴力性犯罪被判处10年以上有期徒刑、无期徒刑的犯罪分子，？",options:["不得假释", "可以假释", "应当假释", "减刑后假释"],answer:0,explanation:"刑法规定，对于累犯和因故意杀人、强奸、抢劫、绑架、放火、爆炸、投放危险物质或者有组织的暴力性犯罪被判处10年以上有期徒刑、无期徒刑的犯罪分子，不得假释。"},{id:"cs-4180",module:"changshi",prompt:"我国行政许可法规定，法律、法规、规章规定实施行政许可应当听证的事项，或者行政机关认为需要听证的其他涉及公共利益的重大行政许可事项，行政机关应当？",options:["向社会公告，并举行听证", "内部决定", "秘密进行", "延期处理"],answer:0,explanation:"行政许可法规定，法律、法规、规章规定实施行政许可应当听证的事项，或者行政机关认为需要听证的其他涉及公共利益的重大行政许可事项，行政机关应当向社会公告，并举行听证。"},{id:"cs-4181",module:"changshi",prompt:"我国行政许可法规定，被许可人要求变更行政许可事项的，应当向作出行政许可决定的行政机关提出申请，行政机关应当依照法定程序审查，？",options:["符合法定条件、标准的，依法办理变更手续", "一律不予变更", "一律变更", "报上级批准"],answer:0,explanation:"行政许可法规定，被许可人要求变更行政许可事项的，应当向作出行政许可决定的行政机关提出申请；符合法定条件、标准的，行政机关应当依法办理变更手续。"},{id:"cs-4182",module:"changshi",prompt:"我国行政处罚法规定，违法事实确凿并有法定依据，对公民处以200元以下、对法人或者其他组织处以3000元以下罚款或者警告的行政处罚的，可以适用？",options:["简易程序，当场作出行政处罚决定", "一般程序", "听证程序", "刑事程序"],answer:0,explanation:"行政处罚法规定，违法事实确凿并有法定依据，对公民处以200元以下、对法人或者其他组织处以3000元以下罚款或者警告的行政处罚的，可以当场作出行政处罚决定，即简易程序。"},{id:"cs-4183",module:"changshi",prompt:"我国行政处罚法规定，行政机关作出较大数额罚款、没收较大数额违法所得等行政处罚决定之前，应当告知当事人有要求？",options:["听证的权利", "复议的权利", "上诉的权利", "申诉的权利"],answer:0,explanation:"行政处罚法规定，行政机关拟作出较大数额罚款、没收较大数额违法所得、降低资质等级、吊销许可证件、责令停产停业、责令关闭、限制从业等行政处罚决定之前，应当告知当事人有要求听证的权利。"},{id:"cs-4184",module:"changshi",prompt:"我国行政复议法规定，对县级以上地方各级人民政府工作部门的具体行政行为不服的，由申请人选择，可以向该部门的本级人民政府申请行政复议，也可以向？",options:["上一级主管部门申请行政复议", "国务院申请行政复议", "人民法院申请行政复议", "监察委员会申请行政复议"],answer:0,explanation:"行政复议法规定，对县级以上地方各级人民政府工作部门的具体行政行为不服的，可以向该部门的本级人民政府申请行政复议，也可以向上一级主管部门申请行政复议。"},{id:"cs-4185",module:"changshi",prompt:"我国行政复议法规定，行政复议决定书一经送达，即发生？",options:["法律效力", "强制执行力", "既判力", "公示力"],answer:0,explanation:"行政复议法规定，行政复议决定书一经送达，即发生法律效力；申请人逾期不起诉又不履行行政复议决定的，行政机关可以依法强制执行或者申请人民法院强制执行。"},{id:"cs-4186",module:"changshi",prompt:"我国国家赔偿法规定，侵犯公民人身自由的，每日赔偿金按照？",options:["国家上年度职工日平均工资计算", "当地最低工资计算", "受害人实际收入计算", "全国人均收入计算"],answer:0,explanation:"国家赔偿法规定，侵犯公民人身自由的，每日赔偿金按照国家上年度职工日平均工资计算。"},{id:"cs-4187",module:"changshi",prompt:"我国国家赔偿法规定，赔偿义务机关应当自收到申请之日起多少个月内作出赔偿决定？",options:["2个月", "1个月", "3个月", "6个月"],answer:0,explanation:"国家赔偿法规定，赔偿义务机关应当自收到申请之日起2个月内作出是否赔偿的决定；逾期未作决定的，赔偿请求人可以申请复议或者提起诉讼。"},{id:"cs-4188",module:"changshi",prompt:"我国政府信息公开条例规定，行政机关不能当场答复的，应当自收到申请之日起多少个工作日内予以答复？",options:["20个", "10个", "15个", "30个"],answer:0,explanation:"政府信息公开条例规定，行政机关收到政府信息公开申请，能够当场答复的，应当当场答复；不能当场答复的，应当自收到申请之日起20个工作日内予以答复；需要延长的，延长不超过20个工作日。"},{id:"cs-4189",module:"changshi",prompt:"我国公务员法规定，公务员的考核分为平时考核、专项考核和？",options:["定期考核", "年度考核", "月度考核", "季度考核"],answer:0,explanation:"公务员法规定，公务员的考核分为平时考核、专项考核和定期考核等方式；定期考核以年度考核为主。"},{id:"cs-4190",module:"changshi",prompt:"我国公务员法规定，公务员定期考核的结果分为？",options:["优秀、称职、基本称职和不称职", "合格和不合格", "优秀和合格", "称职和不称职"],answer:0,explanation:"公务员法规定，公务员定期考核的结果分为优秀、称职、基本称职和不称职四个等次。"},{id:"cs-4191",module:"changshi",prompt:"我国行政诉讼法规定，对限制人身自由的行政强制措施不服提起的诉讼，由被告所在地或者？",options:["原告所在地人民法院管辖", "被告上级所在地法院管辖", "行为发生地法院管辖", "任意法院管辖"],answer:0,explanation:"行政诉讼法规定，对限制人身自由的行政强制措施不服提起的诉讼，由被告所在地或者原告所在地人民法院管辖。"},{id:"cs-4192",module:"changshi",prompt:"我国行政诉讼法规定，人民法院应当在立案之日起多少个月内作出第一审判决？",options:["6个月", "3个月", "9个月", "12个月"],answer:0,explanation:"行政诉讼法规定，人民法院应当在立案之日起6个月内作出第一审判决；有特殊情况需要延长的，经批准可以延长。"},{id:"cs-4193",module:"changshi",prompt:"我国工伤保险条例规定，职工在工作时间和工作岗位，突发疾病死亡或者在48小时之内经抢救无效死亡的，？",options:["视同工伤", "不认定为工伤", "由单位自行决定", "由个人承担"],answer:0,explanation:"工伤保险条例规定，职工在工作时间和工作岗位，突发疾病死亡或者在48小时之内经抢救无效死亡的，视同工伤。"},{id:"cs-4194",module:"changshi",prompt:"我国工伤保险条例规定，职工有下列情形之一的，不得认定为工伤或者视同工伤，其中包括？",options:["故意犯罪", "上下班途中受到交通事故伤害", "患职业病", "因工外出受伤"],answer:0,explanation:"工伤保险条例规定，故意犯罪、醉酒或者吸毒、自残或者自杀的，不得认定为工伤或者视同工伤。"},{id:"cs-4195",module:"changshi",prompt:"我国工伤保险条例规定，职工发生工伤，所在单位应当自事故伤害发生之日起多少日内提出工伤认定申请？",options:["30日", "15日", "60日", "90日"],answer:0,explanation:"工伤保险条例规定，职工发生事故伤害，所在单位应当自事故伤害发生之日起30日内向社会保险行政部门提出工伤认定申请；用人单位未申请的，工伤职工或者其近亲属可以在1年内申请。"},{id:"cs-4196",module:"changshi",prompt:"我国社会保险法规定，失业人员失业前用人单位和本人累计缴费满1年不足5年的，领取失业保险金的期限最长为？",options:["12个月", "6个月", "18个月", "24个月"],answer:0,explanation:"社会保险法规定，失业人员失业前用人单位和本人累计缴费满1年不足5年的，领取失业保险金的期限最长为12个月；累计缴费满5年不足10年的，最长为18个月；10年以上的，最长为24个月。"},{id:"cs-4197",module:"changshi",prompt:"我国社会保险法规定，失业保险金的领取条件不包括？",options:["主动辞职", "失业前用人单位和本人已经缴纳失业保险费满1年", "非因本人意愿中断就业", "已经进行失业登记，并有求职要求"],answer:0,explanation:"领取失业保险金的条件包括缴费满1年、非因本人意愿中断就业、已办理失业登记并有求职要求；主动辞职不属于非因本人意愿中断就业。"},{id:"cs-4198",module:"changshi",prompt:"我国社会保险法规定，基本养老金由统筹养老金和？",options:["个人账户养老金", "企业年金", "商业保险", "公积金"],answer:0,explanation:"社会保险法规定，基本养老金由统筹养老金和个人账户养老金组成；基本养老金根据个人累计缴费年限、缴费工资、当地职工平均工资、个人账户金额、城镇人口平均预期寿命等因素确定。"},{id:"cs-4199",module:"changshi",prompt:"我国劳动法规定，对怀孕多少个月以上的女职工，不得安排其延长工作时间和夜班劳动？",options:["7个月", "5个月", "3个月", "6个月"],answer:0,explanation:"劳动法规定，对怀孕7个月以上的女职工，不得安排其延长工作时间和夜班劳动；不得安排女职工在哺乳未满1周岁婴儿期间从事国家规定的第三级体力劳动强度的劳动和哺乳期禁忌从事的其他劳动。"},{id:"cs-4200",module:"changshi",prompt:"我国劳动合同法规定，集体合同由工会代表企业职工一方与用人单位订立，劳动报酬、工作时间等标准不得低于？",options:["当地人民政府规定的最低标准", "用人单位自定标准", "行业平均标准", "全国最高标准"],answer:0,explanation:"劳动合同法规定，集体合同中劳动报酬和劳动条件等标准不得低于当地人民政府规定的最低标准；用人单位与劳动者订立的劳动合同中劳动报酬和劳动条件等标准不得低于集体合同规定的标准。"},{id:"cs-4201",module:"changshi",prompt:"我国劳动合同法规定，用人单位裁减人员，应当提前多少日向工会或者全体职工说明情况？",options:["30日", "15日", "60日", "90日"],answer:0,explanation:"劳动合同法规定，用人单位依照规定裁减人员的，应当提前30日向工会或者全体职工说明情况，听取工会或者职工的意见后，裁减人员方案经向劳动行政部门报告，可以裁减人员。"},{id:"cs-4202",module:"changshi",prompt:"我国劳动合同法规定，用人单位裁减人员时，应当优先留用？",options:["与本单位订立较长期限的固定期限劳动合同的人员等", "新入职员工", "临时工", "劳务派遣人员"],answer:0,explanation:"劳动合同法规定，用人单位裁减人员时，应当优先留用与本单位订立较长期限的固定期限劳动合同的人员、订立无固定期限劳动合同的人员、家庭无其他就业人员且有需要扶养的老人或者未成年人的人员。"},{id:"cs-4203",module:"changshi",prompt:"我国劳动争议调解仲裁法规定，劳动争议申请仲裁的时效期间为？",options:["1年", "6个月", "2年", "3年"],answer:0,explanation:"劳动争议调解仲裁法规定，劳动争议申请仲裁的时效期间为1年，自当事人知道或者应当知道其权利被侵害之日起计算；劳动关系存续期间因拖欠劳动报酬发生争议的，不受该限制。"},{id:"cs-4204",module:"changshi",prompt:"我国反垄断法规定，行政机关和法律、法规授权的具有管理公共事务职能的组织不得滥用行政权力，实施？",options:["排除、限制竞争的行为", "正常管理行为", "公共服务行为", "宏观调控行为"],answer:0,explanation:"反垄断法规定，行政机关和法律、法规授权的具有管理公共事务职能的组织不得滥用行政权力，限定或者变相限定单位或者个人经营、购买、使用其指定的经营者提供的商品，排除、限制竞争。"},{id:"cs-4205",module:"changshi",prompt:"我国反垄断法规定，经营者主动向反垄断执法机构报告达成垄断协议的有关情况并提供重要证据的，执法机构可以？",options:["酌情减轻或者免除对该经营者的处罚", "加重处罚", "维持原处罚", "公开处罚"],answer:0,explanation:"反垄断法规定，经营者主动向反垄断执法机构报告达成垄断协议的有关情况并提供重要证据的，执法机构可以酌情减轻或者免除对该经营者的处罚，即宽大制度。"},{id:"cs-4206",module:"changshi",prompt:"我国消费者权益保护法规定，消费者在购买、使用商品或者接受服务时，其人格尊严、民族风俗习惯得到尊重，享有？",options:["个人信息依法得到保护的权利", "无限退货的权利", "免费获得商品的权利", "指定价格的权利"],answer:0,explanation:"消费者权益保护法规定，消费者享有人格尊严、民族风俗习惯得到尊重的权利，享有个人信息依法得到保护的权利。"},{id:"cs-4207",module:"changshi",prompt:"我国消费者权益保护法规定，网络交易平台提供者明知或者应知销售者或者服务者利用其平台侵害消费者合法权益，未采取必要措施的，依法与该销售者或者服务者承担？",options:["连带责任", "按份责任", "补充责任", "无责任"],answer:0,explanation:"消费者权益保护法规定，网络交易平台提供者明知或者应知销售者或者服务者利用其平台侵害消费者合法权益，未采取必要措施的，依法与该销售者或者服务者承担连带责任。"},{id:"cs-4208",module:"changshi",prompt:"我国价格法规定，下列商品和服务价格，政府在必要时可以实行政府指导价或者政府定价，其中包括？",options:["与国民经济发展和人民生活关系重大的极少数商品价格", "所有商品价格", "市场竞争充分的价格", "奢侈品价格"],answer:0,explanation:"价格法规定，政府在必要时可以对与国民经济发展和人民生活关系重大的极少数商品价格、资源稀缺的少数商品价格、自然垄断经营的商品价格、重要的公用事业价格、重要的公益性服务价格实行政府指导价或者政府定价。"},{id:"cs-4209",module:"changshi",prompt:"我国价格法规定，经营者违反明码标价规定的，责令改正，没收违法所得，可以并处？",options:["5000元以下的罚款", "500元以下的罚款", "5万元以下的罚款", "10万元以下的罚款"],answer:0,explanation:"价格法规定，经营者违反明码标价规定的，责令改正，没收违法所得，可以并处5000元以下的罚款。"},{id:"cs-4210",module:"changshi",prompt:"我国商业银行法规定，商业银行的贷款余额与存款余额的比例不得超过？",options:["75%", "50%", "80%", "100%"],answer:0,explanation:"商业银行法规定，商业银行贷款余额与存款余额的比例不得超过75%；流动性资产余额与流动性负债余额的比例不得低于25%。"},{id:"cs-4211",module:"changshi",prompt:"我国商业银行法规定，商业银行不得向关系人发放？",options:["信用贷款", "抵押贷款", "质押贷款", "保证贷款"],answer:0,explanation:"商业银行法规定，商业银行不得向关系人发放信用贷款；向关系人发放担保贷款的条件不得优于其他借款人同类贷款的条件。"},{id:"cs-4212",module:"changshi",prompt:"我国证券法规定，证券发行、交易活动，必须遵守法律、行政法规，禁止？",options:["欺诈、内幕交易和操纵证券市场的行为", "正常投资", "信息披露", "承销保荐"],answer:0,explanation:"证券法规定，证券发行、交易活动必须遵守法律、行政法规，禁止欺诈、内幕交易和操纵证券市场的行为。"},{id:"cs-4213",module:"changshi",prompt:"我国证券法规定，内幕交易是指证券交易内幕信息的知情人和非法获取内幕信息的人，在内幕信息公开前？",options:["买卖该证券，或者泄露该信息、建议他人买卖该证券", "正常买卖证券", "公开信息披露", "承销证券"],answer:0,explanation:"证券法规定，内幕交易是内幕信息知情人或非法获取内幕信息的人在内幕信息公开前买卖该证券，或者泄露该信息、建议他人买卖该证券的行为。"},{id:"cs-4214",module:"changshi",prompt:"我国广告法规定，广告中使用的数据、统计资料、调查结果、文摘、引用语等引证内容，应当？",options:["真实、准确，并表明出处", "随意使用", "夸大使用", "模糊使用"],answer:0,explanation:"广告法规定，广告中使用的数据、统计资料、调查结果、文摘、引用语等引证内容，应当真实、准确，并表明出处；引证内容有适用范围和有效期限的，应当明确表示。"},{id:"cs-4215",module:"changshi",prompt:"我国广告法规定，广告不得损害国家的尊严或者利益，不得妨碍社会安定，不得危害？",options:["人身、财产安全，损害社会公共利益", "竞争对手利益", "平台利益", "行业利益"],answer:0,explanation:"广告法规定，广告不得损害国家的尊严或者利益，不得妨碍社会安定，不得危害人身、财产安全，不得损害社会公共利益。"},{id:"cs-4216",module:"changshi",prompt:"我国民事诉讼法规定，当事人对小额诉讼案件的判决不服的，？",options:["不得上诉", "可以上诉", "可以申请再审", "可以复议"],answer:0,explanation:"民事诉讼法规定，人民法院适用小额诉讼程序审理案件，实行一审终审，当事人对判决不服的，不得上诉；符合条件的可以申请再审。"},{id:"cs-4217",module:"changshi",prompt:"我国民事诉讼法规定，债权人请求债务人给付金钱、有价证券，符合条件的，可以向有管辖权的基层人民法院申请？",options:["支付令", "先予执行", "财产保全", "强制执行"],answer:0,explanation:"民事诉讼法规定，债权人请求债务人给付金钱、有价证券，符合债权人与债务人没有其他债务纠纷、支付令能够送达债务人等条件的，可以向有管辖权的基层人民法院申请支付令。"},{id:"cs-4218",module:"changshi",prompt:"我国民事诉讼法规定，人民法院对下列案件，根据当事人的申请，可以裁定先予执行，其中包括？",options:["追索赡养费、扶养费、抚育费、抚恤金、医疗费用的", "普通买卖合同纠纷", "离婚案件", "继承纠纷"],answer:0,explanation:"民事诉讼法规定，人民法院对追索赡养费、扶养费、抚育费、抚恤金、医疗费用的案件，追索劳动报酬的案件，因情况紧急需要先予执行的案件，根据当事人的申请，可以裁定先予执行。"},{id:"cs-4219",module:"changshi",prompt:"我国民事诉讼法规定，直接送达诉讼文书有困难的，可以委托其他人民法院代为送达，或者？",options:["邮寄送达", "口头送达", "广播送达", "公告送达"],answer:0,explanation:"民事诉讼法规定，直接送达诉讼文书有困难的，可以委托其他人民法院代为送达，或者邮寄送达；受送达人是军人的，通过其所在部队团级以上单位的政治机关转交。"},{id:"cs-4220",module:"changshi",prompt:"我国民事诉讼法规定，受送达人下落不明，或者用其他方式无法送达的，可以？",options:["公告送达", "留置送达", "转交送达", "电子送达"],answer:0,explanation:"民事诉讼法规定，受送达人下落不明，或者用其他方式无法送达的，可以公告送达；自发出公告之日起，经过30日，即视为送达。"},{id:"cs-4221",module:"changshi",prompt:"我国刑事诉讼法规定，第二审人民法院审理被告人或者他的法定代理人、辩护人、近亲属上诉的案件，不得加重被告人的刑罚，这被称为？",options:["上诉不加刑原则", "罪刑法定原则", "罪责刑相适应原则", "无罪推定原则"],answer:0,explanation:"刑事诉讼法规定，第二审人民法院审理被告人一方上诉的案件，不得加重被告人的刑罚；人民检察院提出抗诉或者自诉人提出上诉的，不受该限制。"},{id:"cs-4222",module:"changshi",prompt:"我国刑事诉讼法规定，中级人民法院管辖的第一审刑事案件包括？",options:["危害国家安全、恐怖活动的案件，可能判处无期徒刑、死刑的案件", "所有刑事案件", "轻微刑事案件", "自诉案件"],answer:0,explanation:"刑事诉讼法规定，中级人民法院管辖危害国家安全、恐怖活动的案件以及可能判处无期徒刑、死刑的案件；基层人民法院管辖普通刑事案件。"},{id:"cs-4223",module:"changshi",prompt:"我国刑事诉讼法规定，最高人民法院复核死刑案件，高级人民法院复核死刑缓期执行的案件，应当？",options:["由审判员3人组成合议庭进行", "独任审判", "公开听证", "书面审理"],answer:0,explanation:"刑事诉讼法规定，最高人民法院复核死刑案件，高级人民法院复核死刑缓期执行的案件，应当由审判员3人组成合议庭进行。"},{id:"cs-4224",module:"changshi",prompt:"我国刑事诉讼法规定，当事人及其法定代理人、近亲属，对已经发生法律效力的判决、裁定，可以向人民法院或者人民检察院提出？",options:["申诉", "上诉", "抗诉", "复议"],answer:0,explanation:"刑事诉讼法规定，当事人及其法定代理人、近亲属，对已经发生法律效力的判决、裁定，可以向人民法院或者人民检察院提出申诉，但是不能停止判决、裁定的执行。"},{id:"cs-4225",module:"changshi",prompt:"我国行政诉讼法规定，行政案件的审判权由谁行使？",options:["人民法院", "人民检察院", "行政机关", "监察委员会"],answer:0,explanation:"行政诉讼法规定，人民法院依法对行政案件独立行使审判权，不受行政机关、社会团体和个人的干涉。"},{id:"cs-4226",module:"changshi",prompt:"我国行政诉讼法规定，公民、法人或者其他组织申请行政机关履行保护其人身权、财产权等合法权益的法定职责，行政机关不履行的，提起诉讼的期限为？",options:["行政机关履行法定职责期限届满后6个月内", "3个月内", "1年内", "2年内"],answer:0,explanation:"行政诉讼法规定，公民、法人或者其他组织申请行政机关履行保护其人身权、财产权等合法权益的法定职责，行政机关在接到申请之日起2个月内不履行的，可以提起诉讼；紧急情况下不受期限限制。"},{id:"cs-4227",module:"changshi",prompt:"我国行政诉讼法规定，人民法院判决确认行政行为违法，但不撤销行政行为的情形不包括？",options:["行政行为轻微违法但对原告权利不产生实际影响", "行政行为依法应当撤销，但撤销会给国家利益、社会公共利益造成重大损害", "行政行为程序轻微违法，但对原告权利不产生实际影响", "行政行为实施主体不具有行政主体资格"],answer:0,explanation:"行政诉讼法规定，行政行为依法应当撤销但撤销会给国家利益、社会公共利益造成重大损害的，或者程序轻微违法但对原告权利不产生实际影响的，判决确认违法但不撤销；行政行为重大且明显违法的，判决确认无效。"},{id:"cs-4228",module:"changshi",prompt:"当秩序与自由发生价值冲突时，解决的原则不包括？",options:["自由优先于秩序，任何情况下都无条件优先", "价值位阶原则", "个案平衡原则", "比例原则"],answer:0,explanation:"解决法的价值冲突的原则包括价值位阶原则、个案平衡原则和比例原则；自由并非任何情况下都无条件优先于秩序。"},{id:"cs-4229",module:"changshi",prompt:"法律推理的方法主要包括演绎推理、归纳推理和？",options:["类比推理", "概率推理", "模糊推理", "逆向推理"],answer:0,explanation:"法律推理的方法主要包括演绎推理、归纳推理和类比推理；演绎推理是从一般到个别的推理，是最常用的法律推理方法。"},{id:"cs-4230",module:"changshi",prompt:"法律论证的说服性标准要求？",options:["论证应当使听众接受结论", "论证应当符合逻辑", "论证应当符合立法原意", "论证应当符合习惯"],answer:0,explanation:"法律论证强调论证的说服性，即论证应当使听众（包括当事人和社会公众）接受结论，同时符合逻辑和法的价值。"},{id:"cs-4231",module:"changshi",prompt:"法律意识可以分为法律心理和？",options:["法律思想体系", "法律制度", "法律规范", "法律行为"],answer:0,explanation:"法律意识可以分为法律心理和法律思想体系；法律心理是人们对法律现象的感性认识，法律思想体系是理性认识。"},{id:"cs-4232",module:"changshi",prompt:"建设法治国家要求坚持？",options:["依法治国、依法执政、依法行政共同推进", "以人治为主", "以政策为主", "以道德代替法律"],answer:0,explanation:"建设法治国家要求坚持依法治国、依法执政、依法行政共同推进，坚持法治国家、法治政府、法治社会一体建设。"},{id:"cs-4233",module:"changshi",prompt:"法的实施方式包括法的遵守、法的执行和？",options:["法的适用", "法的制定", "法的废止", "法的修改"],answer:0,explanation:"法的实施方式包括法的遵守（守法）、法的执行（执法）和法的适用（司法）。"},{id:"cs-4234",module:"changshi",prompt:"执法的基本原则不包括？",options:["任意处置原则", "依法行政原则", "讲求效能原则", "公平合理原则"],answer:0,explanation:"执法的基本原则包括依法行政、讲求效能、公平合理等；任意处置不是执法原则，执法必须依法进行。"},{id:"cs-4235",module:"changshi",prompt:"司法的基本原则包括司法公正、司法独立和？",options:["司法效率", "司法垄断", "司法随意", "司法协商"],answer:0,explanation:"司法的基本原则包括司法公正、司法独立、司法效率、司法公开等；司法独立是司法机关依法独立行使职权。"});
(window.YC_CS_BANK=window.YC_CS_BANK||[]).push({id:"cs-4236",module:"changshi",prompt:"根据民法典合同编的规定，租赁合同的租赁期限最长不得超过多少年？",options:["20年", "10年", "30年", "5年"],answer:0,explanation:"民法规定，租赁期限不得超过20年；超过20年的，超过部分无效。"},{id:"cs-4237",module:"changshi",prompt:"从法理学的角度看，法律文化的含义是什么？",options:["一个国家或民族的法传统、法观念、法制度等的总和", "法律条文的总和", "法院判决的总和", "法学著作的总和"],answer:0,explanation:"法律文化是一个国家或民族的法传统、法观念、法制度、法意识等的总和，具有历史延续性和民族性。"},{id:"cs-4238",module:"changshi",prompt:"从法理学角度看，守法的主体包括哪些？",options:["一切组织和个人", "仅公民", "仅国家机关", "仅企业"],answer:0,explanation:"守法的主体是一切组织和个人，包括国家机关、社会组织和公民个人，任何组织和个人都必须遵守宪法和法律。"});
(window.YC_CS_BANK=window.YC_CS_BANK||[]).push({id:"cs-4239",module:"changshi",prompt:"我国宪法规定，中华人民共和国公民有劳动的权利和义务，劳动者有？",options:["休息的权利", "不劳动的权利", "随意离职的权利", "免除义务的权利"],answer:0,explanation:"宪法规定，公民有劳动的权利和义务；劳动者有休息的权利；国家发展劳动者休息和休养的设施，规定职工的工作时间和休假制度。"},{id:"cs-4240",module:"changshi",prompt:"我国宪法规定，中华人民共和国公民在年老、疾病或者丧失劳动能力的情况下，有从国家和社会获得？",options:["物质帮助的权利", "经济赔偿的权利", "全额补贴的权利", "免费医疗的权利"],answer:0,explanation:"宪法规定，公民在年老、疾病或者丧失劳动能力的情况下，有从国家和社会获得物质帮助的权利；国家发展为公民享受这些权利所需要的社会保险、社会救济和医疗卫生事业。"},{id:"cs-4241",module:"changshi",prompt:"我国宪法规定，中华人民共和国保护华侨的正当的权利和利益，保护归侨和侨眷的？",options:["合法的权利和利益", "全部权利和利益", "经济利益", "政治权利"],answer:0,explanation:"宪法规定，国家保护华侨的正当的权利和利益，保护归侨和侨眷的合法的权利和利益。"},{id:"cs-4242",module:"changshi",prompt:"我国宪法规定，全国人民代表大会会议每年举行一次，由谁召集？",options:["全国人民代表大会常务委员会", "国家主席", "国务院", "全国政协"],answer:0,explanation:"宪法规定，全国人民代表大会会议每年举行一次，由全国人民代表大会常务委员会召集；如果常务委员会认为必要，或者有五分之一以上的全国人民代表大会代表提议，可以临时召集全国人民代表大会会议。"},{id:"cs-4243",module:"changshi",prompt:"我国宪法规定，全国人民代表大会代表在全国人民代表大会开会期间，有权依照法律规定的程序提出对国务院或者国务院各部、各委员会的？",options:["质询案", "罢免案", "弹劾案", "否决案"],answer:0,explanation:"宪法规定，全国人民代表大会代表在全国人民代表大会开会期间，全国人民代表大会常务委员会组成人员在常务委员会开会期间，有权依照法律规定的程序提出对国务院或者国务院各部、各委员会的质询案。"},{id:"cs-4244",module:"changshi",prompt:"我国宪法规定，城市和农村按居民居住地区设立的居民委员会或者村民委员会是？",options:["基层群众性自治组织", "国家行政机关", "司法机关", "党的基层组织"],answer:0,explanation:"宪法规定，城市和农村按居民居住地区设立的居民委员会或者村民委员会是基层群众性自治组织；居民委员会、村民委员会设人民调解、治安保卫、公共卫生等委员会。"},{id:"cs-4245",module:"changshi",prompt:"我国宪法规定，居民委员会、村民委员会同基层政权的相互关系由？",options:["法律规定", "国务院决定", "地方政府自定", "居民自定"],answer:0,explanation:"宪法规定，居民委员会、村民委员会同基层政权的相互关系由法律规定；居民委员会、村民委员会的主任、副主任和委员由居民、村民选举。"},{id:"cs-4246",module:"changshi",prompt:"我国宪法规定，国家厉行节约，反对浪费，国家合理安排积累和消费，兼顾国家、集体和个人的利益，在发展生产的基础上，逐步改善人民的？",options:["物质生活和文化生活", "政治生活", "精神生活", "经济生活"],answer:0,explanation:"宪法规定，国家厉行节约，反对浪费；国家合理安排积累和消费，兼顾国家、集体和个人的利益，在发展生产的基础上，逐步改善人民的物质生活和文化生活。"},{id:"cs-4247",module:"changshi",prompt:"我国宪法规定，中华人民共和国公民有言论、出版、集会、结社、游行、示威的自由，这被称为？",options:["政治自由", "人身自由", "宗教自由", "经济自由"],answer:0,explanation:"宪法规定，公民有言论、出版、集会、结社、游行、示威的自由，这些是公民的政治自由，是公民参与国家政治生活的基本保障。"},{id:"cs-4248",module:"changshi",prompt:"我国宪法规定，全国人民代表大会代表，非经全国人民代表大会会议主席团许可，在全国人民代表大会闭会期间非经全国人民代表大会常务委员会许可，不受？",options:["逮捕或者刑事审判", "传唤", "询问", "约谈"],answer:0,explanation:"宪法规定，全国人民代表大会代表，非经全国人民代表大会会议主席团许可，在全国人民代表大会闭会期间非经全国人民代表大会常务委员会许可，不受逮捕或者刑事审判。"},{id:"cs-4249",module:"changshi",prompt:"我国宪法规定，中华人民共和国公民有维护国家安全、荣誉和利益的义务，不得有危害祖国的安全、荣誉和利益的？",options:["行为", "想法", "言论", "习惯"],answer:0,explanation:"宪法规定，公民有维护祖国的安全、荣誉和利益的义务，不得有危害祖国的安全、荣誉和利益的行为。"},{id:"cs-4250",module:"changshi",prompt:"赠与合同是赠与人将自己的财产无偿给予受赠人，受赠人表示接受赠与的合同，赠与人在赠与财产的权利转移之前可以？",options:["撤销赠与", "要求返还", "继续履行", "变更合同"],answer:0,explanation:"民法规定，赠与人在赠与财产的权利转移之前可以撤销赠与；但是经过公证的赠与合同或者依法不得撤销的具有救灾、扶贫、助残等公益、道德义务性质的赠与合同除外。"},{id:"cs-4251",module:"changshi",prompt:"受赠人有下列情形之一的，赠与人可以撤销赠与，其中包括？",options:["严重侵害赠与人或者赠与人近亲属的合法权益", "接受赠与", "使用赠与财产", "转让赠与财产"],answer:0,explanation:"民法规定，受赠人严重侵害赠与人或者赠与人近亲属的合法权益、对赠与人有扶养义务而不履行、不履行赠与合同约定的义务的，赠与人可以撤销赠与。"},{id:"cs-4252",module:"changshi",prompt:"承揽合同是承揽人按照定作人的要求完成工作，交付工作成果，定作人支付报酬的合同，承揽包括？",options:["加工、定作、修理、复制、测试、检验等工作", "运输、保管", "买卖、租赁", "借款、担保"],answer:0,explanation:"民法规定，承揽合同包括加工、定作、修理、复制、测试、检验等工作；承揽人以自己的设备、技术和劳力完成主要工作。"},{id:"cs-4253",module:"changshi",prompt:"运输合同是承运人将旅客或者货物从起运地点运输到约定地点，旅客、托运人或者收货人支付票款或者运输费用的合同，承运人应当按照约定的或者通常路线将旅客、货物运输到？",options:["约定地点", "任意地点", "承运人指定地点", "出发地"],answer:0,explanation:"民法规定，承运人应当按照约定的或者通常路线将旅客、货物运输到约定地点；旅客、托运人或者收货人应当支付票款或者运输费用。"},{id:"cs-4254",module:"changshi",prompt:"保管合同是保管人保管寄存人交付的保管物，并返还该物的合同，保管合同自何时成立？",options:["保管物交付时", "合同签订时", "口头约定时", "书面确认时"],answer:0,explanation:"民法规定，保管合同自保管物交付时成立，但是当事人另有约定的除外；保管是无偿的，保管人证明自己没有重大过失的，不承担损害赔偿责任。"},{id:"cs-4255",module:"changshi",prompt:"委托合同是委托人和受托人约定，由受托人处理委托人事务的合同，受托人应当按照委托人的指示处理委托事务，需要变更委托人指示的，应当？",options:["经委托人同意", "自行决定", "报法院批准", "通知第三人"],answer:0,explanation:"民法规定，受托人应当按照委托人的指示处理委托事务；需要变更委托人指示的，应当经委托人同意；因情况紧急难以和委托人取得联系的，受托人应当妥善处理委托事务，但是事后应当将该情况及时报告委托人。"},{id:"cs-4256",module:"changshi",prompt:"自然人享有生命权、身体权、健康权、姓名权、肖像权、名誉权、荣誉权、隐私权等权利，法人、非法人组织享有？",options:["名称权、名誉权、荣誉权等权利", "生命权、身体权", "健康权、隐私权", "肖像权、婚姻自主权"],answer:0,explanation:"民法规定，自然人享有生命权、身体权、健康权等权利；法人、非法人组织享有名称权、名誉权和荣誉权。"},{id:"cs-4257",module:"changshi",prompt:"以非法拘禁等方式剥夺、限制他人的行动自由，或者非法搜查他人身体的，受害人有权依法请求行为人？",options:["承担民事责任", "承担刑事责任", "承担行政责任", "承担政治责任"],answer:0,explanation:"民法规定，以非法拘禁等方式剥夺、限制他人的行动自由，或者非法搜查他人身体的，受害人有权依法请求行为人承担民事责任。"},{id:"cs-4258",module:"changshi",prompt:"侵害他人人身权益造成财产损失的，按照被侵权人因此受到的损失或者侵权人因此获得的利益赔偿；难以确定的，可以向人民法院提起诉讼，由人民法院根据实际情况确定赔偿数额，这体现了？",options:["人身损害赔偿制度", "惩罚性赔偿制度", "精神损害赔偿制度", "违约赔偿制度"],answer:0,explanation:"民法规定，侵害他人人身权益造成财产损失的，按照被侵权人因此受到的损失或者侵权人因此获得的利益赔偿；被侵权人的损失难以确定，侵权人因此获得的利益难以确定，双方就赔偿数额协商不一致的，可以向人民法院提起诉讼。"},{id:"cs-4259",module:"changshi",prompt:"侵害自然人人身权益造成严重精神损害的，被侵权人有权请求？",options:["精神损害赔偿", "惩罚性赔偿", "加倍赔偿", "三倍赔偿"],answer:0,explanation:"民法规定，侵害自然人人身权益造成严重精神损害的，被侵权人有权请求精神损害赔偿；侵害特定物的具有人身意义的物品造成严重精神损害的，也可以请求精神损害赔偿。"},{id:"cs-4260",module:"changshi",prompt:"机动车发生交通事故造成损害的，属于该机动车一方责任的，先由承保机动车强制保险的保险人在强制保险责任限额范围内予以赔偿，不足部分由承保机动车商业保险的保险人按照保险合同的约定予以赔偿，仍然不足的，由谁赔偿？",options:["侵权人赔偿", "保险公司赔偿", "受害人自担", "交管部门赔偿"],answer:0,explanation:"民法典规定，机动车发生交通事故造成损害的，先由交强险赔偿，不足部分由商业险赔偿，仍然不足的或者没有投保的，由侵权人赔偿。"},{id:"cs-4261",module:"changshi",prompt:"承担高度危险责任，使用易燃、易爆、剧毒、高放射性、强腐蚀性、高致病性等高度危险物造成他人损害的，受害人故意造成损害的，行为人？",options:["不承担责任", "承担全部责任", "承担一半责任", "承担补偿责任"],answer:0,explanation:"民法典规定，使用高度危险物造成他人损害的，承担无过错责任；但是能够证明损害是因受害人故意或者不可抗力造成的，不承担责任。"},{id:"cs-4262",module:"changshi",prompt:"因污染环境、破坏生态造成他人损害的，侵权人应当承担？",options:["侵权责任", "行政责任", "刑事责任", "政治责任"],answer:0,explanation:"民法典规定，因污染环境、破坏生态造成他人损害的，侵权人应当承担侵权责任；违反国家规定造成生态环境损害的，国家规定的机关或者法律规定的组织有权请求侵权人承担修复责任。"},{id:"cs-4263",module:"changshi",prompt:"父母是未成年子女的？",options:["监护人", "代理人", "担保人", "委托人"],answer:0,explanation:"民法规定，父母是未成年子女的监护人；未成年人的父母已经死亡或者没有监护能力的，由祖父母、外祖父母等有监护能力的人按顺序担任监护人。"},{id:"cs-4264",module:"changshi",prompt:"监护人应当按照最有利于被监护人的原则履行监护职责，监护人除为维护被监护人利益外，不得处分被监护人的？",options:["财产", "人身", "自由", "名誉"],answer:0,explanation:"民法规定，监护人应当按照最有利于被监护人的原则履行监护职责；监护人除为维护被监护人利益外，不得处分被监护人的财产。"},{id:"cs-4265",module:"changshi",prompt:"我国刑法规定，已满14周岁不满18周岁的人犯罪，应当？",options:["从轻或者减轻处罚", "从重处罚", "免除处罚", "加重处罚"],answer:0,explanation:"刑法规定，已满14周岁不满18周岁的人犯罪，应当从轻或者减轻处罚；犯罪时不满18周岁的人，不适用死刑。"},{id:"cs-4266",module:"changshi",prompt:"我国刑法规定，已满75周岁的人故意犯罪的，？",options:["可以从轻或者减轻处罚", "应当从重处罚", "免除处罚", "加重处罚"],answer:0,explanation:"刑法规定，已满75周岁的人故意犯罪的，可以从轻或者减轻处罚；过失犯罪的，应当从轻或者减轻处罚。"},{id:"cs-4267",module:"changshi",prompt:"我国刑法规定，又聋又哑的人或者盲人犯罪，？",options:["可以从轻、减轻或者免除处罚", "应当从重处罚", "免除处罚", "加重处罚"],answer:0,explanation:"刑法规定，又聋又哑的人或者盲人犯罪，可以从轻、减轻或者免除处罚。"},{id:"cs-4268",module:"changshi",prompt:"我国刑法规定，被判处管制、拘役、有期徒刑、无期徒刑的犯罪分子，在执行期间，如果认真遵守监规，接受教育改造，确有悔改表现的，或者有立功表现的，可以？",options:["减刑", "假释", "缓刑", "赦免"],answer:0,explanation:"刑法规定，被判处管制、拘役、有期徒刑、无期徒刑的犯罪分子，在执行期间，如果认真遵守监规，接受教育改造，确有悔改表现的，或者有立功表现的，可以减刑；有重大立功表现的，应当减刑。"},{id:"cs-4269",module:"changshi",prompt:"我国刑法规定，减刑以后实际执行的刑期，判处管制、拘役、有期徒刑的，不能少于？",options:["原判刑期的二分之一", "原判刑期的三分之一", "原判刑期的四分之一", "原判刑期的三分之二"],answer:0,explanation:"刑法规定，减刑以后实际执行的刑期，判处管制、拘役、有期徒刑的，不能少于原判刑期的二分之一；判处无期徒刑的，不能少于13年。"},{id:"cs-4270",module:"changshi",prompt:"我国刑法规定，对被判处管制、宣告缓刑、假释的犯罪分子，依法实行？",options:["社区矫正", "监外执行", "取保候审", "监视居住"],answer:0,explanation:"刑法规定，对被判处管制、宣告缓刑、假释的犯罪分子，依法实行社区矫正，由社区矫正机构负责执行。"},{id:"cs-4271",module:"changshi",prompt:"公司、企业或者其他单位的人员，利用职务上的便利，将本单位财物非法占为己有，数额较大的，构成？",options:["职务侵占罪", "贪污罪", "挪用资金罪", "盗窃罪"],answer:0,explanation:"职务侵占罪是公司、企业或者其他单位的人员，利用职务上的便利，将本单位财物非法占为己有，数额较大的行为；国家工作人员实施该行为的，构成贪污罪。"},{id:"cs-4272",module:"changshi",prompt:"公司、企业或者其他单位的工作人员，利用职务上的便利，挪用本单位资金归个人使用或者借贷给他人，数额较大、超过3个月未还的，构成？",options:["挪用资金罪", "挪用公款罪", "职务侵占罪", "挪用特定款物罪"],answer:0,explanation:"挪用资金罪是公司、企业或者其他单位的工作人员，利用职务上的便利，挪用本单位资金归个人使用或者借贷给他人，数额较大、超过3个月未还，或者虽未超过3个月，但数额较大、进行营利活动或者非法活动的行为。"},{id:"cs-4273",module:"changshi",prompt:"为掩饰、隐瞒毒品犯罪、黑社会性质的组织犯罪、恐怖活动犯罪、走私犯罪、贪污贿赂犯罪、破坏金融管理秩序犯罪、金融诈骗犯罪的所得及其产生的收益的来源和性质，实施提供资金账户等行为的，构成？",options:["洗钱罪", "掩饰隐瞒犯罪所得罪", "窝藏包庇罪", "帮助毁灭证据罪"],answer:0,explanation:"洗钱罪是为掩饰、隐瞒特定上游犯罪的所得及其产生的收益的来源和性质，实施提供资金账户、将财产转换为现金或金融票据、通过转账等方式转移资金等行为。"},{id:"cs-4274",module:"changshi",prompt:"明知他人利用信息网络实施犯罪，为其犯罪提供互联网接入、服务器托管、网络存储、通讯传输等技术支持，或者提供广告推广、支付结算等帮助，情节严重的，构成？",options:["帮助信息网络犯罪活动罪", "诈骗罪", "非法经营罪", "破坏计算机信息系统罪"],answer:0,explanation:"帮助信息网络犯罪活动罪是明知他人利用信息网络实施犯罪，为其提供技术支持或帮助，情节严重的行为。"},{id:"cs-4275",module:"changshi",prompt:"以暴力、威胁方法阻碍国家机关工作人员依法执行职务的，构成？",options:["妨害公务罪", "聚众斗殴罪", "寻衅滋事罪", "故意伤害罪"],answer:0,explanation:"妨害公务罪是以暴力、威胁方法阻碍国家机关工作人员依法执行职务，阻碍人大代表依法执行代表职务，或者在自然灾害和突发事件中阻碍红十字会工作人员依法履行职责的行为。"},{id:"cs-4276",module:"changshi",prompt:"聚众斗殴，对首要分子和其他积极参加的，构成？",options:["聚众斗殴罪", "故意伤害罪", "寻衅滋事罪", "妨害公务罪"],answer:0,explanation:"聚众斗殴罪是对聚众斗殴的首要分子和其他积极参加的人的犯罪；聚众斗殴致人重伤、死亡的，依照故意伤害罪、故意杀人罪定罪处罚。"},{id:"cs-4277",module:"changshi",prompt:"随意殴打他人，情节恶劣的；追逐、拦截、辱骂、恐吓他人，情节恶劣的；强拿硬要或者任意损毁、占用公私财物，情节严重的，构成？",options:["寻衅滋事罪", "故意伤害罪", "聚众斗殴罪", "抢劫罪"],answer:0,explanation:"寻衅滋事罪是随意殴打他人情节恶劣，追逐、拦截、辱骂、恐吓他人情节恶劣，强拿硬要或者任意损毁、占用公私财物情节严重，在公共场所起哄闹事造成公共场所秩序严重混乱的行为。"},{id:"cs-4278",module:"changshi",prompt:"以营利为目的，聚众赌博或者以赌博为业的，构成？",options:["赌博罪", "开设赌场罪", "诈骗罪", "盗窃罪"],answer:0,explanation:"赌博罪是以营利为目的，聚众赌博或者以赌博为业的行为；开设赌场的，构成开设赌场罪。"},{id:"cs-4279",module:"changshi",prompt:"我国刑法规定，犯罪的时候不满18周岁的人和审判的时候怀孕的妇女，？",options:["不适用死刑", "可以适用死刑", "应当适用死刑", "适用死缓"],answer:0,explanation:"刑法规定，犯罪的时候不满18周岁的人和审判的时候怀孕的妇女，不适用死刑；审判的时候已满75周岁的人，不适用死刑，但以特别残忍手段致人死亡的除外。"},{id:"cs-4280",module:"changshi",prompt:"我国行政许可法规定，直接关系公共安全、人身健康、生命财产安全的重要设备、设施，应当按照？",options:["技术标准、技术规范进行检验、检测", "企业自定标准检验", "口头承诺验收", "抽样免检"],answer:0,explanation:"行政许可法规定，直接关系公共安全、人身健康、生命财产安全的重要设备、设施，应当按照技术标准、技术规范进行检验、检测；检验、检测合格的，行政机关应当发给相应的证明文件。"},{id:"cs-4281",module:"changshi",prompt:"我国行政处罚法规定，当事人有下列情形之一的，应当从轻或者减轻行政处罚，其中包括？",options:["主动消除或者减轻违法行为危害后果的", "拒不改正的", "多次违法的", "隐匿证据的"],answer:0,explanation:"行政处罚法规定，主动消除或者减轻违法行为危害后果的、受他人胁迫或者诱骗实施违法行为的、主动供述行政机关尚未掌握的违法行为的、配合查处违法行为有立功表现的等，应当从轻或者减轻行政处罚。"},{id:"cs-4282",module:"changshi",prompt:"我国行政处罚法规定，不满多少周岁的人有违法行为的，不予行政处罚，责令监护人加以管教？",options:["14周岁", "16周岁", "12周岁", "18周岁"],answer:0,explanation:"行政处罚法规定，不满14周岁的人有违法行为的，不予行政处罚，责令监护人加以管教；已满14周岁不满18周岁的人有违法行为的，应当从轻或者减轻行政处罚。"},{id:"cs-4283",module:"changshi",prompt:"我国行政处罚法规定，当事人有证据足以证明没有主观过错的，？",options:["不予行政处罚", "从重处罚", "减轻处罚", "正常处罚"],answer:0,explanation:"行政处罚法规定，当事人有证据足以证明没有主观过错的，不予行政处罚；法律、行政法规另有规定的，从其规定。"},{id:"cs-4284",module:"changshi",prompt:"我国行政处罚法规定，行政处罚由具有行政处罚权的行政机关在？",options:["法定职权范围内实施", "任意范围内实施", "上级授权范围内实施", "协商范围内实施"],answer:0,explanation:"行政处罚法规定，行政处罚由具有行政处罚权的行政机关在法定职权范围内实施；法律、法规授权的具有管理公共事务职能的组织可以在法定授权范围内实施行政处罚。"},{id:"cs-4285",module:"changshi",prompt:"我国行政处罚法规定，行政处罚没有依据或者实施主体不具有行政主体资格等重大违法情形的，行政处罚决定？",options:["无效", "可撤销", "效力待定", "有效"],answer:0,explanation:"行政处罚法规定，行政处罚没有依据或者实施主体不具有行政主体资格等重大且明显违法情形的，行政处罚决定无效。"},{id:"cs-4286",module:"changshi",prompt:"我国突发事件应对法规定，突发事件的分级不包括？",options:["五级", "特别重大", "重大", "较大和一般"],answer:0,explanation:"突发事件应对法规定，突发事件分为特别重大、重大、较大和一般四级，不包括五级。"},{id:"cs-4287",module:"changshi",prompt:"我国突发事件应对法规定，突发事件是指突然发生，造成或者可能造成严重社会危害，需要采取应急处置措施予以应对的自然灾害、事故灾难、公共卫生事件和？",options:["社会安全事件", "经济危机", "金融风险", "环境变化"],answer:0,explanation:"突发事件应对法规定，突发事件是指突然发生，造成或者可能造成严重社会危害，需要采取应急处置措施予以应对的自然灾害、事故灾难、公共卫生事件和社会安全事件。"},{id:"cs-4288",module:"changshi",prompt:"我国行政强制法规定，行政机关实施行政强制，应当遵循？",options:["比例原则，选择适当的行政强制方式", "效率优先原则", "从严从重原则", "灵活变通原则"],answer:0,explanation:"行政强制法规定，行政机关实施行政强制，应当遵循比例原则，选择适当的行政强制方式，以最小损害当事人权益的方式实现行政管理目的。"},{id:"cs-4289",module:"changshi",prompt:"我国行政强制法规定，行政机关依法作出金钱给付义务的行政决定，当事人逾期不履行的，行政机关可以依法？",options:["加处罚款或者滞纳金", "直接拘留", "直接判刑", "直接没收财产"],answer:0,explanation:"行政强制法规定，行政机关依法作出金钱给付义务的行政决定，当事人逾期不履行的，行政机关可以依法加处罚款或者滞纳金；加处罚款或者滞纳金的数额不得超出金钱给付义务的数额。"},{id:"cs-4290",module:"changshi",prompt:"我国公务员法规定，公务员职务、职级实行？",options:["能上能下制度", "终身制", "世袭制", "任命制"],answer:0,explanation:"公务员法规定，公务员职务、职级实行能上能下制度；公务员在年度考核中被确定为不称职的，按照规定程序降低一个职务或者职级层次任职。"},{id:"cs-4291",module:"changshi",prompt:"我国公务员法规定，对公务员的奖励不包括？",options:["刑事奖励", "嘉奖", "记三等功、二等功、一等功", "授予称号"],answer:0,explanation:"公务员法规定，对公务员的奖励包括嘉奖、记三等功、二等功、一等功、授予称号等；刑事奖励不是公务员奖励种类。"},{id:"cs-4292",module:"changshi",prompt:"我国公务员法规定，公务员应当履行的义务不包括？",options:["服从上级的一切命令", "忠于宪法，模范遵守宪法和法律", "忠于职守，勤勉尽责", "保守国家秘密和工作秘密"],answer:0,explanation:"公务员法规定，公务员应当忠于宪法、模范遵守宪法和法律、忠于职守、勤勉尽责、保守秘密等；对明显违法的决定或命令应当拒绝执行，而不是服从上级的一切命令。"},{id:"cs-4293",module:"changshi",prompt:"我国劳动法规定，用人单位必须为劳动者提供符合国家规定的劳动安全卫生条件和必要的劳动防护用品，对从事有职业危害作业的劳动者应当定期进行？",options:["健康检查", "技能培训", "绩效考核", "思想教育"],answer:0,explanation:"劳动法规定，用人单位必须为劳动者提供符合国家规定的劳动安全卫生条件和必要的劳动防护用品，对从事有职业危害作业的劳动者应当定期进行健康检查。"},{id:"cs-4294",module:"changshi",prompt:"我国劳动法规定，从事特种作业的劳动者必须经过专门培训并取得？",options:["特种作业资格", "学历证书", "职称证书", "荣誉证书"],answer:0,explanation:"劳动法规定，从事特种作业的劳动者必须经过专门培训并取得特种作业资格。"},{id:"cs-4295",module:"changshi",prompt:"我国劳动法规定，劳动者在劳动过程中必须严格遵守安全操作规程，劳动者对用人单位管理人员违章指挥、强令冒险作业，有权？",options:["拒绝执行", "服从执行", "向上级举报后执行", "协商后执行"],answer:0,explanation:"劳动法规定，劳动者在劳动过程中必须严格遵守安全操作规程；劳动者对用人单位管理人员违章指挥、强令冒险作业，有权拒绝执行。"},{id:"cs-4296",module:"changshi",prompt:"我国社会保险法规定，职工应当参加工伤保险，由谁缴纳工伤保险费？",options:["用人单位缴纳，职工不缴纳", "职工缴纳，单位不缴", "双方共同缴纳", "国家财政缴纳"],answer:0,explanation:"社会保险法规定，职工应当参加工伤保险，由用人单位缴纳工伤保险费，职工不缴纳工伤保险费。"},{id:"cs-4297",module:"changshi",prompt:"我国社会保险法规定，职工应当参加生育保险，由谁缴纳生育保险费？",options:["用人单位缴纳，职工不缴纳", "职工缴纳，单位不缴", "双方共同缴纳", "国家财政缴纳"],answer:0,explanation:"社会保险法规定，职工应当参加生育保险，由用人单位按照国家规定缴纳生育保险费，职工不缴纳生育保险费。"},{id:"cs-4298",module:"changshi",prompt:"我国社会保险法规定，用人单位应当自行申报、按时足额缴纳社会保险费，未按时足额缴纳的，由社会保险费征收机构责令限期缴纳或者补足，并自欠缴之日起，按日加收？",options:["万分之五的滞纳金", "千分之五的滞纳金", "百分之一的滞纳金", "万分之十的滞纳金"],answer:0,explanation:"社会保险法规定，用人单位未按时足额缴纳社会保险费的，由社会保险费征收机构责令限期缴纳或者补足，并自欠缴之日起，按日加收万分之五的滞纳金。"},{id:"cs-4299",module:"changshi",prompt:"我国劳动法规定，国家确定职业分类，对规定的职业制定职业技能标准，实行？",options:["职业资格证书制度", "终身雇佣制度", "统一分配制度", "固定工资制度"],answer:0,explanation:"劳动法规定，国家确定职业分类，对规定的职业制定职业技能标准，实行职业资格证书制度，由经过政府批准的考核鉴定机构负责对劳动者实施职业技能考核鉴定。"},{id:"cs-4300",module:"changshi",prompt:"我国劳动保障监察条例规定，劳动保障监察是？",options:["劳动保障行政部门对用人单位遵守劳动保障法律法规情况进行监督检查", "用人单位内部检查", "工会监督", "群众举报"],answer:0,explanation:"劳动保障监察条例规定，劳动保障监察是劳动保障行政部门对用人单位遵守劳动保障法律、法规和规章的情况进行监督检查，并对违法行为进行处理的活动。"},{id:"cs-4301",module:"changshi",prompt:"我国劳动保障监察条例规定，劳动保障监察以日常巡视检查和？",options:["书面材料审查等方式进行", "口头询问为主", "电话访谈为主", "网络调查为主"],answer:0,explanation:"劳动保障监察条例规定，劳动保障监察以日常巡视检查和书面材料审查等方式进行，受理对违反劳动保障法律、法规或者规章的行为的举报、投诉。"},{id:"cs-4302",module:"changshi",prompt:"我国劳动合同法规定，用人单位拖欠或者未足额支付劳动报酬的，劳动者可以依法向当地人民法院申请？",options:["支付令", "先予执行", "财产保全", "强制执行"],answer:0,explanation:"劳动合同法规定，用人单位拖欠或者未足额支付劳动报酬的，劳动者可以依法向当地人民法院申请支付令，人民法院应当依法发出支付令。"},{id:"cs-4303",module:"changshi",prompt:"我国劳动合同法规定，个人承包经营违反本法规定招用劳动者，给劳动者造成损害的，发包的组织与个人承包经营者承担？",options:["连带赔偿责任", "按份责任", "补充责任", "无责任"],answer:0,explanation:"劳动合同法规定，个人承包经营违反本法规定招用劳动者，给劳动者造成损害的，发包的组织与个人承包经营者承担连带赔偿责任。"},{id:"cs-4304",module:"changshi",prompt:"我国劳动合同法规定，用人单位招用劳动者，不得扣押劳动者的居民身份证和其他证件，不得要求劳动者提供担保或者以其他名义向劳动者收取？",options:["财物", "保证金", "押金", "违约金"],answer:0,explanation:"劳动合同法规定，用人单位招用劳动者，不得扣押劳动者的居民身份证和其他证件，不得要求劳动者提供担保或者以其他名义向劳动者收取财物。"},{id:"cs-4305",module:"changshi",prompt:"我国反垄断法规定，认定经营者具有市场支配地位，可以依据市场份额达到一定比例推定，其中1个经营者市场份额达到多少的，可以推定其具有市场支配地位？",options:["二分之一", "三分之一", "三分之二", "四分之三"],answer:0,explanation:"反垄断法规定，1个经营者的市场份额达到二分之一的，可以推定其具有市场支配地位；2个经营者合计达到三分之二、3个经营者合计达到四分之三的，可以推定其中2个或3个经营者具有市场支配地位。"},{id:"cs-4306",module:"changshi",prompt:"我国反垄断法规定，禁止经营者与交易相对人达成下列纵向垄断协议，其中包括？",options:["固定向第三人转售商品的价格", "正常供货协议", "正常销售协议", "正常采购协议"],answer:0,explanation:"反垄断法规定，禁止经营者与交易相对人达成固定向第三人转售商品的价格、限定向第三人转售商品的最低价格等纵向垄断协议。"},{id:"cs-4307",module:"changshi",prompt:"我国消费者权益保护法规定，经营者提供的机动车、计算机、电视机、电冰箱、空调器、洗衣机等耐用商品或者装饰装修等服务，消费者自接受商品或者服务之日起6个月内发现瑕疵，发生争议的，由谁承担有关瑕疵的举证责任？",options:["经营者", "消费者", "生产者", "监管部门"],answer:0,explanation:"消费者权益保护法规定，经营者提供的机动车、计算机、电视机、电冰箱、空调器、洗衣机等耐用商品或者装饰装修等服务，消费者自接受商品或者服务之日起6个月内发现瑕疵，发生争议的，由经营者承担有关瑕疵的举证责任。"},{id:"cs-4308",module:"changshi",prompt:"我国消费者权益保护法规定，经营者以广告、产品说明、实物样品或者其他方式表明商品或者服务的质量状况的，应当保证其提供的商品或者服务的实际质量与表明的？",options:["质量状况相符", "价格相符", "数量相符", "包装相符"],answer:0,explanation:"消费者权益保护法规定，经营者以广告、产品说明、实物样品或者其他方式表明商品或者服务的质量状况的，应当保证其提供的商品或者服务的实际质量与表明的质量状况相符。"},{id:"cs-4309",module:"changshi",prompt:"我国食品安全法规定，国家建立食品安全全程追溯制度，食品生产经营者应当建立？",options:["食品安全追溯体系", "销售档案", "财务档案", "人事档案"],answer:0,explanation:"食品安全法规定，国家建立食品安全全程追溯制度；食品生产经营者应当建立食品安全追溯体系，保证食品可追溯。"},{id:"cs-4310",module:"changshi",prompt:"我国食品安全法规定，国家建立食品安全风险监测制度，对食源性疾病、食品污染以及食品中的有害因素进行？",options:["监测", "处罚", "许可", "备案"],answer:0,explanation:"食品安全法规定，国家建立食品安全风险监测制度，对食源性疾病、食品污染以及食品中的有害因素进行监测。"},{id:"cs-4311",module:"changshi",prompt:"我国广告法规定，不得在针对未成年人的大众传播媒介上发布？",options:["医疗、药品、保健食品、医疗器械、化妆品、酒类、美容广告", "教育广告", "图书广告", "文具广告"],answer:0,explanation:"广告法规定，不得在针对未成年人的大众传播媒介上发布医疗、药品、保健食品、医疗器械、化妆品、酒类、美容广告，以及不利于未成年人身心健康的网络游戏广告等。"},{id:"cs-4312",module:"changshi",prompt:"我国广告法规定，利用互联网发布广告，应当具有？",options:["可识别性，显著标明广告", "隐蔽性", "娱乐性", "互动性"],answer:0,explanation:"广告法规定，利用互联网发布、发送广告，不得影响用户正常使用网络；在互联网页面以弹出等形式发布的广告，应当显著标明关闭标志，确保一键关闭。"},{id:"cs-4313",module:"changshi",prompt:"我国税收征收管理法规定，税务机关有根据认为从事生产、经营的纳税人有逃避纳税义务行为的，可以在规定的纳税期之前，责令限期缴纳应纳税款；在限期内发现纳税人有明显的转移、隐匿其应纳税的商品、货物以及其他财产或者应纳税的收入的迹象的，税务机关可以责成纳税人提供？",options:["纳税担保", "抵押物", "保证金", "保证人"],answer:0,explanation:"税收征收管理法规定，税务机关可以责成纳税人提供纳税担保；纳税人不能提供纳税担保的，经批准，税务机关可以采取税收保全措施。"},{id:"cs-4314",module:"changshi",prompt:"我国税收征收管理法规定，纳税人未按照规定的期限申报办理税务登记、变更或者注销登记的，由税务机关责令限期改正，可以处？",options:["2000元以下的罚款", "200元以下的罚款", "1万元以下的罚款", "5万元以下的罚款"],answer:0,explanation:"税收征收管理法规定，纳税人未按照规定的期限申报办理税务登记、变更或者注销登记的，由税务机关责令限期改正，可以处2000元以下的罚款；情节严重的，处2000元以上1万元以下的罚款。"},{id:"cs-4315",module:"changshi",prompt:"我国反不正当竞争法规定，经营者不得编造、传播虚假信息或者误导性信息，损害竞争对手的？",options:["商业信誉、商品声誉", "个人名誉", "品牌形象", "市场份额"],answer:0,explanation:"反不正当竞争法规定，经营者不得编造、传播虚假信息或者误导性信息，损害竞争对手的商业信誉、商品声誉，即商业诋毁行为。"},{id:"cs-4316",module:"changshi",prompt:"我国反不正当竞争法规定，经营者进行有奖销售不得存在下列情形，其中包括？",options:["所设奖的种类、兑奖条件、奖金金额或者奖品等有奖销售信息不明确，影响兑奖", "正常抽奖", "正常赠品", "正常折扣"],answer:0,explanation:"反不正当竞争法规定，经营者进行有奖销售不得谎称有奖、所设奖的信息不明确影响兑奖、抽奖式有奖销售最高奖金额超过5万元等。"},{id:"cs-4317",module:"changshi",prompt:"我国民事诉讼法规定的证据种类不包括？",options:["微信聊天记录", "当事人的陈述", "书证", "物证"],answer:0,explanation:"民事诉讼法规定的证据种类包括当事人的陈述、书证、物证、视听资料、电子数据、证人证言、鉴定意见、勘验笔录；微信聊天记录属于电子数据，是法定证据种类。"},{id:"cs-4318",module:"changshi",prompt:"我国民事诉讼法规定，当事人对自己提出的主张，有责任提供证据；当事人及其诉讼代理人因客观原因不能自行收集的证据，或者人民法院认为审理案件需要的证据，人民法院应当？",options:["调查收集", "免除举证", "驳回起诉", "中止审理"],answer:0,explanation:"民事诉讼法规定，当事人及其诉讼代理人因客观原因不能自行收集的证据，或者人民法院认为审理案件需要的证据，人民法院应当调查收集。"},{id:"cs-4319",module:"changshi",prompt:"我国民事诉讼法规定，当事人对鉴定意见有异议或者人民法院认为鉴定人有必要出庭的，鉴定人应当？",options:["出庭作证", "书面答复", "电话说明", "委托他人"],answer:0,explanation:"民事诉讼法规定，当事人对鉴定意见有异议或者人民法院认为鉴定人有必要出庭的，鉴定人应当出庭作证；鉴定人拒不出庭作证的，鉴定意见不得作为认定事实的根据。"},{id:"cs-4320",module:"changshi",prompt:"我国民事诉讼法规定，经人民法院通知，证人没有正当理由不出庭作证的，其证言？",options:["不得单独作为认定案件事实的根据", "一律无效", "效力最高", "可以采信"],answer:0,explanation:"民事诉讼法规定，经人民法院通知，证人没有正当理由不出庭作证的，其证言不得单独作为认定案件事实的根据。"},{id:"cs-4321",module:"changshi",prompt:"我国刑事诉讼法规定，采用刑讯逼供等非法方法收集的犯罪嫌疑人、被告人供述和采用暴力、威胁等非法方法收集的证人证言、被害人陈述，应当？",options:["予以排除", "可以采信", "酌情采信", "作为定案根据"],answer:0,explanation:"刑事诉讼法规定，采用刑讯逼供等非法方法收集的犯罪嫌疑人、被告人供述和采用暴力、威胁等非法方法收集的证人证言、被害人陈述，应当予以排除，即非法证据排除规则。"},{id:"cs-4322",module:"changshi",prompt:"我国刑事诉讼法规定，犯罪嫌疑人、被告人自愿如实供述自己的罪行，承认指控的犯罪事实，愿意接受处罚的，可以？",options:["依法从宽处理", "依法从重处理", "免除处罚", "加重处罚"],answer:0,explanation:"刑事诉讼法规定，犯罪嫌疑人、被告人自愿如实供述自己的罪行，承认指控的犯罪事实，愿意接受处罚的，可以依法从宽处理，即认罪认罚从宽制度。"},{id:"cs-4323",module:"changshi",prompt:"我国刑事诉讼法规定，基层人民法院管辖的可能判处3年有期徒刑以下刑罚的案件，案件事实清楚，证据确实、充分，被告人认罪认罚并同意适用速裁程序的，可以适用？",options:["速裁程序", "普通程序", "简易程序", "再审程序"],answer:0,explanation:"刑事诉讼法规定，基层人民法院管辖的可能判处3年有期徒刑以下刑罚的案件，案件事实清楚，证据确实、充分，被告人认罪认罚并同意适用速裁程序的，可以适用速裁程序，由审判员1人独任审判。"},{id:"cs-4324",module:"changshi",prompt:"我国刑事诉讼法规定，人民法院审判第一审案件应当公开进行，但是有关国家秘密或者个人隐私的案件，？",options:["不公开审理", "公开审理", "部分公开", "延期审理"],answer:0,explanation:"刑事诉讼法规定，人民法院审判第一审案件应当公开进行；但是有关国家秘密或者个人隐私的案件，不公开审理；涉及商业秘密的案件，当事人申请不公开的，可以不公开审理。"},{id:"cs-4325",module:"changshi",prompt:"我国行政诉讼法规定，人民法院审理行政案件，以法律和行政法规、地方性法规为依据，参照？",options:["规章", "行政法规", "宪法", "国际条约"],answer:0,explanation:"行政诉讼法规定，人民法院审理行政案件，以法律和行政法规、地方性法规为依据，参照规章；认为规章之间不一致的，由最高人民法院送请国务院作出解释或者裁决。"},{id:"cs-4326",module:"changshi",prompt:"我国行政诉讼法规定，证据的种类不包括？",options:["新闻报道", "书证", "物证", "视听资料"],answer:0,explanation:"行政诉讼法规定的证据种类包括书证、物证、视听资料、电子数据、证人证言、当事人的陈述、鉴定意见、勘验笔录、现场笔录；新闻报道不是法定证据种类。"},{id:"cs-4327",module:"changshi",prompt:"我国行政诉讼法规定，人民法院审理行政案件，由谁担任审判长？",options:["审判员", "陪审员", "书记员", "检察官"],answer:0,explanation:"行政诉讼法规定，人民法院审理行政案件，由审判员或者审判员与人民陪审员组成合议庭，审判员担任审判长；合议庭评议案件，实行少数服从多数的原则。"},{id:"cs-4328",module:"changshi",prompt:"我国民事诉讼法规定，当事人申请证据保全的，应当在？",options:["举证期限届满前提出", "开庭后提出", "判决后提出", "上诉时提出"],answer:0,explanation:"民事诉讼法规定，当事人申请证据保全的，应当在举证期限届满前提出；在证据可能灭失或者以后难以取得的情况下，当事人可以在诉讼过程中申请证据保全。"},{id:"cs-4329",module:"changshi",prompt:"法的作用的局限性不包括？",options:["法可以解决一切社会问题", "法的制定和实施受人的因素影响", "法的实施受政治、经济、文化等社会因素的影响", "法自身具有概括性、抽象性等特征"],answer:0,explanation:"法的作用具有局限性，法不能解决一切社会问题，法的制定和实施受人的因素和社会因素的影响，法自身具有概括性、抽象性等特征。"},{id:"cs-4330",module:"changshi",prompt:"我国的法律体系包括宪法及宪法相关法、民法商法、行政法、经济法、社会法、刑法、诉讼与非诉讼程序法等法律部门，其中居于核心地位的是？",options:["宪法", "民法", "刑法", "行政法"],answer:0,explanation:"我国的法律体系中，宪法及宪法相关法居于核心地位，是国家的根本法，具有最高的法律效力。"},{id:"cs-4331",module:"changshi",prompt:"立法权的归属体现的是？",options:["立法体制", "司法体制", "行政体制", "监察体制"],answer:0,explanation:"立法权的归属体现的是立法体制；我国实行统一而又分层次的立法体制，全国人大及其常委会行使国家立法权。"},{id:"cs-4332",module:"changshi",prompt:"法律实施的核心环节是？",options:["法的适用", "法的制定", "法的废止", "法的修改"],answer:0,explanation:"法律实施包括法的遵守、法的执行、法的适用和法的监督；法的适用（司法）是法律实施的核心环节。"},{id:"cs-4333",module:"changshi",prompt:"法律解释的原则不包括？",options:["随意解释原则", "合法性原则", "合理性原则", "整体性原则"],answer:0,explanation:"法律解释的原则包括合法性、合理性、整体性、历史与现实相统一等；随意解释不是法律解释的原则。"},{id:"cs-4334",module:"changshi",prompt:"法治政府建设的要求不包括？",options:["政府权力不受约束", "职能科学、权责法定", "执法严明、公开公正", "廉洁高效、守法诚信"],answer:0,explanation:"法治政府建设要求职能科学、权责法定、执法严明、公开公正、廉洁高效、守法诚信；政府权力不受约束与人治相符，与法治政府要求相悖。"});
(window.YC_CS_BANK=window.YC_CS_BANK||[]).push({id:"cs-4335",module:"changshi",prompt:"从法理学的角度看，法律体系的含义是什么？",options:["一国的全部现行法律规范按照不同的法律部门分类组合而形成的有机整体", "一部法律的条文体系", "法院判决的总和", "法学理论体系"],answer:0,explanation:"法律体系是一国的全部现行法律规范按照不同的法律部门分类组合而形成的有机整体；我国已形成以宪法为核心的中国特色社会主义法律体系。"},{id:"cs-4336",module:"changshi",prompt:"从法理学的角度看，法律监督的客体包括哪些？",options:["一切国家机关、社会组织和公民的守法活动", "仅司法机关", "仅行政机关", "仅公民"],answer:0,explanation:"法律监督的客体是一切国家机关、社会组织和公民的守法活动，重点是监督国家机关及其工作人员的公务活动。"},{id:"cs-4337",module:"changshi",prompt:"从法理学的角度看，法律推理的目的是什么？",options:["为法律适用提供正当理由", "制定法律", "废止法律", "修改法律"],answer:0,explanation:"法律推理的目的是为法律适用提供正当理由，即在具体案件中论证裁判结论的合法性和合理性。"});
(window.YC_CS_BANK=window.YC_CS_BANK||[]).push({id:"cs-4338",module:"changshi",prompt:"我国宪法规定，全国人民代表大会有权制定和修改？",options:["刑事、民事、国家机构的和其他的基本法律", "行政法规", "地方性法规", "部门规章"],answer:0,explanation:"宪法规定，全国人民代表大会有权制定和修改刑事、民事、国家机构的和其他的基本法律；全国人民代表大会常务委员会制定和修改其他法律。"},{id:"cs-4339",module:"changshi",prompt:"我国宪法规定，全国人民代表大会常务委员会有权监督？",options:["国务院、中央军委、国家监察委员会、最高人民法院和最高人民检察院的工作", "仅国务院的工作", "仅地方各级政府的工作", "企业的工作"],answer:0,explanation:"宪法规定，全国人民代表大会常务委员会监督国务院、中央军事委员会、国家监察委员会、最高人民法院和最高人民检察院的工作。"},{id:"cs-4340",module:"changshi",prompt:"我国宪法规定，地方各级人民代表大会在本行政区域内，保证宪法、法律、行政法规的遵守和执行，有权改变或者撤销本级人民代表大会常务委员会不适当的？",options:["决定和命令", "判决", "裁定", "调解书"],answer:0,explanation:"宪法规定，地方各级人民代表大会在本行政区域内，保证宪法、法律、行政法规的遵守和执行，有权改变或者撤销本级人民代表大会常务委员会不适当的决定和命令。"},{id:"cs-4341",module:"changshi",prompt:"我国宪法规定，人民法院依照法律规定独立行使？",options:["审判权，不受行政机关、社会团体和个人的干涉", "检察权", "监察权", "立法权"],answer:0,explanation:"宪法规定，人民法院依照法律规定独立行使审判权，不受行政机关、社会团体和个人的干涉；人民检察院依照法律规定独立行使检察权。"},{id:"cs-4342",module:"changshi",prompt:"我国宪法规定，最高人民法院监督？",options:["地方各级人民法院和专门人民法院的审判工作", "人民检察院的工作", "公安机关的工作", "监察委员会的工作"],answer:0,explanation:"宪法规定，最高人民法院监督地方各级人民法院和专门人民法院的审判工作，上级人民法院监督下级人民法院的审判工作。"},{id:"cs-4343",module:"changshi",prompt:"我国宪法规定，全国人民代表大会代表应当同原选举单位和人民保持密切的联系，听取和反映人民的意见和要求，努力为人民服务，这是代表的？",options:["义务", "权利", "职权", "待遇"],answer:0,explanation:"宪法规定，全国人民代表大会代表应当同原选举单位和人民保持密切的联系，听取和反映人民的意见和要求，努力为人民服务，这是代表的义务。"},{id:"cs-4344",module:"changshi",prompt:"我国宪法规定，中华人民共和国公民有依照法律服兵役和参加民兵组织的义务，这是公民的？",options:["基本义务", "基本权利", "政治权利", "人身自由"],answer:0,explanation:"宪法规定，依照法律服兵役和参加民兵组织是中华人民共和国公民的光荣义务，属于公民的基本义务。"},{id:"cs-4345",module:"changshi",prompt:"我国宪法规定，国家保护社会主义的公共财产，禁止任何组织或者个人用任何手段侵占或者？",options:["破坏国家的和集体的财产", "使用公共财产", "管理公共财产", "监督公共财产"],answer:0,explanation:"宪法规定，社会主义的公共财产神圣不可侵犯；国家保护社会主义的公共财产，禁止任何组织或者个人用任何手段侵占或者破坏国家的和集体的财产。"},{id:"cs-4346",module:"changshi",prompt:"因债务人怠于行使其债权或者与该债权有关的从权利，影响债权人的到期债权实现的，债权人可以向人民法院请求以自己的名义代位行使债务人对相对人的权利，这被称为？",options:["代位权", "撤销权", "解除权", "抗辩权"],answer:0,explanation:"民法规定，因债务人怠于行使其债权或者与该债权有关的从权利，影响债权人的到期债权实现的，债权人可以向人民法院请求以自己的名义代位行使债务人对相对人的权利，即代位权。"},{id:"cs-4347",module:"changshi",prompt:"债务人以放弃其债权、放弃债权担保、无偿转让财产等方式无偿处分财产权益，或者恶意延长其到期债权的履行期限，影响债权人的债权实现的，债权人可以请求人民法院？",options:["撤销债务人的行为", "解除合同", "宣告合同无效", "变更合同"],answer:0,explanation:"民法规定，债务人以放弃其债权、放弃债权担保、无偿转让财产等方式无偿处分财产权益，影响债权人的债权实现的，债权人可以请求人民法院撤销债务人的行为，即撤销权。"},{id:"cs-4348",module:"changshi",prompt:"得利人没有法律根据取得不当利益的，受损失的人可以请求得利人？",options:["返还取得的利益", "赔偿双倍损失", "支付违约金", "承担刑事责任"],answer:0,explanation:"民法规定，得利人没有法律根据取得不当利益的，受损失的人可以请求得利人返还取得的利益，即不当得利返还请求权。"},{id:"cs-4349",module:"changshi",prompt:"管理人没有法定的或者约定的义务，为避免他人利益受损失而管理他人事务的，可以请求受益人偿还因管理事务而支出的必要费用，这被称为？",options:["无因管理", "不当得利", "侵权行为", "合同行为"],answer:0,explanation:"民法规定，管理人没有法定的或者约定的义务，为避免他人利益受损失而管理他人事务的，可以请求受益人偿还因管理事务而支出的必要费用，即无因管理。"},{id:"cs-4350",module:"changshi",prompt:"个人之间形成劳务关系，提供劳务一方因劳务造成他人损害的，由谁承担侵权责任？",options:["接受劳务一方承担侵权责任，接受劳务一方承担侵权责任后，可以向有故意或者重大过失的提供劳务一方追偿", "提供劳务一方承担", "双方共同承担", "受害人自担"],answer:0,explanation:"民法典规定，个人之间形成劳务关系，提供劳务一方因劳务造成他人损害的，由接受劳务一方承担侵权责任；接受劳务一方承担侵权责任后，可以向有故意或者重大过失的提供劳务一方追偿。"},{id:"cs-4351",module:"changshi",prompt:"土地承包经营权自土地承包经营权合同生效时？",options:["设立", "登记时设立", "交付时设立", "公告时设立"],answer:0,explanation:"民法典规定，土地承包经营权自土地承包经营权合同生效时设立；土地承包经营权的期限，耕地为30年，草地为30年至50年，林地为30年至70年。"},{id:"cs-4352",module:"changshi",prompt:"建设用地使用权自登记时？",options:["设立", "合同生效时设立", "交付时设立", "公告时设立"],answer:0,explanation:"民法典规定，建设用地使用权自登记时设立；建设用地使用权可以在土地的地表、地上或者地下分别设立。"},{id:"cs-4353",module:"changshi",prompt:"地役权自地役权合同生效时设立，当事人要求登记的，可以向登记机构申请地役权登记，未经登记，不得对抗？",options:["善意第三人", "合同相对人", "所有人", "使用人"],answer:0,explanation:"民法典规定，地役权自地役权合同生效时设立；当事人要求登记的，可以向登记机构申请地役权登记；未经登记，不得对抗善意第三人。"},{id:"cs-4354",module:"changshi",prompt:"抵押权人为债权人的，债务人不履行到期债务或者发生当事人约定的实现抵押权的情形，债权人有权就该财产？",options:["优先受偿", "直接占有", "直接拍卖", "直接变卖"],answer:0,explanation:"民法典规定，为担保债务的履行，债务人或者第三人不转移财产的占有，将该财产抵押给债权人的，债务人不履行到期债务或者发生当事人约定的实现抵押权的情形，债权人有权就该财产优先受偿。"},{id:"cs-4355",module:"changshi",prompt:"企业、个体工商户、农业生产经营者可以将现有的以及将有的生产设备、原材料、半成品、产品抵押，这被称为？",options:["浮动抵押", "固定抵押", "最高额抵押", "动产质押"],answer:0,explanation:"民法典规定，企业、个体工商户、农业生产经营者可以将现有的以及将有的生产设备、原材料、半成品、产品抵押，即浮动抵押；浮动抵押自抵押合同生效时设立，未经登记不得对抗善意第三人。"},{id:"cs-4356",module:"changshi",prompt:"为担保债务的履行，债务人或者第三人不转移财产的占有，将该财产质押给债权人的，这被称为？",options:["动产质押", "动产抵押", "权利质押", "留置"],answer:0,explanation:"民法典规定，为担保债务的履行，债务人或者第三人将其动产出质给债权人占有的，债务人不履行到期债务或者发生当事人约定的实现质权的情形，债权人有权就该动产优先受偿，即动产质押。"},{id:"cs-4357",module:"changshi",prompt:"留置权成立的条件不包括？",options:["债权人任意占有债务人的财产", "债权人合法占有债务人的动产", "债务已届清偿期", "债权与动产的占有属于同一法律关系"],answer:0,explanation:"留置权的成立条件包括债权人合法占有债务人的动产、债务已届清偿期、债权与动产的占有属于同一法律关系（企业之间留置除外）；债权人任意占有债务人的财产不能成立留置权。"},{id:"cs-4358",module:"changshi",prompt:"最高额抵押权是为担保债务的履行，债务人或者第三人对一定期间内将要连续发生的债权提供担保财产的，债务人不履行到期债务或者发生当事人约定的实现抵押权的情形的，抵押权人有权在？",options:["最高债权额限度内就该担保财产优先受偿", "全部债权范围内受偿", "任意范围内受偿", "最低债权额内受偿"],answer:0,explanation:"民法典规定，最高额抵押权是债务人对一定期间内将要连续发生的债权提供担保财产，债务人不履行到期债务的，抵押权人有权在最高债权额限度内就该担保财产优先受偿。"},{id:"cs-4359",module:"changshi",prompt:"放火、决水、爆炸以及投放毒害性、放射性、传染病病原体等物质或者以其他危险方法危害公共安全，尚未造成严重后果的，处？",options:["3年以上10年以下有期徒刑", "10年以上有期徒刑", "死刑", "无期徒刑"],answer:0,explanation:"刑法规定，放火、决水、爆炸以及投放危险物质危害公共安全，尚未造成严重后果的，处3年以上10年以下有期徒刑；致人重伤、死亡或者使公私财产遭受重大损失的，处10年以上有期徒刑、无期徒刑或者死刑。"},{id:"cs-4360",module:"changshi",prompt:"破坏火车、汽车、电车、船只、航空器，足以使火车、汽车、电车、船只、航空器发生倾覆、毁坏危险，尚未造成严重后果的，构成？",options:["破坏交通工具罪", "交通肇事罪", "危险驾驶罪", "故意毁坏财物罪"],answer:0,explanation:"破坏交通工具罪是破坏火车、汽车、电车、船只、航空器，足以使其发生倾覆、毁坏危险，尚未造成严重后果的行为；造成严重后果的，处更重刑罚。"},{id:"cs-4361",module:"changshi",prompt:"生产者、销售者在产品中掺杂、掺假，以假充真，以次充好或者以不合格产品冒充合格产品，销售金额5万元以上的，构成？",options:["生产、销售伪劣产品罪", "生产、销售有毒、有害食品罪", "诈骗罪", "非法经营罪"],answer:0,explanation:"生产、销售伪劣产品罪是生产者、销售者在产品中掺杂、掺假，以假充真，以次充好或者以不合格产品冒充合格产品，销售金额5万元以上的行为。"},{id:"cs-4362",module:"changshi",prompt:"在生产、销售的食品中掺入有毒、有害的非食品原料的，或者销售明知掺有有毒、有害的非食品原料的食品的，构成？",options:["生产、销售有毒、有害食品罪", "生产、销售伪劣产品罪", "生产、销售不符合安全标准的食品罪", "诈骗罪"],answer:0,explanation:"生产、销售有毒、有害食品罪是在生产、销售的食品中掺入有毒、有害的非食品原料的，或者销售明知掺有有毒、有害的非食品原料的食品的行为。"},{id:"cs-4363",module:"changshi",prompt:"违反海关法规，逃避海关监管，运输、携带、邮寄国家禁止进出境的物品进出境的，构成？",options:["走私罪", "偷税罪", "非法经营罪", "诈骗罪"],answer:0,explanation:"走私罪是违反海关法规，逃避海关监管，运输、携带、邮寄国家禁止进出境的物品或者依法应当缴纳税款的货物、物品进出境的行为。"},{id:"cs-4364",module:"changshi",prompt:"为他人虚开、为自己虚开、让他人为自己虚开、介绍他人虚开增值税专用发票的，构成？",options:["虚开增值税专用发票罪", "偷税罪", "诈骗罪", "非法经营罪"],answer:0,explanation:"虚开增值税专用发票罪是为他人虚开、为自己虚开、让他人为自己虚开、介绍他人虚开增值税专用发票的行为。"},{id:"cs-4365",module:"changshi",prompt:"违反国家规定，从事非法经营活动，扰乱市场秩序，情节严重的，构成？",options:["非法经营罪", "生产销售伪劣产品罪", "诈骗罪", "偷税罪"],answer:0,explanation:"非法经营罪是违反国家规定，从事非法经营活动，扰乱市场秩序，情节严重的行为，如未经许可经营专营专卖物品、买卖进出口许可证等。"},{id:"cs-4366",module:"changshi",prompt:"组织、领导以推销商品、提供服务等经营活动为名，要求参加者缴纳费用或者购买商品、服务等方式获得加入资格，并按照一定顺序组成层级，直接或者间接以发展人员的数量作为计酬或者返利依据，引诱、胁迫参加者继续发展他人参加，骗取财物，扰乱经济社会秩序的，构成？",options:["组织、领导传销活动罪", "诈骗罪", "非法经营罪", "集资诈骗罪"],answer:0,explanation:"组织、领导传销活动罪是以推销商品、提供服务等经营活动为名，要求参加者缴纳费用或者购买商品服务获得加入资格，按照一定顺序组成层级，以发展人员数量作为计酬返利依据，骗取财物的行为。"},{id:"cs-4367",module:"changshi",prompt:"犯罪分子虽不具有自首情节，但是如实供述自己罪行的，可以从轻处罚，这被称为？",options:["坦白", "自首", "立功", "中止"],answer:0,explanation:"刑法规定，犯罪分子虽不具有自首情节，但是如实供述自己罪行的，可以从轻处罚；因其如实供述自己罪行，避免特别严重后果发生的，可以减轻处罚，即坦白从宽。"},{id:"cs-4368",module:"changshi",prompt:"对正在进行行凶、杀人、抢劫、强奸、绑架以及其他严重危及人身安全的暴力犯罪，采取防卫行为，造成不法侵害人伤亡的，不属于防卫过当，不负刑事责任，这被称为？",options:["特殊防卫", "正当防卫", "紧急避险", "假想防卫"],answer:0,explanation:"刑法规定，对正在进行行凶、杀人、抢劫、强奸、绑架以及其他严重危及人身安全的暴力犯罪，采取防卫行为，造成不法侵害人伤亡的，不属于防卫过当，不负刑事责任，即特殊防卫（无限防卫权）。"},{id:"cs-4369",module:"changshi",prompt:"我国刑法规定，犯罪经过下列期限不再追诉，法定最高刑为无期徒刑、死刑的，经过？",options:["20年", "15年", "10年", "25年"],answer:0,explanation:"刑法规定，法定最高刑为无期徒刑、死刑的，经过20年不再追诉；如果20年以后认为必须追诉的，须报请最高人民检察院核准。"},{id:"cs-4370",module:"changshi",prompt:"我国刑法规定，追诉期限从犯罪之日起计算，犯罪行为有连续或者继续状态的，从？",options:["犯罪行为终了之日起计算", "犯罪之日起计算", "发现之日起计算", "立案之日起计算"],answer:0,explanation:"刑法规定，追诉期限从犯罪之日起计算；犯罪行为有连续或者继续状态的，从犯罪行为终了之日起计算。"},{id:"cs-4371",module:"changshi",prompt:"我国刑法规定，在追诉期限以内又犯罪的，前罪追诉的期限从？",options:["犯后罪之日起计算", "犯前罪之日起计算", "后罪判决之日起计算", "前罪判决之日起计算"],answer:0,explanation:"刑法规定，在追诉期限以内又犯罪的，前罪追诉的期限从犯后罪之日起计算。"},{id:"cs-4372",module:"changshi",prompt:"我国刑法规定，对于犯罪的外国人，可以独立适用或者附加适用？",options:["驱逐出境", "罚款", "没收财产", "剥夺政治权利"],answer:0,explanation:"刑法规定，对于犯罪的外国人，可以独立适用或者附加适用驱逐出境；驱逐出境是专门适用于犯罪的外国人的附加刑。"},{id:"cs-4373",module:"changshi",prompt:"我国刑法规定，由于不能抗拒的原因或者不能预见的原因引起的行为，不是犯罪，这被称为？",options:["意外事件", "过失犯罪", "故意犯罪", "不可抗力免责"],answer:0,explanation:"刑法规定，行为在客观上虽然造成了损害结果，但是不是出于故意或者过失，而是由于不能抗拒或者不能预见的原因所引起的，不是犯罪，即意外事件。"},{id:"cs-4374",module:"changshi",prompt:"我国行政复议法规定，公民、法人或者其他组织认为行政机关的具体行政行为所依据的规定不合法，在对具体行政行为申请行政复议时，可以？",options:["一并提出对该规定的审查申请", "直接起诉该规定", "拒绝履行", "自行废止该规定"],answer:0,explanation:"行政复议法规定，公民、法人或者其他组织认为行政机关的具体行政行为所依据的规章以下的规定不合法，在对具体行政行为申请行政复议时，可以一并提出对该规定的审查申请。"},{id:"cs-4375",module:"changshi",prompt:"我国行政复议法规定，行政复议机关负责法制工作的机构应当自行政复议申请受理之日起多少日内，将行政复议申请书副本或者行政复议申请笔录复印件发送被申请人？",options:["7日", "5日", "10日", "15日"],answer:0,explanation:"行政复议法规定，行政复议机关负责法制工作的机构应当自行政复议申请受理之日起7日内，将行政复议申请书副本或者行政复议申请笔录复印件发送被申请人。"},{id:"cs-4376",module:"changshi",prompt:"我国行政复议法规定，被申请人应当自收到行政复议申请书副本或者行政复议申请笔录复印件之日起多少日内，提出书面答复？",options:["10日", "7日", "15日", "30日"],answer:0,explanation:"行政复议法规定，被申请人应当自收到行政复议申请书副本或者行政复议申请笔录复印件之日起10日内，提出书面答复，并提交当初作出具体行政行为的证据、依据和其他有关材料。"},{id:"cs-4377",module:"changshi",prompt:"我国行政诉讼法规定，行政案件由最初作出行政行为的行政机关所在地人民法院管辖，这被称为？",options:["原告就被告原则", "被告就原告原则", "专属管辖", "协议管辖"],answer:0,explanation:"行政诉讼法规定，行政案件由最初作出行政行为的行政机关所在地人民法院管辖，即原告就被告原则；经复议的案件，也可以由复议机关所在地人民法院管辖。"},{id:"cs-4378",module:"changshi",prompt:"我国行政诉讼法规定，对国务院部门或者县级以上地方人民政府所作的行政行为提起诉讼的案件，由哪一级人民法院管辖？",options:["中级人民法院", "基层人民法院", "高级人民法院", "最高人民法院"],answer:0,explanation:"行政诉讼法规定，对国务院部门或者县级以上地方人民政府所作的行政行为提起诉讼的案件，由中级人民法院管辖。"},{id:"cs-4379",module:"changshi",prompt:"我国行政诉讼法规定，人民法院经审理认为行政行为证据确凿，适用法律、法规正确，符合法定程序的，判决？",options:["驳回原告的诉讼请求", "撤销行政行为", "确认违法", "变更行政行为"],answer:0,explanation:"行政诉讼法规定，人民法院经审理认为行政行为证据确凿，适用法律、法规正确，符合法定程序的，或者原告申请被告履行法定职责或者给付义务理由不成立的，判决驳回原告的诉讼请求。"},{id:"cs-4380",module:"changshi",prompt:"我国行政诉讼法规定，行政行为有下列情形之一的，人民法院判决撤销或者部分撤销，并可以判决被告重新作出行政行为，其中包括？",options:["主要证据不足的", "证据确凿的", "程序合法的", "适用法律正确的"],answer:0,explanation:"行政诉讼法规定，行政行为主要证据不足、适用法律法规错误、违反法定程序、超越职权、滥用职权、明显不当的，人民法院判决撤销或者部分撤销，并可以判决被告重新作出行政行为。"},{id:"cs-4381",module:"changshi",prompt:"我国国家赔偿法规定，赔偿请求人要求赔偿，应当先向谁提出？",options:["赔偿义务机关提出，也可以在申请行政复议或者提起行政诉讼时一并提出", "人民法院直接提出", "人民检察院提出", "监察委员会提出"],answer:0,explanation:"国家赔偿法规定，赔偿请求人要求赔偿，应当先向赔偿义务机关提出，也可以在申请行政复议或者提起行政诉讼时一并提出。"},{id:"cs-4382",module:"changshi",prompt:"我国国家赔偿法规定，赔偿义务机关应当自收到申请之日起2个月内作出是否赔偿的决定，赔偿义务机关作出赔偿决定，应当充分听取赔偿请求人的意见，并可以与赔偿请求人？",options:["就赔偿方式、赔偿项目和赔偿数额依法进行协商", "讨价还价", "拒绝协商", "强制决定"],answer:0,explanation:"国家赔偿法规定，赔偿义务机关作出赔偿决定，应当充分听取赔偿请求人的意见，并可以与赔偿请求人就赔偿方式、赔偿项目和赔偿数额依法进行协商。"},{id:"cs-4383",module:"changshi",prompt:"我国国家赔偿法规定，赔偿义务机关赔偿后，应当责令有故意或者重大过失的工作人员或者受委托的组织或者个人承担？",options:["部分或者全部赔偿费用", "全部赔偿费用", "部分赔偿费用", "不承担费用"],answer:0,explanation:"国家赔偿法规定，赔偿义务机关赔偿后，应当责令有故意或者重大过失的工作人员或者受委托的组织或者个人承担部分或者全部赔偿费用；对有故意或者重大过失的责任人员，有关机关应当依法给予处分。"},{id:"cs-4384",module:"changshi",prompt:"我国行政强制法规定，行政机关作出强制执行决定前，应当事先？",options:["催告当事人履行义务", "直接强制执行", "申请法院执行", "公告执行"],answer:0,explanation:"行政强制法规定，行政机关作出强制执行决定前，应当事先催告当事人履行义务；催告应当以书面形式作出，并载明履行义务的期限、方式、金额和给付方式等。"},{id:"cs-4385",module:"changshi",prompt:"我国行政强制法规定，经催告，当事人逾期仍不履行行政决定，且无正当理由的，行政机关可以作出？",options:["强制执行决定", "行政处罚决定", "刑事处罚决定", "行政拘留决定"],answer:0,explanation:"行政强制法规定，经催告，当事人逾期仍不履行行政决定，且无正当理由的，行政机关可以作出强制执行决定；强制执行决定应当以书面形式作出。"},{id:"cs-4386",module:"changshi",prompt:"我国公务员法规定，公务员晋升领导职务的，应当按照有关规定实行？",options:["任职前公示制度和任职试用期制度", "终身任职制度", "世袭制度", "直接任命制度"],answer:0,explanation:"公务员法规定，公务员晋升领导职务的，应当按照有关规定实行任职前公示制度和任职试用期制度。"},{id:"cs-4387",module:"changshi",prompt:"我国劳动合同法规定，用人单位违法解除或者终止劳动合同，劳动者要求继续履行劳动合同的，用人单位应当？",options:["继续履行", "支付赔偿金", "支付违约金", "支付补偿金"],answer:0,explanation:"劳动合同法规定，用人单位违法解除或者终止劳动合同，劳动者要求继续履行劳动合同的，用人单位应当继续履行；劳动者不要求继续履行或者劳动合同已经不能继续履行的，用人单位应当依照规定支付赔偿金。"},{id:"cs-4388",module:"changshi",prompt:"我国劳动合同法规定，用人单位违法解除或者终止劳动合同，劳动者不要求继续履行或者劳动合同已经不能继续履行的，用人单位应当依照经济补偿标准的多少向劳动者支付赔偿金？",options:["2倍", "1倍", "3倍", "5倍"],answer:0,explanation:"劳动合同法规定，用人单位违法解除或者终止劳动合同的，应当依照经济补偿标准的2倍向劳动者支付赔偿金。"},{id:"cs-4389",module:"changshi",prompt:"我国劳动合同法规定，除劳动者违反服务期约定或者违反竞业限制约定的情形外，用人单位不得与劳动者约定由劳动者承担？",options:["违约金", "赔偿金", "补偿金", "罚款"],answer:0,explanation:"劳动合同法规定，除劳动者违反服务期约定或者违反竞业限制约定的情形外，用人单位不得与劳动者约定由劳动者承担违约金。"},{id:"cs-4390",module:"changshi",prompt:"我国劳动合同法规定，被派遣劳动者享有与用工单位的劳动者？",options:["同工同酬的权利", "不同的报酬", "更低的报酬", "更高的报酬"],answer:0,explanation:"劳动合同法规定，被派遣劳动者享有与用工单位的劳动者同工同酬的权利；用工单位应当按照同工同酬原则，对被派遣劳动者与本单位同类岗位的劳动者实行相同的劳动报酬分配办法。"},{id:"cs-4391",module:"changshi",prompt:"我国劳动合同法规定，用人单位与劳动者协商一致，可以订立？",options:["固定期限劳动合同、无固定期限劳动合同和以完成一定工作任务为期限的劳动合同", "仅固定期限劳动合同", "仅无固定期限劳动合同", "仅口头劳动合同"],answer:0,explanation:"劳动合同法规定，用人单位与劳动者协商一致，可以订立固定期限劳动合同、无固定期限劳动合同和以完成一定工作任务为期限的劳动合同。"},{id:"cs-4392",module:"changshi",prompt:"我国工会法规定，工会是？",options:["职工自愿结合的工人阶级的群众组织", "行政机关", "企业内部机构", "政党组织"],answer:0,explanation:"工会法规定，工会是职工自愿结合的工人阶级的群众组织；中华全国总工会及其各工会组织代表职工的利益，依法维护职工的合法权益。"},{id:"cs-4393",module:"changshi",prompt:"我国工会法规定，企业、事业单位、社会组织违反劳动法律、法规规定，侵犯职工劳动权益的，工会可以？",options:["要求企业、事业单位、社会组织采取措施予以改正", "直接处罚", "直接辞退负责人", "直接停产"],answer:0,explanation:"工会法规定，企业、事业单位、社会组织违反劳动法律、法规规定，侵犯职工劳动权益的，工会可以要求企业、事业单位、社会组织采取措施予以改正；拒不改正的，工会可以提请当地人民政府依法作出处理。"},{id:"cs-4394",module:"changshi",prompt:"我国劳动合同法规定，用人单位应当依法建立和完善劳动规章制度，保障劳动者享有劳动权利、履行？",options:["劳动义务", "劳动权利", "劳动报酬", "劳动保险"],answer:0,explanation:"劳动合同法规定，用人单位应当依法建立和完善劳动规章制度，保障劳动者享有劳动权利、履行劳动义务。"},{id:"cs-4395",module:"changshi",prompt:"我国劳动合同法规定，用人单位与劳动者建立劳动关系，应当订立？",options:["书面劳动合同", "口头劳动合同", "电子合同", "集体合同"],answer:0,explanation:"劳动合同法规定，建立劳动关系，应当订立书面劳动合同；已建立劳动关系，未同时订立书面劳动合同的，应当自用工之日起1个月内订立书面劳动合同。"},{id:"cs-4396",module:"changshi",prompt:"我国劳动合同法规定，用人单位自用工之日起1个月内应当与劳动者订立书面劳动合同，超过1个月不满1年未订立的，应当？",options:["每月支付2倍工资", "每月支付3倍工资", "支付补偿金", "无需承担责任"],answer:0,explanation:"劳动合同法规定，用人单位自用工之日起超过1个月不满1年未与劳动者订立书面劳动合同的，应当向劳动者每月支付2倍的工资。"},{id:"cs-4397",module:"changshi",prompt:"我国劳动合同法规定，劳动者拒绝用人单位管理人员违章指挥、强令冒险作业的，？",options:["不视为违反劳动合同", "视为违反劳动合同", "可以解除劳动合同", "应当赔偿"],answer:0,explanation:"劳动合同法规定，劳动者拒绝用人单位管理人员违章指挥、强令冒险作业的，不视为违反劳动合同；劳动者对危害生命安全和身体健康的劳动条件，有权对用人单位提出批评、检举和控告。"},{id:"cs-4398",module:"changshi",prompt:"我国劳动合同法规定，用人单位发生合并或者分立等情况，原劳动合同？",options:["继续有效，劳动合同由承继其权利和义务的用人单位继续履行", "自动终止", "重新签订", "无效"],answer:0,explanation:"劳动合同法规定，用人单位发生合并或者分立等情况，原劳动合同继续有效，劳动合同由承继其权利和义务的用人单位继续履行。"},{id:"cs-4399",module:"changshi",prompt:"我国反垄断法规定，经营者集中具有或者可能具有排除、限制竞争效果的，国务院反垄断执法机构应当作出？",options:["禁止经营者集中的决定", "批准经营者集中的决定", "不予受理的决定", "延期审查的决定"],answer:0,explanation:"反垄断法规定，经营者集中具有或者可能具有排除、限制竞争效果的，国务院反垄断执法机构应当作出禁止经营者集中的决定；但是，经营者能够证明该集中对竞争产生的有利影响明显大于不利影响，或者符合社会公共利益的，可以作出不予禁止的决定。"},{id:"cs-4400",module:"changshi",prompt:"我国反垄断法规定，国务院反垄断执法机构应当自收到经营者提交的申报文件、资料之日起多少日内，对申报的经营者集中进行初步审查？",options:["30日", "20日", "60日", "90日"],answer:0,explanation:"反垄断法规定，国务院反垄断执法机构应当自收到经营者提交的申报文件、资料之日起30日内，对申报的经营者集中进行初步审查，作出是否实施进一步审查的决定。"},{id:"cs-4401",module:"changshi",prompt:"我国反垄断法规定，对经营者集中实施进一步审查的，应当自决定之日起多少日内审查完毕？",options:["90日", "30日", "60日", "120日"],answer:0,explanation:"反垄断法规定，国务院反垄断执法机构决定实施进一步审查的，应当自决定之日起90日内审查完毕，作出是否禁止经营者集中的决定。"},{id:"cs-4402",module:"changshi",prompt:"我国消费者权益保护法规定，经营者以预收款方式提供商品或者服务的，应当按照约定提供；未按照约定提供的，消费者可以要求经营者按照约定履行或者？",options:["退回预付款，并应当承担预付款的利息、消费者必须支付的合理费用", "仅退回预付款", "不退预付款", "加倍退款"],answer:0,explanation:"消费者权益保护法规定，经营者以预收款方式提供商品或者服务，未按照约定提供的，消费者可以要求经营者按照约定履行或者退回预付款，并应当承担预付款的利息、消费者必须支付的合理费用。"},{id:"cs-4403",module:"changshi",prompt:"我国消费者权益保护法规定，使用他人营业执照的违法经营者提供商品或者服务，损害消费者合法权益的，消费者可以向其要求赔偿，也可以向？",options:["营业执照的持有人要求赔偿", "监管部门要求赔偿", "生产者要求赔偿", "平台要求赔偿"],answer:0,explanation:"消费者权益保护法规定，使用他人营业执照的违法经营者提供商品或者服务，损害消费者合法权益的，消费者可以向其要求赔偿，也可以向营业执照的持有人要求赔偿。"},{id:"cs-4404",module:"changshi",prompt:"我国食品安全法规定，发生食品安全事故的单位应当立即采取措施，防止事故扩大，并立即向当地？",options:["食品安全监督管理等部门报告", "人民法院报告", "公安机关报告", "监察委员会报告"],answer:0,explanation:"食品安全法规定，发生食品安全事故的单位应当立即采取措施，防止事故扩大，事故发生单位和接收病人进行治疗的单位应当及时向事故发生地县级食品安全监督管理、卫生行政部门报告。"},{id:"cs-4405",module:"changshi",prompt:"我国食品安全法规定，食品生产经营者未依照规定召回或者停止经营的，县级以上人民政府食品安全监督管理部门可以？",options:["责令其召回或者停止经营", "直接没收", "直接销毁", "直接处罚"],answer:0,explanation:"食品安全法规定，食品生产经营者未依照本条规定召回或者停止经营的，县级以上人民政府食品安全监督管理部门可以责令其召回或者停止经营。"},{id:"cs-4406",module:"changshi",prompt:"我国广告法规定，违反本法规定，发布虚假广告，欺骗、误导消费者，使购买商品或者接受服务的消费者的合法权益受到损害的，由谁承担责任？",options:["广告主依法承担民事责任；广告经营者、广告发布者不能提供广告主的真实名称、地址和有效联系方式的，消费者可以要求广告经营者、广告发布者先行赔偿", "仅广告主承担责任", "仅广告发布者承担责任", "消费者自担"],answer:0,explanation:"广告法规定，发布虚假广告欺骗、误导消费者，使消费者合法权益受到损害的，广告主依法承担民事责任；广告经营者、广告发布者不能提供广告主的真实名称、地址和有效联系方式的，消费者可以要求其先行赔偿。"},{id:"cs-4407",module:"changshi",prompt:"我国税收征收管理法规定，纳税人必须依照法律、行政法规规定或者税务机关依照法律、行政法规的规定确定的申报期限、申报内容？",options:["如实办理纳税申报", "自行决定是否申报", "延迟申报", "免于申报"],answer:0,explanation:"税收征收管理法规定，纳税人必须依照法律、行政法规规定或者税务机关依照法律、行政法规的规定确定的申报期限、申报内容如实办理纳税申报，报送纳税申报表、财务会计报表以及税务机关根据实际需要要求纳税人报送的其他纳税资料。"},{id:"cs-4408",module:"changshi",prompt:"我国税收征收管理法规定，纳税人、扣缴义务人有权要求税务机关为其保密的情况不包括？",options:["纳税人的税收违法行为", "纳税人、扣缴义务人的商业秘密", "纳税人、扣缴义务人的个人隐私", "纳税人、扣缴义务人的财务信息"],answer:0,explanation:"税收征收管理法规定，纳税人、扣缴义务人有权要求税务机关为其保密的是商业秘密和个人隐私；税收违法行为不属于保密范围。"},{id:"cs-4409",module:"changshi",prompt:"我国反不正当竞争法规定，经营者违反本法规定，给被侵害的经营者造成损害的，应当承担？",options:["损害赔偿责任，被侵害的经营者的损失难以计算的，赔偿额为侵权人在侵权期间因侵权所获得的利润", "双倍赔偿", "三倍赔偿", "不承担责任"],answer:0,explanation:"反不正当竞争法规定，经营者违反本法规定，给被侵害的经营者造成损害的，应当承担损害赔偿责任；被侵害的经营者的损失难以计算的，赔偿额为侵权人在侵权期间因侵权所获得的利润，并应当承担被侵害的经营者因调查该经营者侵害其合法权益的不正当竞争行为所支付的合理费用。"},{id:"cs-4410",module:"changshi",prompt:"我国反不正当竞争法规定，经营者不得实施下列混淆行为，引人误认为是他人商品或者与他人存在特定联系，其中包括？",options:["擅自使用与他人有一定影响的商品名称、包装、装潢等相同或者近似的标识", "使用自己的商标", "使用自己的包装", "使用自己的名称"],answer:0,explanation:"反不正当竞争法规定，经营者不得擅自使用与他人有一定影响的商品名称、包装、装潢等相同或者近似的标识，擅自使用他人有一定影响的企业名称、社会组织名称、姓名等，引人误认为是他人商品或者与他人存在特定联系。"},{id:"cs-4411",module:"changshi",prompt:"我国民事诉讼法规定，人民法院受理案件后，当事人对管辖权有异议的，应当在？",options:["提交答辩状期间提出", "开庭后提出", "判决前提出", "上诉时提出"],answer:0,explanation:"民事诉讼法规定，人民法院受理案件后，当事人对管辖权有异议的，应当在提交答辩状期间提出；人民法院对当事人提出的异议，应当审查，异议成立的，裁定将案件移送有管辖权的人民法院。"},{id:"cs-4412",module:"changshi",prompt:"我国民事诉讼法规定，原告经传票传唤，无正当理由拒不到庭的，或者未经法庭许可中途退庭的，可以？",options:["按撤诉处理", "缺席判决", "中止审理", "延期审理"],answer:0,explanation:"民事诉讼法规定，原告经传票传唤，无正当理由拒不到庭的，或者未经法庭许可中途退庭的，可以按撤诉处理；被告反诉的，可以缺席判决。"},{id:"cs-4413",module:"changshi",prompt:"我国民事诉讼法规定，被告经传票传唤，无正当理由拒不到庭的，或者未经法庭许可中途退庭的，可以？",options:["缺席判决", "按撤诉处理", "拘传", "中止审理"],answer:0,explanation:"民事诉讼法规定，被告经传票传唤，无正当理由拒不到庭的，或者未经法庭许可中途退庭的，可以缺席判决。"},{id:"cs-4414",module:"changshi",prompt:"我国民事诉讼法规定，宣判前，原告申请撤诉的，是否准许，由人民法院？",options:["裁定", "判决", "决定", "通知"],answer:0,explanation:"民事诉讼法规定，宣判前，原告申请撤诉的，是否准许，由人民法院裁定；人民法院裁定不准许撤诉的，原告经传票传唤，无正当理由拒不到庭的，可以缺席判决。"},{id:"cs-4415",module:"changshi",prompt:"我国民事诉讼法规定，有下列情形之一的，中止诉讼，其中包括？",options:["一方当事人死亡，需要等待继承人表明是否参加诉讼的", "一方当事人死亡，没有继承人的", "一方当事人放弃诉讼的", "双方达成和解的"],answer:0,explanation:"民事诉讼法规定，一方当事人死亡，需要等待继承人表明是否参加诉讼的；一方当事人丧失诉讼行为能力，尚未确定法定代理人的等，中止诉讼；中止诉讼的原因消除后，恢复诉讼。"},{id:"cs-4416",module:"changshi",prompt:"我国刑事诉讼法规定，被害人由于被告人的犯罪行为而遭受物质损失的，在刑事诉讼过程中，有权提起？",options:["附带民事诉讼", "反诉", "上诉", "申诉"],answer:0,explanation:"刑事诉讼法规定，被害人由于被告人的犯罪行为而遭受物质损失的，在刑事诉讼过程中，有权提起附带民事诉讼；附带民事诉讼应当同刑事案件一并审判。"},{id:"cs-4417",module:"changshi",prompt:"我国刑事诉讼法规定，当事人及其法定代理人、近亲属的申诉符合下列情形之一的，人民法院应当重新审判，其中包括？",options:["有新的证据证明原判决、裁定认定的事实确有错误的", "原判决正确的", "程序合法的", "证据充分的"],answer:0,explanation:"刑事诉讼法规定，有新的证据证明原判决、裁定认定的事实确有错误，可能影响定罪量刑的；据以定罪量刑的证据不确实、不充分等，人民法院应当重新审判，即审判监督程序。"},{id:"cs-4418",module:"changshi",prompt:"我国刑事诉讼法规定，下列判决和裁定是发生法律效力的判决和裁定，其中包括？",options:["超过法定期限没有上诉、抗诉的判决和裁定", "一审未生效的判决", "二审审理中的裁定", "发回重审的裁定"],answer:0,explanation:"刑事诉讼法规定，发生法律效力的判决和裁定包括已过法定期限没有上诉、抗诉的判决和裁定，终审的判决和裁定，最高人民法院核准的死刑判决和高级人民法院核准的死刑缓期2年执行的判决。"},{id:"cs-4419",module:"changshi",prompt:"我国行政诉讼法规定，人民法院审理行政案件，由审判员组成合议庭，或者由审判员和？",options:["人民陪审员组成合议庭", "检察官组成合议庭", "监察官组成合议庭", "律师组成合议庭"],answer:0,explanation:"行政诉讼法规定，人民法院审理行政案件，由审判员组成合议庭，或者由审判员和人民陪审员组成合议庭；合议庭的成员，应当是3人以上的单数。"},{id:"cs-4420",module:"changshi",prompt:"我国行政诉讼法规定，人民法院审理行政案件，认为地方人民政府制定、发布的规章与国务院部、委制定、发布的规章不一致的，以及国务院部、委制定、发布的规章之间不一致的，由最高人民法院送请？",options:["国务院作出解释或者裁决", "全国人大常委会作出解释", "地方人大作出解释", "最高人民检察院作出解释"],answer:0,explanation:"行政诉讼法规定，人民法院认为地方人民政府制定、发布的规章与国务院部、委制定、发布的规章不一致的，以及国务院部、委制定、发布的规章之间不一致的，由最高人民法院送请国务院作出解释或者裁决。"},{id:"cs-4421",module:"changshi",prompt:"我国行政诉讼法规定，人民法院对行政案件宣告判决或者裁定前，原告申请撤诉的，或者被告改变其所作的行政行为，原告同意并申请撤诉的，是否准许，由人民法院？",options:["裁定", "判决", "决定", "通知"],answer:0,explanation:"行政诉讼法规定，人民法院对行政案件宣告判决或者裁定前，原告申请撤诉的，或者被告改变其所作的行政行为，原告同意并申请撤诉的，是否准许，由人民法院裁定。"},{id:"cs-4422",module:"changshi",prompt:"我国民事诉讼法规定，人民法院审理选民资格案件、宣告失踪或者宣告死亡案件等，适用？",options:["特别程序", "普通程序", "简易程序", "再审程序"],answer:0,explanation:"民事诉讼法规定，人民法院审理选民资格案件、宣告失踪或者宣告死亡案件、认定公民无民事行为能力或者限制民事行为能力案件、认定财产无主案件等，适用特别程序；依照特别程序审理的案件，实行一审终审。"},{id:"cs-4423",module:"changshi",prompt:"法律规则的逻辑结构包括假定条件、行为模式和？",options:["法律后果", "法律原则", "法律概念", "法律条文"],answer:0,explanation:"法律规则的逻辑结构包括假定条件、行为模式和法律后果三部分；假定条件是规则适用的条件，行为模式是规则规定的行为方式，法律后果是遵守或违反规则的后果。"},{id:"cs-4424",module:"changshi",prompt:"法律规则按照内容的不同可以分为？",options:["授权性规则和义务性规则", "任意性规则和强制性规则", "确定性规则和委任性规则", "一般规则和特殊规则"],answer:0,explanation:"法律规则按照内容的不同可以分为授权性规则和义务性规则；授权性规则规定人们可以做什么，义务性规则规定人们必须做什么或不得做什么。"},{id:"cs-4425",module:"changshi",prompt:"法律规则按照对人们行为规定和限定的范围或程度的不同可以分为？",options:["强行性规则和任意性规则", "授权性规则和义务性规则", "确定性规则和委任性规则", "基本规则和具体规则"],answer:0,explanation:"法律规则按照对人们行为规定和限定的范围或程度的不同可以分为强行性规则和任意性规则；强行性规则不允许当事人自行协议改变，任意性规则允许当事人自行选择。"},{id:"cs-4426",module:"changshi",prompt:"法律概念的功能不包括？",options:["直接规定权利义务", "表达法律事实", "连接法律规则", "界定法律关系"],answer:0,explanation:"法律概念的功能包括表达法律事实、连接法律规则、界定法律关系等；直接规定权利义务的是法律规则，不是法律概念。"},{id:"cs-4427",module:"changshi",prompt:"法的要素包括法律规则、法律原则和？",options:["法律概念", "法律条文", "法律制度", "法律体系"],answer:0,explanation:"法的要素包括法律规则、法律原则和法律概念；法律规则规定权利义务，法律原则是规则的基础性原理，法律概念是表达法律事实的工具。"},{id:"cs-4428",module:"changshi",prompt:"法律条文与法律规范的关系是？",options:["法律规范是法律条文的内容，法律条文是法律规范的表现形式", "两者完全相同", "法律条文是法律规范的内容", "两者互不相关"],answer:0,explanation:"法律规范是法律条文的内容，法律条文是法律规范的表现形式；一个法律规范可以由多个法律条文表达，一个法律条文也可以表达多个法律规范。"},{id:"cs-4429",module:"changshi",prompt:"法的价值冲突的解决原则不包括？",options:["利益最大化原则", "价值位阶原则", "个案平衡原则", "比例原则"],answer:0,explanation:"法的价值冲突的解决原则包括价值位阶原则、个案平衡原则和比例原则；利益最大化原则不是法的价值冲突的解决原则。"},{id:"cs-4430",module:"changshi",prompt:"法治社会建设的要求不包括？",options:["以权谋私", "全民守法", "公正司法", "严格执法"],answer:0,explanation:"法治社会建设要求全民守法、公正司法、严格执法、科学立法等；以权谋私与法治社会建设要求相悖。"});
(window.YC_CS_BANK=window.YC_CS_BANK||[]).push({id:"cs-4431",module:"changshi",prompt:"从法理学的角度看，法律实施的基础是什么？",options:["法律规范的存在", "司法机关的存在", "行政机关的存在", "政党的存在"],answer:0,explanation:"法律实施的基础是法律规范的存在，没有法律规范就没有法律实施；法律实施是法律规范在社会生活中的具体运用和实现。"});
